CREATE OR REPLACE FUNCTION private.adopt_catalogue_model(p_patient uuid, p_product text)
 RETURNS care_recipient_products
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare model public.products;
begin
  perform private.require_cap(p_patient, 'catalog.manage');
  perform pg_advisory_xact_lock(hashtextextended('catalogue:' || p_patient, 0));
  if not exists (select 1 from public.care_recipients where id = p_patient and is_active) then
    raise exception 'inactive patient' using errcode = '42501';
  end if;
  select * into model from public.products
    where id = p_product and owner_care_recipient_id is null and is_active;
  if not found then raise exception 'template not found'; end if;
  if exists (select 1 from public.care_recipient_products where care_recipient_id = p_patient and product_id = model.id) then
    raise exception 'template already adopted' using errcode = '23505';
  end if;
  return public.admin_upsert_recipient_product(p_patient, model.id, model.name, model.category, model.unit, model.aliases, true);
end;
$function$

CREATE OR REPLACE FUNCTION private.apply_access_change(p_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare c public.access_change_requests;x jsonb;a jsonb;invitation public.care_recipient_invitations;v_hash text;v_email text;begin
 select * into strict c from public.access_change_requests where id=p_id;
 x:=c.proposed;a:=x->'args';
 if not public.can_manage_recipient(c.care_recipient_id) then raise exception 'local administrator required' using errcode='42501';end if;
 if c.kind='membership' and not exists(select 1 from public.care_recipient_memberships where care_recipient_id=c.care_recipient_id and user_id=(x->>'userId')::uuid and status='active') then
 select token_hash into v_hash from private.membership_invitation_intents where backend_pid=pg_backend_pid() and transaction_id=txid_current() and request_id=c.id;
 if v_hash is null then raise exception 'recipient invitation acceptance required' using errcode='23514';end if;
 select email into v_email from auth.users where id=(x->>'userId')::uuid and email_confirmed_at is not null;
 if v_email is null then raise exception 'confirmed intended identity required' using errcode='23514';end if;
 invitation:=public.admin_create_invitation(c.care_recipient_id,lower(v_email),(x->>'role')::public.profile_role,false,false,v_hash,now()+interval '7 days');
 update public.patient_settings set version=version+1,updated_at=now() where care_recipient_id=c.care_recipient_id;
 update public.access_change_requests set status='awaiting_acceptance',decided_at=now(),resolution=jsonb_build_object('invitationId',invitation.id,'invitationHash',v_hash) where id=c.id;
 insert into public.audit_events(actor_id,action,entity_type,entity_id,metadata) values(auth.uid(),'membership.approved.awaiting_acceptance','access_change',c.id,jsonb_build_object('care_recipient_id',c.care_recipient_id,'invitationId',invitation.id));return;
 elsif c.kind='notification_rule' then
 perform public.configure_notification_rule(c.care_recipient_id,x->>'event',x->>'role',array(select jsonb_array_elements_text(x->'channels')),coalesce((x->>'includePdf')::boolean,true),coalesce((x->>'cooldownMinutes')::integer,0),(x->>'quietStart')::integer,(x->>'quietEnd')::integer);
 update public.notification_event_rules set mode=coalesce(x->>'mode','optional') where care_recipient_id=c.care_recipient_id and event=x->>'event' and subject_role=x->>'role';
 elsif c.kind='capability' and x->'enabled'='null'::jsonb then
 delete from public.capability_overrides where care_recipient_id=c.care_recipient_id and capability=x->>'capability' and (subject_role=x->>'subjectRole' or subject_user=(x->>'subjectUser')::uuid);
 elsif c.kind='administration' then
 case x->>'operation'
 when 'recipient' then perform public.admin_upsert_recipient(c.care_recipient_id,a->>'displayName',(a->>'isActive')::boolean,(a->>'isDevelopment')::boolean);
 when 'product' then perform public.admin_upsert_recipient_product(c.care_recipient_id,a->>'id',a->>'name',(a->>'category')::public.product_category,a->>'unit',array(select jsonb_array_elements_text(a->'aliases')),(a->>'isActive')::boolean,a->>'description',coalesce((a->>'sortOrder')::integer,0));
 when 'adoptProduct' then perform public.admin_adopt_product(c.care_recipient_id,a->>'productId');
 when 'membershipStatus' then perform public.admin_set_membership_status(c.care_recipient_id,(a->>'userId')::uuid,a->>'status');
 when 'alertRule' then perform public.configure_stock_alert(c.care_recipient_id,a->>'productId',a->>'location',(a->>'lowThreshold')::numeric,(a->>'criticalThreshold')::numeric,(a->>'isEnabled')::boolean);
 when 'notificationRecipient' then perform public.configure_recipient_notification(c.care_recipient_id,(a->>'recipientUserId')::uuid,a->>'recipientGroup',a->>'channel',a->>'destination',(a->>'isEnabled')::boolean,coalesce((a->>'includeTeamAlerts')::boolean,false));
 else raise exception 'invalid administration operation';end case;
 else perform private.v3_apply_access_change(p_id);return;end if;
 update public.patient_settings set version=version+1,updated_at=now() where care_recipient_id=c.care_recipient_id;
 update public.access_change_requests set status='applied',decided_at=now() where id=p_id;
 insert into public.audit_events(actor_id,action,entity_type,entity_id,metadata) values(auth.uid(),'access.applied','access_change',p_id,jsonb_build_object('care_recipient_id',c.care_recipient_id,'kind',c.kind));
end;$function$

CREATE OR REPLACE FUNCTION private.apply_bal(p_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare d public.operational_documents;l public.document_lines;delta numeric;begin
 select * into strict d from public.operational_documents where id=p_id;
 if d.status='approved' then return;end if;
 if private.team_revision(d.care_recipient_id)<>(d.workflow_data->>'referenceRevision')::bigint then raise exception 'inventory conflict: reference changed; recount' using errcode='P0001';end if;
 for l in select * from public.document_lines where document_id=p_id order by product_id loop
 delta:=l.quantity-private.stock_quantity(d.care_recipient_id,l.product_id,'CARE_TEAM');
 if delta<>0 then perform private.move_stock(d.care_recipient_id,l.product_id,abs(delta),case when delta<0 then 'CARE_TEAM' end,case when delta>0 then 'CARE_TEAM' end,
 'Reconciliação BAL','bal',d.id);end if;
 update public.document_lines set fully_checked=true,accepted_quantity=quantity where id=l.id;
 end loop;
 update public.operational_documents set status='approved',workflow_data=workflow_data||jsonb_build_object('appliedAt',now()) where id=p_id;
end;$function$

CREATE OR REPLACE FUNCTION private.bal_assign(p_patient uuid, p_cycle uuid, p_shift uuid, p_kind text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$declare v_s public.scheduled_shifts;v_id uuid;begin
 select * into v_s from public.scheduled_shifts where care_recipient_id=p_patient and id=p_shift for share;
 if not found or v_s.status<>'published' or v_s.ends_at<=now() or not private.schedule_worker(p_patient,v_s.professional_id)
 or not private.member_can(p_patient,v_s.professional_id,'bal.count') then raise exception 'invalid balance target shift';end if;
 insert into public.bal_assignments(care_recipient_id,cycle_id,shift_id,shift_version,professional_id,starts_at,ends_at,kind)
 values(p_patient,p_cycle,v_s.id,v_s.version,v_s.professional_id,v_s.starts_at,v_s.ends_at,p_kind) returning id into v_id;
 perform private.bal_event(p_patient,p_cycle,v_id,'bal.cycle.assigned','Responsabilidade vinculada ao plantão real',to_jsonb(v_s),'assignment:'||v_id);
 return v_id;end;$function$

CREATE OR REPLACE FUNCTION private.bal_count_context(p_patient uuid, p_document uuid, p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_a public.bal_assignments;v_c public.bal_cycles;v_s public.scheduled_shifts;begin
 perform private.require_cap(p_patient,'bal.count');
 perform pg_advisory_xact_lock(hashtextextended('stock:'||p_patient,0)); if nullif(p_payload->'balanceAssignment'->>'referenceRevision','') is null or (p_payload->'balanceAssignment'->>'referenceRevision')::bigint<>private.team_revision(p_patient) then raise exception 'inventory reference changed' using errcode='P0001';end if;
 perform pg_advisory_xact_lock(hashtextextended('bal:'||p_patient,0));
 select * into v_a from public.bal_assignments where care_recipient_id=p_patient and id=(p_payload->'balanceAssignment'->>'id')::uuid for update;
 if not found or v_a.status<>'active' or v_a.version is distinct from (p_payload->'balanceAssignment'->>'version')::integer
 or v_a.professional_id<>auth.uid() or not private.schedule_worker(p_patient,auth.uid()) or v_a.starts_at>now() or v_a.ends_at<=now() then raise exception 'balance shift authorization required' using errcode='42501';end if;
 select * into v_s from public.scheduled_shifts where id=v_a.shift_id for share;
 if v_s.status<>'published' or v_s.version<>v_a.shift_version then raise exception 'stale balance assignment';end if;
 select * into strict v_c from public.bal_cycles where id=v_a.cycle_id for update;
 if (p_document is null and v_c.document_id is not null) or (p_document is not null and v_c.document_id is distinct from p_document) then raise exception 'existing balance document requires revision' using errcode='P0001';end if;
 return jsonb_build_object('cycleId',v_c.id,'assignmentId',v_a.id,'assignmentVersion',v_a.version,'shiftId',v_s.id,'shiftType',(select name from public.shift_types where id=v_s.shift_type_id),
 'professionalId',v_a.professional_id,'professionalName',(select full_name from public.profiles where id=v_a.professional_id),'startsAt',v_a.starts_at,'endsAt',v_a.ends_at,'timezone',v_s.timezone,
 'countedAt',now(),'weeks',(select jsonb_agg(week_start order by week_start) from public.bal_obligations where cycle_id=v_c.id),'kind',v_a.kind);
end;$function$

CREATE OR REPLACE FUNCTION private.bal_event(p_patient uuid, p_cycle uuid, p_assignment uuid, p_action text, p_reason text, p_details jsonb, p_key text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$declare v_eid uuid;v_rid uuid;v_m record;v_worker uuid;begin
 insert into public.bal_cycle_events(care_recipient_id,cycle_id,assignment_id,event_key,action,reason,details,actor_id)
 values(p_patient,p_cycle,p_assignment,p_key,p_action,p_reason,p_details,auth.uid()) on conflict do nothing returning id into v_eid;
 if v_eid is null then return;end if;
 select professional_id into v_worker from public.bal_assignments where id=p_assignment;
 for v_m in select user_id,role from public.care_recipient_memberships where care_recipient_id=p_patient and status='active'
 and (user_id=v_worker or role in ('admin','family','supervisor')) loop
 if not private.member_can(p_patient,v_m.user_id,'bal.read') then continue;end if;
 insert into public.operational_reminders(care_recipient_id,user_id,kind,period,expected_at,bal_event_id)
 values(p_patient,v_m.user_id,'bal_cycle',current_date,now(),v_eid) returning id into v_rid;
 perform private.enqueue_notice(p_patient,v_m.user_id,p_action,p_reminder=>v_rid);
 end loop;end;$function$

CREATE OR REPLACE FUNCTION private.credit_purchase_receipt(p_receipt uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare r public.purchase_receipts;d public.operational_documents;x jsonb;l public.document_lines;q numeric;begin
 select * into strict r from public.purchase_receipts where id=p_receipt for update;
 if r.state='approved' then return;end if;
 select * into strict d from public.operational_documents where id=r.document_id;
 for x in select value from jsonb_array_elements(r.lines) loop
 select * into strict l from public.document_lines where id=(x->>'lineId')::uuid and document_id=d.id;
 q:=(x->>'quantity')::numeric;
 if q<=0 or l.accepted_quantity+q>l.purchased_quantity then raise exception 'invalid receipt quantity';end if;
 perform private.move_stock(d.care_recipient_id,l.product_id,q,null,'FAMILY','Recebimento COM validado','purchase_receipt',r.id);
 update public.document_lines set accepted_quantity=accepted_quantity+q,fully_checked=accepted_quantity+q=approved_quantity where id=l.id;
 end loop;
 update public.purchase_receipts set state='approved',validated_by=auth.uid(),validated_at=now() where id=r.id;
 update public.operational_documents set status=case when not exists(select 1 from public.document_lines where document_id=d.id and accepted_quantity<approved_quantity) then 'received' else 'partially_received' end where id=d.id;
end;$function$

CREATE OR REPLACE FUNCTION private.delivery_science_and_progress()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare d public.operational_documents;r record;s public.requisition_lifecycle;begin
 select * into d from public.operational_documents where id=new.document_id;
 if d.type<>'ENT' then return new;end if;
 for r in select distinct i.requisition_id from public.document_request_links k join public.document_lines l on l.id=k.document_line_id join public.requisition_items i on i.id=k.requisition_item_id where l.document_id=d.id loop
 select * into s from public.requisition_lifecycle where requisition_id=r.requisition_id;
 if new.action in ('ent.issued','ent.submit') and coalesce((s.policy->>'scienceByDispatch')::boolean,true)
 and d.status='pending_receipt' and auth.uid()=d.created_by and auth.uid()=any(s.eligible_users) then
 perform private.record_science(r.requisition_id,auth.uid(),'dispatch',jsonb_build_object('deliveryId',d.id,'deliveryVersion',new.version,'sessionId',private.auth_session()));end if;
 perform private.refresh_requisition_lifecycle(r.requisition_id);
 end loop;return new;
end;$function$

CREATE OR REPLACE FUNCTION private.emit_document(p_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare d public.operational_documents;n bigint;
begin
 select * into strict d from public.operational_documents where id=p_id for update;
 if d.code is not null then return;end if;
 insert into public.document_series(care_recipient_id,type,last_number) values(d.care_recipient_id,d.type,1)
 on conflict(care_recipient_id,type) do update set last_number=public.document_series.last_number+1 returning last_number into n;
 update public.operational_documents set number=n,code=d.type||'-'||lpad(n::text,greatest(4,length(n::text)),'0'),
 protocol=d.type||'-'||to_char(now() at time zone 'America/Sao_Paulo','YYYYMMDD')||'-'||upper(left(replace(d.care_recipient_id::text,'-',''),8))||'-'||upper(left(replace(d.created_by::text,'-',''),8))||'-'||n||'-'||upper(left(encode(extensions.digest(p_id::text,'sha256'),'hex'),8)) where id=p_id;
end;$function$

CREATE OR REPLACE FUNCTION private.enqueue_document_event()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare d public.operational_documents;m record;event_name text;pdf boolean;begin
 if new.action in ('req.legacy_imported','attachment.reserved','attachment.ready','attachment.rejected','attachment.bound') then return new;end if;
 select * into strict d from public.operational_documents where id=new.document_id;if d.status='draft' then return new;end if;
 if new.action='req.fulfillment_updated' and (coalesce((new.body->'event'->>'fulfilled')::integer,0)=0 or (new.body->'event'->>'fulfilled')::integer=(new.body->'event'->>'total')::integer) then return new;end if;
 for m in select user_id,role from public.care_recipient_memberships where care_recipient_id=d.care_recipient_id and status='active' loop
 if not private.member_can(d.care_recipient_id,m.user_id,lower(d.type)||'.read') then continue;end if;
 if m.role='reader' and not exists(select 1 from public.notification_event_rules where care_recipient_id=d.care_recipient_id and event=new.action and subject_role='reader' and cardinality(channels)>0) and not exists(select 1 from public.recipient_notification_settings where care_recipient_id=d.care_recipient_id and recipient_user_id=m.user_id and is_enabled) then continue;end if;
 if new.action in ('ent.issued','ent.submit') and m.role in ('professional','supervisor') and m.user_id<>d.recipient_id then continue;end if;
 if new.action in ('req.science_satisfied','req.science_recorded') and m.user_id<>d.created_by and m.role not in ('admin','family') then continue;end if;
 if new.action like 'req.archived.%' and m.role not in ('admin','family') then continue;end if;
 if new.action='req.reminder' and m.role not in ('admin','family') then continue;end if;
 if new.action='ent.reminder' and m.user_id<>d.recipient_id then continue;end if;
 if new.action='req.issued' and m.user_id<>d.created_by and m.role not in ('admin','family','supervisor') and not exists(select 1 from public.recipient_notification_settings where care_recipient_id=d.care_recipient_id and recipient_user_id=m.user_id and is_enabled) and not exists(select 1 from public.notification_event_rules where care_recipient_id=d.care_recipient_id and event=new.action and subject_role=m.role::text and cardinality(channels)>0) then continue;end if;
 event_name:=case when new.action='req.issued' and m.user_id=d.created_by then 'req.registered_author' else new.action end;
 select coalesce(include_pdf,true) into pdf from public.notification_event_rules where care_recipient_id=d.care_recipient_id and event=event_name and subject_role=m.role::text;
 if event_name='req.science_satisfied' and m.user_id=d.created_by then pdf:=true;end if;
 perform private.enqueue_notice(d.care_recipient_id,m.user_id,event_name,d.id,new.id,null,null,null,coalesce(pdf,true));
 end loop;return new;
end;$function$

CREATE OR REPLACE FUNCTION private.enqueue_notice(p_patient uuid, p_user uuid, p_event text, p_document uuid DEFAULT NULL::uuid, p_document_event uuid DEFAULT NULL::uuid, p_alert uuid DEFAULT NULL::uuid, p_report uuid DEFAULT NULL::uuid, p_reminder uuid DEFAULT NULL::uuid, p_pdf boolean DEFAULT false)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare person public.profiles;m public.care_recipient_memberships;r public.notification_event_rules;channels text[];v_channel text;destination text;due timestamptz:=now();local_now timestamp:=now() at time zone 'America/Sao_Paulo';h integer;g text;required boolean;begin
 select * into person from public.profiles where id=p_user and status='active';if not found then return;end if;
 select * into m from public.care_recipient_memberships where care_recipient_id=p_patient and user_id=p_user and status='active';if not found then return;end if;
 select * into r from public.notification_event_rules where care_recipient_id=p_patient and event=case p_event when 'com.submit' then 'com.issued' when 'ent.submit' then 'ent.issued' else p_event end and subject_role=m.role::text;
 channels:=case when found then r.channels else array(select distinct v from (select 'internal'::text v union select x.channel from public.recipient_notification_settings x where x.care_recipient_id=p_patient and x.recipient_user_id=p_user and x.is_enabled) c) end;
 required:=r.mode='required';if required and not('internal'=any(channels)) then channels:=array_append(channels,'internal');end if;
 if r.mode='silent' then channels:=array['internal'];end if;
 g:=case m.role when 'family' then 'family' when 'supervisor' then 'supervision' when 'professional' then 'care_team' else 'other' end;
 h:=extract(hour from local_now);
 if r.quiet_start is not null and r.quiet_end is not null and (r.quiet_start<=r.quiet_end and h>=r.quiet_start and h<r.quiet_end or r.quiet_start>r.quiet_end and (h>=r.quiet_start or h<r.quiet_end)) then
 due:=(date_trunc('day',local_now)+make_interval(hours=>r.quiet_end)+case when r.quiet_start>r.quiet_end and h>=r.quiet_start then interval '1 day' else interval '0' end) at time zone 'America/Sao_Paulo';end if;
 foreach v_channel in array channels loop
 if v_channel='internal' then
 if not coalesce(required,false) and not coalesce((person.notification_preferences->>'internal')::boolean,true) then continue;end if;
 destination:=null;
 else
 if not coalesce((person.notification_preferences->>v_channel)::boolean,false) then continue;end if;
 select s.destination into destination from public.recipient_notification_settings s where care_recipient_id=p_patient and recipient_user_id=p_user and s.channel=v_channel and is_enabled;
 if destination is null then continue;end if;
 if v_channel='email' and not exists(select 1 from auth.users u where u.id=p_user and u.email_confirmed_at is not null and lower(u.email)=lower(destination)) then continue;end if;
 if v_channel='whatsapp' and not exists(select 1 from public.verified_phones v join auth.users u on u.id=v.user_id where v.user_id=p_user and '+'||ltrim(u.phone,'+')=v.phone and u.phone_confirmed_at is not null and ltrim(v.phone,'+')=ltrim(destination,'+')) then continue;end if;
 end if;
 if coalesce(r.cooldown_minutes,0)>0 and exists(select 1 from public.requisition_notifications n where n.care_recipient_id=p_patient and n.recipient_user_id=p_user and n.event_key=p_event and n.channel=v_channel
 and coalesce(n.document_id,n.alert_event_id,n.consumption_report_id,n.reminder_id)=coalesce(p_document,p_alert,p_report,p_reminder) and n.created_at>now()-make_interval(mins=>r.cooldown_minutes)) then continue;end if;
 insert into public.requisition_notifications(care_recipient_id,document_id,document_event_id,alert_event_id,consumption_report_id,reminder_id,recipient_user_id,recipient_group,recipient_label,channel,destination,event_key,include_pdf,next_attempt_at,silent)
 values(p_patient,p_document,p_document_event,p_alert,p_report,p_reminder,p_user,g,person.full_name,v_channel,destination,p_event,p_event<>'req.registered_author' and p_pdf,case when v_channel='internal' then now() else due end,coalesce(r.mode='silent',false)) on conflict do nothing;
 end loop;
end;$function$

CREATE OR REPLACE FUNCTION private.enqueue_scheduled_reminders()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare s record;user_id uuid;rid uuid;today date:=(now() at time zone 'America/Sao_Paulo')::date;clock_hour integer:=extract(hour from now() at time zone 'America/Sao_Paulo');n integer:=0;begin
 for s in select p.care_recipient_id,p.settings from public.patient_settings p join public.care_recipients c on c.id=p.care_recipient_id where c.is_active and (p.settings ? 'balReminderUsers' or p.settings ? 'shiftReminder') limit 100 loop
 if not exists(select 1 from public.bal_regimes br where br.care_recipient_id=s.care_recipient_id and br.enabled) and s.settings->>'balDay' is not null and (s.settings->>'balDay')::integer=extract(dow from today) and clock_hour>=9 then
 for user_id in select value::uuid from jsonb_array_elements_text(coalesce(s.settings->'balReminderUsers','[]')) loop
 if not private.member_can(s.care_recipient_id,user_id,'bal.count') then continue;end if;
 insert into public.operational_reminders(care_recipient_id,user_id,kind,period,expected_at) values(s.care_recipient_id,user_id,'bal',today,(today+time '09:00') at time zone 'America/Sao_Paulo') on conflict do nothing returning id into rid;
 if rid is not null then perform private.enqueue_notice(s.care_recipient_id,user_id,'bal.reminder',null,null,null,null,rid);n:=n+1;end if;end loop;end if;
 if coalesce((s.settings->'shiftReminder'->>'enabled')::boolean,false) and clock_hour>=coalesce((s.settings->'shiftReminder'->>'hour')::integer,19)
 and coalesce(s.settings->'shiftReminder'->'days','[]') ? extract(dow from today)::text then
 for user_id in select value::uuid from jsonb_array_elements_text(coalesce(s.settings->'shiftReminder'->'userIds','[]')) loop
 if not private.member_can(s.care_recipient_id,user_id,'consumption.report') then continue;end if;
 insert into public.operational_reminders(care_recipient_id,user_id,kind,period,expected_at) values(s.care_recipient_id,user_id,'shift',today,(today+make_time((s.settings->'shiftReminder'->>'hour')::integer,0,0)) at time zone 'America/Sao_Paulo') on conflict do nothing returning id into rid;
 if rid is not null then perform private.enqueue_notice(s.care_recipient_id,user_id,'shift.reminder',null,null,null,null,rid);n:=n+1;end if;end loop;end if;
 end loop;return n;
end;$function$

CREATE OR REPLACE FUNCTION private.finish_bal_count(p_id uuid, p_context jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_cycle uuid:=(p_context->>'cycleId')::uuid;v_assignment uuid:=(p_context->>'assignmentId')::uuid;v_current_week date:=date_trunc('week',now() at time zone (p_context->>'timezone'))::date;begin
 update public.bal_cycles set document_id=p_id,state='counted',counted_at=now() where id=v_cycle;
 update public.bal_assignments set status='counted',version=version+1 where id=v_assignment;
 update public.bal_obligations set state=case when week_start=v_current_week then 'counted' else 'regularized' end,
 count_document_id=case when week_start=v_current_week then p_id end,regularized_by=case when week_start<>v_current_week then p_id end,
 actual_count_at=now() where cycle_id=v_cycle and state='pending';
 update public.bal_deferrals set status='stale',decided_at=now() where cycle_id=v_cycle and status='pending';
 perform private.bal_event((select care_recipient_id from public.bal_cycles where id=v_cycle),v_cycle,v_assignment,'bal.cycle.counted','Contagem física atual registrada; atrasos anteriores preservados',p_context,'count:'||p_id||':'||(select version from public.operational_documents where id=p_id));
end;$function$

CREATE OR REPLACE FUNCTION private.guard_membership_elevation()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
 if auth.uid() is null and current_user<>'authenticated' then return new;end if;
 if tg_op='UPDATE' and old.role='admin' and old.status='active' and (new.role<>'admin' or new.status<>'active') and not exists(select 1 from public.care_recipient_memberships m join public.profiles p on p.id=m.user_id where m.care_recipient_id=old.care_recipient_id and m.user_id<>old.user_id and m.role='admin' and m.status='active' and p.status='active') then raise exception 'last patient administrator must remain active' using errcode='23514';end if;
 if exists(select 1 from private.membership_authority a where a.backend_pid=pg_backend_pid() and a.transaction_id=txid_current() and a.care_recipient_id=new.care_recipient_id and a.user_id=new.user_id and a.role=new.role and a.manage_stock=new.can_manage_stock and a.count_stock=new.can_count_stock and new.status='active') then return new;end if;
 if not public.can_manage_recipient(new.care_recipient_id) then raise exception 'local administrator required' using errcode='42501';end if;return new;
end;$function$

CREATE OR REPLACE FUNCTION private.init_requisition_science(p_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare d public.operational_documents;s jsonb;targets uuid[];begin
 select * into strict d from public.operational_documents where id=p_id and type='REQ';
 if exists(select 1 from public.requisition_lifecycle where requisition_id=p_id) then return;end if;
 select coalesce(settings,'{}') into s from public.patient_settings where care_recipient_id=d.care_recipient_id;
 s:='{"scienceRequired":true,"scienceRoles":["admin","family"],"scienceUsers":[],"scienceRequirement":"any","scienceByDispatch":true,"scienceAutomatic":false,"archiveDays":7,"reminderHours":2,"reminderRepeatHours":24}'::jsonb||coalesce(s,'{}');
 select coalesce(array_agg(m.user_id),'{}') into targets from public.care_recipient_memberships m join public.profiles p on p.id=m.user_id
 where m.care_recipient_id=d.care_recipient_id and m.status='active' and p.status='active'
 and (s->'scienceRoles' ? m.role::text or s->'scienceUsers' ? m.user_id::text) and private.member_can(d.care_recipient_id,m.user_id,'req.science');
 insert into public.requisition_lifecycle(requisition_id,care_recipient_id,policy,eligible_users,next_reminder_at)
 values(p_id,d.care_recipient_id,s,targets,now()+make_interval(hours=>(s->>'reminderHours')::integer));
end;$function$

CREATE OR REPLACE FUNCTION private.invalidate_workspace()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare row_data jsonb;pid uuid;u uuid;n bigint;
begin
 row_data:=case when tg_op='DELETE' then to_jsonb(old) else to_jsonb(new) end;
 pid:=(row_data->>'care_recipient_id')::uuid;
 for u in
  select affected.user_id from (
   select user_id from public.care_recipient_memberships where care_recipient_id=pid and status='active'
   union select (row_data->>'user_id')::uuid where row_data->>'user_id' is not null
  ) affected order by affected.user_id
 loop
  insert into private.workspace_revisions(user_id,revision) values(u,1)
  on conflict(user_id) do update set revision=private.workspace_revisions.revision+1 returning revision into n;
  perform realtime.send(jsonb_build_object('revision',n),'invalidate','hca:user:'||u::text,true);
 end loop;
 return null;
end;
$function$

CREATE OR REPLACE FUNCTION private.invoke_notification_worker()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare endpoint text;bearer text;begin
 select decrypted_secret into endpoint from vault.decrypted_secrets where name='hca_worker_url';
 select decrypted_secret into bearer from vault.decrypted_secrets where name='hca_worker_bearer';
 if endpoint is distinct from 'https://home-care-assistant.vercel.app/api/notifications/worker' or length(coalesce(bearer,''))<32 then return;end if;
 perform net.http_post(url:=endpoint,headers:=jsonb_build_object('content-type','application/json','authorization','Bearer '||bearer),body:='{}'::jsonb,timeout_milliseconds:=120000);
end;$function$

CREATE OR REPLACE FUNCTION private.member_can(p_patient uuid, p_user uuid, p_capability text)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare r text;v boolean;begin
 select m.role::text into r from public.care_recipient_memberships m join public.profiles p on p.id=m.user_id
 where m.care_recipient_id=p_patient and m.user_id=p_user and m.status='active' and p.status='active';
 if r is null then return false;end if;
 if p_capability in ('bal.defer.approve','bal.schedule.manage','bal.approve.family') and r not in ('admin','family') then return false;end if;
 if p_capability='bal.count' and r not in ('professional','supervisor') and exists(select 1 from public.bal_regimes where care_recipient_id=p_patient and activated_at is not null) then return false;end if;
 if p_capability='access.manage' then return r='admin';end if;
 if p_capability like 'com.%' and r not in ('admin','family') then return false;end if;
 select enabled into v from public.capability_overrides where care_recipient_id=p_patient and capability=p_capability and subject_user=p_user;
 if found then return v;end if;
 select enabled into v from public.capability_overrides where care_recipient_id=p_patient and capability=p_capability and subject_role=r;
 if found then return v;end if;
 return coalesce((select r=any(default_roles) from public.capability_definitions where code=p_capability),false);
end;$function$

CREATE OR REPLACE FUNCTION private.process_bal_patient(p_patient uuid, p_now timestamp with time zone DEFAULT now())
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_r public.bal_regimes;v_type public.shift_types;v_c public.bal_cycles;v_a public.bal_assignments;v_s public.scheduled_shifts;
 v_week date;v_today date;v_day date;v_start timestamptz;v_due timestamptz;v_floor timestamptz;v_matches integer;v_sid uuid;v_late record;v_cycles integer:=0;v_i integer;v_was_missed boolean:=false;
begin
 perform pg_advisory_xact_lock(hashtextextended('bal:'||p_patient,0));
 select * into v_r from public.bal_regimes where care_recipient_id=p_patient and enabled;
 if not found or not exists(select 1 from public.care_recipients where id=p_patient and is_active) then return 0;end if;
 select * into strict v_type from public.shift_types where id=v_r.shift_type_id;
 v_today:=(p_now at time zone v_r.timezone)::date;
 v_week:=coalesce((select max(week_start)+7 from public.bal_obligations where care_recipient_id=p_patient),date_trunc('week',v_r.starts_on::timestamp)::date);
 -- Bounded historical catch-up; future runs continue from the same unique weeks.
 for v_i in 0..105 loop
 exit when v_week>v_today;
 v_day:=v_week+((v_r.weekday+6)%7);
 if v_day<v_r.starts_on then v_week:=v_week+7;continue;end if;
 v_start:=(v_day+v_type.starts_local) at time zone v_r.timezone;v_due:=v_start+make_interval(mins=>v_type.duration_minutes);
 select count(*),min(s.starts_at),min(s.ends_at) into v_matches,v_floor,v_due from public.scheduled_shifts s
 where s.care_recipient_id=p_patient and s.status='published' and s.shift_type_id=v_r.shift_type_id
 and (s.starts_at at time zone v_r.timezone)::date=v_day
 and (v_r.designated_professional_id is null or s.professional_id=v_r.designated_professional_id)
 and private.schedule_worker(p_patient,s.professional_id) and private.member_can(p_patient,s.professional_id,'bal.count');
 if v_matches=1 then v_start:=v_floor;else v_due:=v_start+make_interval(mins=>v_type.duration_minutes);end if;
 if v_start>p_now then v_week:=v_week+7;continue;end if;
 if not exists(select 1 from public.bal_obligations where care_recipient_id=p_patient and week_start=v_week) then
 select * into v_c from public.bal_cycles where care_recipient_id=p_patient and state='open' for update;
 if not found then insert into public.bal_cycles(care_recipient_id) values(p_patient) returning * into v_c;end if;
 insert into public.bal_obligations(care_recipient_id,cycle_id,week_start,original_start,original_due,effective_due,regime_snapshot)
 values(p_patient,v_c.id,v_week,v_start,v_due,v_due,to_jsonb(v_r));
 perform private.bal_event(p_patient,v_c.id,null,'bal.cycle.opened','Obrigação semanal disponibilizada',jsonb_build_object('weekStart',v_week,'dueAt',v_due),'week:'||v_week);
 end if;v_week:=v_week+7;
 end loop;
 -- Handle both open cycles and formal recount assignments on counted cycles.
 for v_c in select * from public.bal_cycles c where care_recipient_id=p_patient and (state='open' or exists(select 1 from public.bal_assignments a where a.cycle_id=c.id and a.status='active')) order by created_at loop
 v_floor:=greatest(coalesce((select min(original_start) from public.bal_obligations where cycle_id=v_c.id),p_now),coalesce((select max(ends_at) from public.bal_assignments where cycle_id=v_c.id and status='missed'),'-infinity'::timestamptz));
 v_was_missed:=exists(select 1 from public.bal_assignments where cycle_id=v_c.id and status='missed');
 for v_i in 0..100 loop
 select * into v_a from public.bal_assignments where care_recipient_id=p_patient and cycle_id=v_c.id and status='active' for update;
 if found then
 select * into v_s from public.scheduled_shifts where id=v_a.shift_id;
 if v_a.ends_at<=p_now then
 update public.bal_assignments set status='missed',missed_at=v_a.ends_at,version=version+1 where id=v_a.id;
 update public.bal_obligations set missed_at=coalesce(missed_at,effective_due) where cycle_id=v_c.id and state='pending' and effective_due<=p_now;
 perform private.bal_event(p_patient,v_c.id,v_a.id,'bal.cycle.missed','Plantão encerrado sem contagem',jsonb_build_object('deadline',v_a.ends_at,'professionalId',v_a.professional_id),'missed:'||v_a.id);
 v_floor:=v_a.ends_at;v_was_missed:=true;
 elsif v_s.status<>'published' or v_s.version<>v_a.shift_version or not private.schedule_worker(p_patient,v_a.professional_id) or not private.member_can(p_patient,v_a.professional_id,'bal.count') then
 update public.bal_assignments set status='invalidated',version=version+1 where id=v_a.id;
 perform private.bal_event(p_patient,v_c.id,v_a.id,'bal.cycle.invalidated','Escala ou autorização alterada; atribuição anterior preservada','{}','invalidated:'||v_a.id);
 v_floor:=greatest(v_floor,p_now-interval '24 hours');
 else
 if v_a.starts_at<=p_now then perform private.bal_event(p_patient,v_c.id,v_a.id,'bal.cycle.available','Contagem disponível no período programado',jsonb_build_object('startsAt',v_a.starts_at,'dueAt',v_a.ends_at),'available:'||v_a.id);end if;
 exit;end if;
 end if;
 update public.bal_deferrals d set status='stale',decided_at=p_now where d.cycle_id=v_c.id and d.status='pending'
 and (not exists(select 1 from public.bal_assignments a where a.id=d.assignment_id and a.status='active' and a.version=d.assignment_version) or not exists(select 1 from public.scheduled_shifts s where s.id=d.target_shift_id and s.status='published' and s.version=d.target_shift_version));
 if v_c.state='counted' then exit;end if;
 if exists(select 1 from public.bal_assignments where care_recipient_id=p_patient and status='active') then exit;end if;
 -- Never choose arbitrarily between simultaneous eligible professionals.
 select min(s.starts_at) into v_start from public.scheduled_shifts s where s.care_recipient_id=p_patient and s.status='published'
 and s.starts_at>=v_floor and not exists(select 1 from public.bal_assignments a where a.cycle_id=v_c.id and a.shift_id=s.id and (a.status<>'invalidated' or a.shift_version=s.version))
 and (exists(select 1 from public.bal_assignments where cycle_id=v_c.id) or p_now>=(select min(effective_due) from public.bal_obligations where cycle_id=v_c.id)
 or s.shift_type_id=v_r.shift_type_id and (s.starts_at at time zone v_r.timezone)::date=(v_floor at time zone v_r.timezone)::date and (v_r.designated_professional_id is null or s.professional_id=v_r.designated_professional_id))
 and private.schedule_worker(p_patient,s.professional_id) and private.member_can(p_patient,s.professional_id,'bal.count');
 select count(*),min(s.id::text)::uuid into v_matches,v_sid from public.scheduled_shifts s where s.care_recipient_id=p_patient and s.status='published' and s.starts_at=v_start
 and (exists(select 1 from public.bal_assignments where cycle_id=v_c.id) or p_now>=(select min(effective_due) from public.bal_obligations where cycle_id=v_c.id)
 or s.shift_type_id=v_r.shift_type_id and (s.starts_at at time zone v_r.timezone)::date=(v_floor at time zone v_r.timezone)::date and (v_r.designated_professional_id is null or s.professional_id=v_r.designated_professional_id))
 and private.schedule_worker(p_patient,s.professional_id) and private.member_can(p_patient,s.professional_id,'bal.count')
 and not exists(select 1 from public.bal_assignments a where a.cycle_id=v_c.id and a.shift_id=s.id and (a.status<>'invalidated' or a.shift_version=s.version));
 if v_matches<>1 then
 perform private.bal_event(p_patient,v_c.id,null,'bal.cycle.unassigned','Sem próximo plantão único elegível; exige solução autorizada',jsonb_build_object('ambiguous',v_matches>1),'unassigned:'||v_c.id||':'||v_floor);
 exit;end if;
 select * into v_s from public.scheduled_shifts where id=v_sid;
 -- Past assignments are recorded without pretending they are currently executable.
 insert into public.bal_assignments(care_recipient_id,cycle_id,shift_id,shift_version,professional_id,starts_at,ends_at,kind)
 values(p_patient,v_c.id,v_sid,v_s.version,v_s.professional_id,v_s.starts_at,v_s.ends_at,case when v_was_missed or exists(select 1 from public.bal_assignments where cycle_id=v_c.id) then 'transfer' else 'scheduled' end) returning * into v_a;
 perform private.bal_event(p_patient,v_c.id,v_a.id,'bal.cycle.assigned','Responsabilidade vinculada ao plantão real',to_jsonb(v_s),'assignment:'||v_a.id);
 v_cycles:=v_cycles+1;
 if v_s.ends_at>p_now then exit;end if;
 end loop;end loop;
 for v_late in update public.bal_obligations set missed_at=effective_due where care_recipient_id=p_patient and state='pending' and missed_at is null and effective_due<=p_now returning * loop
 perform private.bal_event(p_patient,v_late.cycle_id,null,'bal.cycle.overdue','Prazo do balanço ultrapassado; obrigação preservada',jsonb_build_object('originalDue',v_late.original_due,'effectiveDue',v_late.effective_due),'overdue:'||v_late.id);end loop;return v_cycles;
end;$function$

CREATE OR REPLACE FUNCTION private.record_science(p_id uuid, p_user uuid, p_mode text, p_evidence jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare s public.requisition_lifecycle;is_satisfied boolean;eid uuid;patient_id uuid;begin
 if exists(select 1 from public.requisitions where id=p_id and is_historical) then return false;end if;
 select care_recipient_id into patient_id from public.requisition_lifecycle where requisition_id=p_id;
 perform pg_advisory_xact_lock(hashtextextended('stock:'||patient_id,0));
 select * into strict s from public.requisition_lifecycle where requisition_id=p_id for update;
 if s.archived_at is not null or not(p_user=any(s.eligible_users)) or not private.member_can(s.care_recipient_id,p_user,'req.science') then return false;end if;
 insert into public.requisition_science_events(requisition_id,care_recipient_id,user_id,actor_name,mode,evidence)
 values(p_id,s.care_recipient_id,p_user,(select full_name from public.profiles where id=p_user),p_mode,p_evidence)
 on conflict(requisition_id,user_id) do nothing returning id into eid;
 if eid is null then return false;end if;
 is_satisfied:=private.science_satisfied(p_id);
 update public.requisition_lifecycle set science_satisfied_at=case when is_satisfied then coalesce(science_satisfied_at,now()) else science_satisfied_at end where requisition_id=p_id;
 update public.operational_documents set version=version+1 where id=p_id;
 perform private.record_document_event(p_id,case when is_satisfied and s.science_satisfied_at is null then 'req.science_satisfied' else 'req.science_recorded' end,
 jsonb_build_object('scienceEventId',eid,'userId',p_user,'mode',p_mode,'evidence',p_evidence),gen_random_uuid());
 return true;
end;$function$

CREATE OR REPLACE FUNCTION private.refresh_requisition_lifecycle(p_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare s public.requisition_lifecycle;total integer;fulfilled integer;blocked boolean;current_state jsonb;changed boolean;begin
 select * into s from public.requisition_lifecycle where requisition_id=p_id for update;
 if not found then return;end if;
 select count(*),count(*) filter(where exists(select 1 from public.document_request_links k join public.document_lines l on l.id=k.document_line_id join public.operational_documents d on d.id=l.document_id
 where k.requisition_item_id=i.id and d.type='ENT' and d.status<>'cancelled' and l.accepted_quantity>0)) into total,fulfilled
 from public.requisition_items i where i.requisition_id=p_id;
 select exists(select 1 from public.document_request_links k join public.requisition_items i on i.id=k.requisition_item_id join public.document_lines l on l.id=k.document_line_id join public.operational_documents d on d.id=l.document_id
 where i.requisition_id=p_id and d.type='ENT' and (d.status='cancellation_pending' or coalesce((l.metadata->>'issueOpen')::boolean,false))) into blocked;

 select coalesce(jsonb_agg(jsonb_build_object('itemId',i.id,'deliveryId',d.id,'lineId',l.id,'accepted',l.accepted_quantity::text,'reconciled',l.reconciled_quantity::text,'issueOpen',coalesce((l.metadata->>'issueOpen')::boolean,false),'status',d.status) order by i.id,d.id,l.id),'[]') into current_state
 from public.requisition_items i join public.document_request_links k on k.requisition_item_id=i.id join public.document_lines l on l.id=k.document_line_id join public.operational_documents d on d.id=l.document_id and d.type='ENT' where i.requisition_id=p_id;
 changed:=current_state is distinct from s.fulfillment_state;
 if changed then
 update public.requisition_lifecycle set fulfillment_state=current_state where requisition_id=p_id;
 if (total>0 and total=fulfilled and not blocked)=(s.completed_at is not null) then
 update public.operational_documents set version=version+1 where id=p_id;
 perform private.record_document_event(p_id,'req.fulfillment_updated',jsonb_build_object('fulfilled',fulfilled,'total',total,'operationalIssue',blocked),gen_random_uuid());end if;end if;
 if total>0 and total=fulfilled and not blocked then
 if s.completed_at is null then
 update public.requisition_lifecycle set completed_at=now(),manual_archive_required=manual_archive_required or not coalesce(private.science_satisfied(p_id),false) where requisition_id=p_id;
 update public.operational_documents set version=version+1 where id=p_id;
 perform private.record_document_event(p_id,'req.completed',jsonb_build_object('fulfilled',fulfilled,'total',total,'sciencePending',not coalesce(private.science_satisfied(p_id),false)),gen_random_uuid());end if;
 elsif s.completed_at is not null then
 update public.requisition_lifecycle set completed_at=null,manual_archive_required=true,archived_at=null,archived_by=null,archive_reason=null where requisition_id=p_id;
 update public.operational_documents set version=version+1 where id=p_id;
 perform private.record_document_event(p_id,'req.reopened',jsonb_build_object('fulfilled',fulfilled,'total',total,'operationalIssue',blocked,'previousArchivedAt',s.archived_at,'previousArchiveReason',s.archive_reason),gen_random_uuid());
 end if;
end;$function$

CREATE OR REPLACE FUNCTION private.scheduled_operations()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare prior text:=current_setting('request.jwt.claims',true);begin
 perform set_config('request.jwt.claims','{"role":"service_role"}',true);
 perform public.run_operational_schedule();perform private.deliver_internal_notifications();
 perform set_config('request.jwt.claims',coalesce(prior,''),true);
exception when others then perform set_config('request.jwt.claims',coalesce(prior,''),true);raise;
