CREATE OR REPLACE FUNCTION private.science_snapshot()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare d public.operational_documents;begin
 select * into strict d from public.operational_documents where id=new.document_id;
 new.actor_name:=(select full_name from public.profiles where id=new.actor_id);
 new.authority_context:=case when new.actor_id is null then jsonb_build_object('mode','system') else coalesce(public.my_active_context(),(select jsonb_build_object('mode','verified_external','purpose',w.purpose) from private.worker_authority w where w.backend_pid=pg_backend_pid() and w.transaction_id=txid_current() and w.user_id=new.actor_id)) end;
 new.body:=new.body||jsonb_build_object('actorName',new.actor_name,'authority',new.authority_context,
 'history',coalesce((select jsonb_agg(jsonb_build_object('action',e.action,'actorName',coalesce(e.actor_name,e.body->>'actorName',case when e.actor_id is null then 'Sistema' else 'Identidade registrada no evento legado' end),'createdAt',e.created_at,'version',e.version) order by e.version) from public.document_events e where document_id=new.document_id),'[]')||jsonb_build_array(jsonb_build_object('action',new.action,'actorName',coalesce(new.actor_name,'Sistema'),'createdAt',new.created_at,'version',new.version)));
 if d.type='REQ' then
 if new.action='req.issued' then perform private.init_requisition_science(new.document_id);end if;
 new.body:=new.body||jsonb_build_object('isHistorical',coalesce((select r.is_historical from public.requisitions r where r.id=d.id),false),'sciencePolicy',(select to_jsonb(s) from public.requisition_lifecycle s where requisition_id=new.document_id),
 'scienceEvents',coalesce((select jsonb_agg(to_jsonb(e) order by e.created_at,e.id) from public.requisition_science_events e where requisition_id=new.document_id),'[]'),
 'fulfillmentLines',coalesce((select jsonb_agg(jsonb_build_object('id',i.id,'attended',exists(select 1 from public.document_request_links k join public.document_lines l on l.id=k.document_line_id join public.operational_documents x on x.id=l.document_id where k.requisition_item_id=i.id and x.type='ENT' and x.status<>'cancelled' and l.accepted_quantity>0))) from public.requisition_items i where i.requisition_id=d.id),'[]'));
 end if;
 new.content_hash:=encode(extensions.digest(new.body::text,'sha256'),'hex');
 update public.operational_documents set canonical_snapshot=new.body,content_hash=new.content_hash where id=new.document_id;
 return new;
end;$function$

CREATE OR REPLACE FUNCTION private.v3_apply_access_change(p_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare c public.access_change_requests;x jsonb;begin
 select * into strict c from public.access_change_requests where id=p_id;
 x:=c.proposed;
 if c.kind='settings' then
 update public.patient_settings set settings=settings||x,version=version+1,updated_at=now() where care_recipient_id=c.care_recipient_id;
 elsif c.kind='capability' then
 if x->>'subjectUser' is not null then
 insert into public.capability_overrides(care_recipient_id,capability,subject_user,enabled) values(c.care_recipient_id,x->>'capability',(x->>'subjectUser')::uuid,(x->>'enabled')::boolean)
 on conflict(care_recipient_id,capability,subject_user) where subject_user is not null do update set enabled=excluded.enabled;
 else
 insert into public.capability_overrides(care_recipient_id,capability,subject_role,enabled) values(c.care_recipient_id,x->>'capability',x->>'subjectRole',(x->>'enabled')::boolean)
 on conflict(care_recipient_id,capability,subject_role) where subject_role is not null do update set enabled=excluded.enabled;
 end if;
 update public.patient_settings set version=version+1,updated_at=now() where care_recipient_id=c.care_recipient_id;
 elsif c.kind='membership' then
 perform public.admin_upsert_membership(c.care_recipient_id,(x->>'userId')::uuid,(x->>'role')::public.profile_role,false,false);
 update public.patient_settings set version=version+1,updated_at=now() where care_recipient_id=c.care_recipient_id;
 end if;
 update public.access_change_requests set status='applied',decided_at=now() where id=p_id;
 insert into public.audit_events(actor_id,action,entity_type,entity_id,metadata) values(auth.uid(),'access.applied','access_change',p_id,jsonb_build_object('care_recipient_id',c.care_recipient_id,'kind',c.kind));
end;$function$

CREATE OR REPLACE FUNCTION private.validate_supply_command(d operational_documents, p_action text, p_body jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare a jsonb;x jsonb;l public.document_lines;q numeric;precision_limit integer;begin
 if p_action is null or jsonb_typeof(p_body) is distinct from 'object' then raise exception 'invalid command body';end if;
 if p_action in ('purchase','consent_cancel') or d.type='COM' and p_action in ('approve','receive') then
 a:=p_body->'lines';
 if jsonb_typeof(a) is distinct from 'array' or jsonb_array_length(a) not between 1 and 1000 then raise exception 'invalid command lines';end if;
 if (select count(distinct z->>'lineId') from jsonb_array_elements(a) z)<>jsonb_array_length(a) then raise exception 'duplicate command lines';end if;
 elsif d.type='ENT' and p_action='receive' then
 a:=p_body->'divergences';
 if jsonb_typeof(a) is distinct from 'array' or jsonb_array_length(a)>1000 then raise exception 'invalid divergences';end if;
 if (select count(distinct z->>'lineId') from jsonb_array_elements(a) z)<>jsonb_array_length(a) then raise exception 'duplicate divergent lines';end if;
 elsif p_action='resolve' then a:=jsonb_build_array(p_body);
 end if;
 for x in select value from jsonb_array_elements(coalesce(a,'[]')) loop
 if jsonb_typeof(x) is distinct from 'object' or x->>'lineId' is null then raise exception 'invalid line';end if;
 select * into l from public.document_lines where document_id=d.id and id=(x->>'lineId')::uuid;
 if not found then raise exception 'line does not belong to document';end if;
 select quantity_decimals into strict precision_limit from public.care_recipient_products where care_recipient_id=d.care_recipient_id and product_id=l.product_id;
 if p_action='consent_cancel' then
 if not (x ?& array['returnQuantity','consumedQuantity']) or x->>'returnQuantity' is null or x->>'consumedQuantity' is null then raise exception 'cancellation quantities required';end if;
 if exists(select 1 from jsonb_each_text(x) z where z.key in ('returnQuantity','consumedQuantity') and (z.value !~ '^[0-9]+([.][0-9]{1,6})?$' or z.value::numeric<>round(z.value::numeric,precision_limit))) then raise exception 'invalid cancellation quantity';end if;
 else
 q:=case when d.type='ENT' and p_action='receive' then (x->>'acceptedQuantity')::numeric else (x->>'quantity')::numeric end;
 if q is null or q<0 or q>1000000000 or q<>round(q,precision_limit) then raise exception 'invalid product quantity';end if;
 end if;
 end loop;
 if p_action='validate_receipt' or p_action='reject_receipt' then if p_body->>'receiptId' is null then raise exception 'receipt required';end if;end if;
 if p_action='approve' and d.type='BAL' and coalesce(p_body->>'group','') not in ('family','supervisor') then raise exception 'review group required';end if;
 if p_action='resolve' and coalesce(p_body->>'resolution','') not in ('received','missing','returned') then raise exception 'resolution required';end if;
end;$function$

CREATE OR REPLACE FUNCTION public.accept_invitation(p_token_hash text)
 RETURNS care_recipient_memberships
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare result public.care_recipient_memberships;invitation uuid;begin
 result:=public.v4_accept_invitation(p_token_hash);
 select id into invitation from public.care_recipient_invitations where token_hash=p_token_hash and status='accepted';
 update public.access_change_requests set status='applied',resolution=resolution||jsonb_build_object('acceptedAt',now()) where status='awaiting_acceptance' and resolution->>'invitationId'=invitation::text;
 return result;
end;$function$

CREATE OR REPLACE FUNCTION public.accept_whatsapp_receipt(p_provider_id text, p_phone text, p_hash text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare c public.whatsapp_challenges;d public.operational_documents;result jsonb;previous text:=current_setting('hca.verified_whatsapp_provider',true);begin
 if coalesce(auth.jwt()->>'role','')<>'service_role' then raise exception 'signed webhook worker required' using errcode='42501';end if;
 select * into c from public.whatsapp_challenges where token_hash=p_hash;
 if not found then return jsonb_build_object('accepted',false);end if;
 select * into strict d from public.operational_documents where id=c.document_id;
 insert into private.worker_authority values(pg_backend_pid(),txid_current(),c.recipient_id,d.care_recipient_id,'verified_whatsapp_receipt');
 perform set_config('hca.verified_whatsapp_provider',p_provider_id,true);
 result:=public.verified_legacy_whatsapp_receipt(p_provider_id,p_phone,p_hash);
 delete from private.worker_authority where backend_pid=pg_backend_pid() and transaction_id=txid_current();
 perform set_config('hca.verified_whatsapp_provider',coalesce(previous,''),true);
 return result;
end;$function$

CREATE OR REPLACE FUNCTION public.acknowledge_no_issues(p_provider_id text, p_phone text, p_hash text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare c public.reminder_challenges;r public.operational_reminders;begin
 if coalesce(auth.jwt()->>'role','')<>'service_role' then raise exception 'verified webhook required' using errcode='42501';end if;
 perform pg_advisory_xact_lock(hashtextextended('inbound:'||p_provider_id,0));
 if exists(select 1 from public.inbound_messages where provider_id=p_provider_id) then return false;end if;
 select * into c from public.reminder_challenges where token_hash=p_hash for update;
 if not found or c.used_at is not null or c.expires_at<=now() or c.phone<>'+'||ltrim(p_phone,'+') then return false;end if;
 select * into strict r from public.operational_reminders where id=c.reminder_id for update;
 if r.acknowledged_at is not null or r.user_id<>c.user_id or not private.member_can(r.care_recipient_id,c.user_id,'consumption.report')
 or not exists(select 1 from public.verified_phones v join auth.users u on u.id=v.user_id where v.user_id=c.user_id and v.phone=c.phone and u.phone_confirmed_at is not null and '+'||ltrim(u.phone,'+')=v.phone) then return false;end if;
 update public.reminder_challenges set used_at=now() where id=c.id;
 update public.operational_reminders set acknowledged_at=now() where id=r.id;
 update public.requisition_notifications set seen_at=coalesce(seen_at,now()) where reminder_id=r.id and recipient_user_id=c.user_id;
 insert into public.inbound_messages values(p_provider_id,encode(extensions.digest(p_phone,'sha256'),'hex'),'no_issues','processed',now());
 insert into public.audit_events(actor_id,action,entity_type,entity_id,metadata) values(c.user_id,'shift.no_issues','reminder',r.id,jsonb_build_object('care_recipient_id',r.care_recipient_id,'stockChanged',false,'providerId',p_provider_id));return true;
end;$function$

CREATE OR REPLACE FUNCTION public.acknowledge_requisition(p_id uuid, p_mode text, p_version integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare s public.requisition_lifecycle;pref jsonb;d public.operational_documents;begin
 select * into d from public.operational_documents where id=p_id;
 perform private.require_cap(d.care_recipient_id,'req.science');
 perform pg_advisory_xact_lock(hashtextextended('stock:'||d.care_recipient_id,0));
 select * into d from public.operational_documents where id=p_id for update;
 select * into strict s from public.requisition_lifecycle where requisition_id=p_id for update;
 if exists(select 1 from public.requisition_science_events where requisition_id=p_id and user_id=auth.uid()) then return public.requisition_progress(p_id);end if;
 if d.status='cancelled' or d.version<>p_version then raise exception 'stale document version' using errcode='P0001';end if;
 select notification_preferences into pref from public.profiles where id=auth.uid();
 if p_mode='express' then
 if not coalesce((pref->>'scienceExpress')::boolean,true) then raise exception 'express science disabled';end if;
 elsif p_mode='app_visible' then
 if not coalesce((pref->>'scienceAutomatic')::boolean,false) or not coalesce((s.policy->>'scienceAutomatic')::boolean,false) then raise exception 'automatic science disabled';end if;
 else raise exception 'invalid science mode';end if;
 if not(auth.uid()=any(s.eligible_users)) then raise exception 'science permission required' using errcode='42501';end if;
 perform private.record_science(p_id,auth.uid(),p_mode,jsonb_build_object('sessionId',private.auth_session(),'documentVersion',p_version,'source',case when p_mode='express' then 'authenticated_confirmation' else 'visible_content_loaded' end));
 return public.requisition_progress(p_id);
end;$function$

CREATE OR REPLACE FUNCTION public.add_stock_inventory_item(p_inventory_id uuid, p_product_id text, p_counted_quantity bigint, p_justification text DEFAULT NULL::text)
 RETURNS stock_inventory_items
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v public.stock_inventory_items; i public.stock_inventories;
begin
  select * into i from public.stock_inventories where id=p_inventory_id for update;
  if not found or i.status<>'draft' then raise exception 'inventory not editable'; end if;
  if not public.recipient_can(i.care_recipient_id,'count') then raise exception 'inventory authorization required' using errcode='42501'; end if;
  if p_counted_quantity is null or p_counted_quantity<0 or p_counted_quantity>2147483647 then raise exception 'invalid count'; end if;
  update public.stock_inventory_items set counted_quantity=p_counted_quantity,justification=nullif(trim(p_justification),''),is_counted=true where inventory_id=p_inventory_id and product_id=p_product_id returning * into v;
  if not found then raise exception 'product absent from inventory snapshot; open a new inventory'; end if;
  return v;
end; $function$

CREATE OR REPLACE FUNCTION public.admin_create_invitation(p_care_recipient_id uuid, p_email text, p_role profile_role, p_can_manage_stock boolean, p_can_count_stock boolean, p_token_hash text, p_expires_at timestamp with time zone)
 RETURNS care_recipient_invitations
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v public.care_recipient_invitations;
begin
  if not public.recipient_can(p_care_recipient_id,'admin') then raise exception 'invitation admin authorization required' using errcode='42501';end if;
  if p_email is null or length(p_email)>254 or p_email!~'^[^[:space:]@]+@[^[:space:]@]+[.][^[:space:]@]+$' or p_role is null or p_token_hash is null or p_token_hash!~'^[a-f0-9]{64}$' or p_expires_at is null or p_expires_at<=now() or p_expires_at>now()+interval '30 days' then raise exception 'invalid invitation';end if;
  insert into public.care_recipient_invitations(care_recipient_id,email,role,can_manage_stock,can_count_stock,token_hash,expires_at,invited_by)
  values(p_care_recipient_id,lower(trim(p_email)),p_role,p_role<>'reader' and p_can_manage_stock,p_role<>'reader' and p_can_count_stock,p_token_hash,p_expires_at,auth.uid()) returning * into v;
  insert into public.audit_events(actor_id,action,entity_type,entity_id,metadata) values(auth.uid(),'invitation.created','invitation',v.id,jsonb_build_object('care_recipient_id',p_care_recipient_id,'role',p_role));return v;
end; $function$

CREATE OR REPLACE FUNCTION public.admin_resend_invitation(p_invitation_id uuid, p_token_hash text, p_expires_at timestamp with time zone)
 RETURNS care_recipient_invitations
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v public.care_recipient_invitations;
begin
  select * into v from public.care_recipient_invitations where id=p_invitation_id for update;
  if not found or not public.recipient_can(v.care_recipient_id,'admin') then raise exception 'invitation not authorized' using errcode='42501';end if;
  if v.status='accepted' or p_token_hash is null or p_token_hash!~'^[a-f0-9]{64}$' or p_expires_at is null or p_expires_at<=now() or p_expires_at>now()+interval '30 days' then raise exception 'invalid invitation renewal';end if;
  update public.care_recipient_invitations set token_hash=p_token_hash,expires_at=p_expires_at,status='pending',invited_by=auth.uid() where id=v.id returning * into v;
  insert into public.audit_events(actor_id,action,entity_type,entity_id,metadata) values(auth.uid(),'invitation.renewed','invitation',v.id,jsonb_build_object('care_recipient_id',v.care_recipient_id));return v;
end; $function$

