CREATE OR REPLACE FUNCTION public.admin_upsert_product(p_id text, p_name text, p_category product_category, p_unit text, p_aliases text[], p_is_active boolean)
 RETURNS products
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_product public.products;
begin
  if not public.is_global_administrator() then raise exception 'admin authorization required'; end if;
  if p_id !~ '^[a-z0-9][a-z0-9-]{1,119}$' or length(trim(p_name)) not between 2 and 160
     or p_unit not in ('unidade','caixa','frasco','pacote','bisnaga','envelope','comprimido')
  then raise exception 'invalid product'; end if;
  if exists (
    select 1
    from public.products x
    cross join lateral unnest(array_append(coalesce(x.aliases, '{}'), x.name)) existing_alias
    where x.id <> p_id
      and (
        unaccent(lower(trim(existing_alias))) = unaccent(lower(trim(p_name)))
        or exists (
          select 1 from unnest(coalesce(p_aliases, '{}')) incoming_alias
          where unaccent(lower(trim(incoming_alias))) = unaccent(lower(trim(existing_alias)))
        )
      )
  ) or exists (
    select 1 from unnest(coalesce(p_aliases, '{}')) a
    where unaccent(lower(trim(a))) = unaccent(lower(trim(p_name)))
  ) then raise exception 'ambiguous product alias'; end if;
  insert into public.products(id, name, category, unit, aliases, is_active)
  values (p_id, trim(p_name), p_category, p_unit, coalesce(p_aliases, '{}'), p_is_active)
  on conflict (id) do update set name=excluded.name, category=excluded.category,
    unit=excluded.unit, aliases=excluded.aliases, is_active=excluded.is_active
  returning * into v_product;
  insert into public.audit_events(actor_id, action, entity_type, entity_id, metadata)
  values (auth.uid(), 'product.updated', 'product', null,
    jsonb_build_object('product_id', p_id, 'is_active', p_is_active));
  return v_product;
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_upsert_recipient_product(p_care_recipient_id uuid, p_product_id text, p_name text, p_category product_category, p_unit text, p_aliases text[], p_is_active boolean, p_description text DEFAULT NULL::text, p_sort_order integer DEFAULT 0)
 RETURNS care_recipient_products
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare v public.care_recipient_products; v_id text; v_old_unit text;
begin
  if not private.can(p_care_recipient_id,'catalog.manage') then raise exception 'catalogue admin authorization required' using errcode='42501'; end if;
  perform pg_advisory_xact_lock(hashtextextended('catalogue:'||p_care_recipient_id,0));
  if p_name is null or length(trim(p_name)) not between 2 and 160 or p_category is null or p_unit is null or not exists(select 1 from public.measurement_units where code=p_unit and (care_recipient_id is null or care_recipient_id=p_care_recipient_id)) then raise exception 'invalid product'; end if;
  if cardinality(coalesce(p_aliases,'{}'))>50 or exists(select 1 from unnest(p_aliases) a where a is null or length(trim(a)) not between 1 and 160) then raise exception 'invalid aliases'; end if;
  if exists(select 1 from public.care_recipient_products c cross join lateral unnest(array_append(c.aliases,c.name)) a
    where c.care_recipient_id=p_care_recipient_id and c.product_id is distinct from p_product_id
      and exists(select 1 from unnest(array_append(coalesce(p_aliases,'{}'),p_name)) b where unaccent(lower(trim(a)))=unaccent(lower(trim(b)))))
  then raise exception 'ambiguous product alias'; end if;
  v_id:=p_product_id;
  if v_id is null then
    v_id:='patient-'||gen_random_uuid()::text;
    insert into public.products(id,name,category,unit,aliases,is_active,owner_care_recipient_id) values(v_id,trim(p_name),p_category,p_unit,coalesce(p_aliases,'{}'),p_is_active,p_care_recipient_id);
  elsif not exists(select 1 from public.products where id=v_id and (owner_care_recipient_id is null or owner_care_recipient_id=p_care_recipient_id)) then raise exception 'product not available for patient'; end if;
  select unit into v_old_unit from public.care_recipient_products where care_recipient_id=p_care_recipient_id and product_id=v_id;
  if v_old_unit is distinct from p_unit and v_old_unit is not null and (
    exists(select 1 from public.requisition_items where care_recipient_id=p_care_recipient_id and product_id=v_id)
    or exists(select 1 from public.stock_movements where care_recipient_id=p_care_recipient_id and product_id=v_id)
    or exists(select 1 from public.stock_inventory_items where care_recipient_id=p_care_recipient_id and product_id=v_id)) then raise exception 'unit with operational history is immutable; create a new product'; end if;
  insert into public.care_recipient_products(care_recipient_id,product_id,name,description,category,unit,aliases,is_active,sort_order)
  values(p_care_recipient_id,v_id,trim(p_name),p_description,p_category,p_unit,coalesce(p_aliases,'{}'),p_is_active,p_sort_order)
  on conflict(care_recipient_id,product_id) do update set name=excluded.name,description=excluded.description,category=excluded.category,unit=excluded.unit,aliases=excluded.aliases,is_active=excluded.is_active,sort_order=excluded.sort_order,updated_at=now() returning * into v;
  insert into public.audit_events(actor_id,action,entity_type,metadata) values(auth.uid(),'patient.product.updated','care_recipient_product',jsonb_build_object('care_recipient_id',p_care_recipient_id,'product_id',v_id,'is_active',p_is_active));
  return v;
end; $function$

CREATE OR REPLACE FUNCTION public.approve_stock_inventory(p_inventory_id uuid)
 RETURNS stock_inventories
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare i public.stock_inventories;x public.stock_inventory_items;v_current uuid;v_delta bigint;
begin
  select * into i from public.stock_inventories where id=p_inventory_id for update;
  if not found or not public.recipient_can(i.care_recipient_id,'review') then raise exception 'inventory approval required' using errcode='42501'; end if;
  if i.status='approved' then return i; end if;
  if i.status not in ('submitted','under_review') or i.reference_at is null then raise exception 'inventory must be recounted from a current snapshot'; end if;
  perform pg_advisory_xact_lock(hashtextextended('stock:'||i.care_recipient_id,0));
  -- Validate all references before inserting any adjustment.
  for x in select * from public.stock_inventory_items where inventory_id=i.id order by product_id loop
    select id into v_current from public.stock_movements where care_recipient_id=i.care_recipient_id and product_id=x.product_id and (source_location=i.location or destination_location=i.location) order by movement_revision desc limit 1;
    if v_current is distinct from x.reference_movement_id or x.expected_quantity is null or not x.is_counted then raise exception 'inventory reference changed; recount required' using errcode='P0001'; end if;
  end loop;
  for x in select * from public.stock_inventory_items where inventory_id=i.id order by product_id loop
    v_delta:=x.counted_quantity-x.expected_quantity;
    if abs(v_delta)>2147483647 then raise exception 'inventory adjustment exceeds allowed quantity'; end if;
    if v_delta<>0 then
      if x.justification is null then raise exception 'divergence justification required'; end if;
      insert into public.stock_movements(product_id,quantity,movement_type,performed_by,justification,care_recipient_id,source_location,destination_location,reference_type,reference_id)
      values(x.product_id,abs(v_delta)::integer,'adjustment',auth.uid(),x.justification,i.care_recipient_id,case when v_delta<0 then i.location end,case when v_delta>0 then i.location end,'inventory',i.id);
    end if;
  end loop;
  update public.stock_inventories set status='approved',approved_by=auth.uid(),approved_at=now() where id=i.id returning * into i;
  insert into public.audit_events(actor_id,action,entity_type,entity_id,metadata) values(auth.uid(),'inventory.approved','stock_inventory',i.id,jsonb_build_object('care_recipient_id',i.care_recipient_id));
  return i;
end; $function$

CREATE OR REPLACE FUNCTION public.archive_requisition(p_id uuid, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare patient uuid;begin
 select care_recipient_id into strict patient from public.requisition_lifecycle where requisition_id=p_id;
 perform private.require_cap(patient,'req.archive');
 perform pg_advisory_xact_lock(hashtextextended('stock:'||patient,0));
 perform private.require_cap(patient,'req.archive');
 return public.v4_review_archive_requisition(p_id,p_reason);
end;$function$

CREATE OR REPLACE FUNCTION public.audited_legacy_supply_command(p_id uuid, p_action text, p_body jsonb, p_key uuid, p_version integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare d public.operational_documents;e public.document_events;l public.document_lines;x jsonb;q numeric;delta numeric;r_id uuid;v_group text;s jsonb;all_ok boolean;any_ok boolean;cnt integer;v_actor uuid;v_return numeric;v_consumed numeric;
begin
 select * into d from public.operational_documents where id=p_id;
 if not found then raise exception 'document not found';end if;
 perform private.require_cap(d.care_recipient_id,lower(d.type)||'.read');
 perform pg_advisory_xact_lock(hashtextextended('stock:'||d.care_recipient_id,0));
 select * into d from public.operational_documents where id=p_id for update;
 select * into e from public.document_events where actor_id=auth.uid() and idempotency_key=p_key;
 if found then
 if e.document_id<>p_id or e.action<>lower(d.type)||'.'||p_action or e.body->'event'<>p_body then raise exception 'idempotency conflict' using errcode='23505';end if;
 return public.operational_document(p_id);end if;
 if p_key is null or p_version is null or d.version<>p_version then raise exception 'stale document version' using errcode='P0001';end if;
 if d.status in ('cancelled','rejected') then raise exception 'document is terminal';end if;
 perform private.validate_supply_command(d,p_action,p_body);
 update public.operational_documents set version=version+1 where id=p_id;
 if p_action='submit' and d.status='draft' then
 perform private.require_cap(d.care_recipient_id,case d.type when 'BAL' then 'bal.count' else lower(d.type)||'.create' end);
 if d.type='ENT' and (not private.user_can(d.care_recipient_id,d.recipient_id,'ent.receive') or d.recipient_id=d.created_by) then raise exception 'invalid designated recipient' using errcode='42501';end if;
 perform private.emit_document(p_id);
 update public.operational_documents set status=case d.type when 'COM' then case when public.recipient_role(d.care_recipient_id)='admin' then 'approved' else 'pending_approval' end when 'ENT' then 'pending_receipt' else 'submitted' end where id=p_id;
 if d.type='ENT' then for l in select * from public.document_lines where document_id=p_id order by product_id loop
 perform private.move_stock(d.care_recipient_id,l.product_id,l.quantity,d.payload->>'source','TRANSIT','Expedição ENT','document',d.id);end loop;end if;
 if d.type='BAL' and d.workflow_data->'reviewPolicy'->>'balReview'='optional' then perform private.apply_bal(d.id);end if;
 elsif d.type='COM' and p_action='approve' then
 perform private.require_cap(d.care_recipient_id,'com.approve');
 if d.status<>'pending_approval' or jsonb_array_length(p_body->'lines')<>(select count(*) from public.document_lines where document_id=p_id) then raise exception 'invalid approval';end if;
 for x in select value from jsonb_array_elements(p_body->'lines') loop
 select * into strict l from public.document_lines where id=(x->>'lineId')::uuid and document_id=p_id;
 q:=(x->>'quantity')::numeric;
 if q is null or q<0 or q>l.quantity or q<>round(q,(select quantity_decimals from public.care_recipient_products where care_recipient_id=d.care_recipient_id and product_id=l.product_id)) then raise exception 'invalid approval quantity';end if;
 if q<>l.quantity and length(trim(coalesce(p_body->>'reason','')))<3 then raise exception 'approval reason required';end if;
 update public.document_lines set approved_quantity=q where id=l.id;
 end loop;
 if (select count(distinct entry.value->>'lineId') from jsonb_array_elements(p_body->'lines') entry)<>jsonb_array_length(p_body->'lines') then raise exception 'duplicate lines';end if;
 update public.operational_documents set status=case when not exists(select 1 from public.document_lines where document_id=p_id and approved_quantity>0) then 'rejected' when exists(select 1 from public.document_lines where document_id=p_id and approved_quantity<quantity) then 'partially_approved' else 'approved' end where id=p_id;
 elsif d.type='COM' and p_action='purchase' then
 perform private.require_cap(d.care_recipient_id,'com.purchase');
 if d.status not in ('approved','partially_approved','purchasing','partially_received') then raise exception 'purchase requires approval';end if;
 for x in select value from jsonb_array_elements(p_body->'lines') loop
 select * into strict l from public.document_lines where id=(x->>'lineId')::uuid and document_id=p_id;
 q:=(x->>'quantity')::numeric;
 if q<=0 or q is null or l.purchased_quantity+q>l.approved_quantity then raise exception 'purchase exceeds approved quantity';end if;
 update public.document_lines set purchased_quantity=purchased_quantity+q where id=l.id;
 end loop;
 update public.operational_documents set status=case when exists(select 1 from public.document_lines where document_id=p_id and accepted_quantity>0) then 'partially_received' when exists(select 1 from public.document_lines where document_id=p_id and purchased_quantity<approved_quantity) then 'purchasing' else 'purchased' end where id=p_id;
 elsif d.type='COM' and p_action='receive' then
 perform private.require_cap(d.care_recipient_id,'com.receive');
 if d.status not in ('purchased','purchasing','partially_received') or jsonb_array_length(p_body->'lines')<1 then raise exception 'purchase required';end if;
 if (select count(distinct entry.value->>'lineId') from jsonb_array_elements(p_body->'lines') entry)<>jsonb_array_length(p_body->'lines') then raise exception 'duplicate lines';end if;
 for x in select value from jsonb_array_elements(p_body->'lines') loop
 select * into strict l from public.document_lines where id=(x->>'lineId')::uuid and document_id=p_id;
 q:=(x->>'quantity')::numeric;
 select coalesce(sum((z->>'quantity')::numeric),0) into delta from public.purchase_receipts r cross join lateral jsonb_array_elements(r.lines) z where r.document_id=p_id and r.state='pending' and z->>'lineId'=l.id::text;
 if q is null or q<=0 or l.accepted_quantity+delta+q>l.purchased_quantity then raise exception 'receipt exceeds purchased quantity';end if;
 end loop;
 insert into public.purchase_receipts(document_id,submitted_by,state,lines) values(p_id,auth.uid(),'pending',p_body->'lines') returning id into r_id;
 if public.recipient_role(d.care_recipient_id)='admin' then perform private.credit_purchase_receipt(r_id);end if;
 elsif d.type='COM' and p_action in ('validate_receipt','reject_receipt') then
 perform private.require_cap(d.care_recipient_id,'com.validate');
 r_id:=(p_body->>'receiptId')::uuid;
 if not exists(select 1 from public.purchase_receipts where id=r_id and document_id=p_id and state='pending') then raise exception 'receipt not pending';end if;
 if p_action='validate_receipt' then perform private.credit_purchase_receipt(r_id);
 else if length(trim(coalesce(p_body->>'reason','')))<3 then raise exception 'reason required';end if;
 update public.purchase_receipts set state='rejected',reason=p_body->>'reason',validated_by=auth.uid(),validated_at=now() where id=r_id;end if;
 elsif d.type='ENT' and p_action='reassign' then
 if d.status<>'pending_receipt' or exists(select 1 from public.document_lines where document_id=p_id and accepted_quantity>0) or d.created_by<>auth.uid() and not public.can_manage_recipient(d.care_recipient_id) then raise exception 'reassignment not authorized' using errcode='42501';end if;
 v_actor:=(p_body->>'recipientId')::uuid;
 if length(trim(coalesce(p_body->>'reason','')))<3 or v_actor=d.created_by or not private.user_can(d.care_recipient_id,v_actor,'ent.receive') or not exists(select 1 from public.care_recipient_memberships m join public.profiles p on p.id=m.user_id where m.care_recipient_id=d.care_recipient_id and m.user_id=v_actor and m.status='active' and p.status='active' and m.role::text in ('admin',case when d.payload->>'destination'='FAMILY' then 'family' else 'professional' end,case when d.payload->>'destination'='CARE_TEAM' then 'supervisor' else 'family' end)) then raise exception 'invalid recipient';end if;
 update public.operational_documents set recipient_id=v_actor where id=p_id;
 elsif d.type='ENT' and p_action='receive' then
 perform private.require_cap(d.care_recipient_id,'ent.receive');
 if auth.uid()<>d.recipient_id or d.status<>'pending_receipt' then raise exception 'only designated recipient may accept' using errcode='42501';end if;
 if exists(select 1 from jsonb_array_elements(coalesce(p_body->'divergences','[]')) z where not exists(select 1 from public.document_lines where document_id=p_id and id=(z->>'lineId')::uuid)) then raise exception 'invalid divergent line';end if;
 for l in select * from public.document_lines where document_id=p_id order by product_id loop
 select z into x from jsonb_array_elements(coalesce(p_body->'divergences','[]')) z where z->>'lineId'=l.id::text;
 if found then q:=coalesce((x->>'acceptedQuantity')::numeric,0);else q:=l.quantity;end if;
 if q<0 or q>l.quantity then raise exception 'invalid accepted quantity';end if;
 if q>0 then perform private.move_stock(d.care_recipient_id,l.product_id,q,'TRANSIT',d.payload->>'destination','Aceite ENT','document',d.id);end if;
 update public.document_lines set accepted_quantity=q,fully_checked=x is null,metadata=metadata||jsonb_build_object('issueOpen',x is not null,'receipt',coalesce(x,'{}')) where id=l.id;
 end loop;
 update public.operational_documents set status=case when exists(select 1 from public.document_lines where document_id=p_id and not fully_checked) then 'disputed' else 'confirmed' end,workflow_data=workflow_data||jsonb_build_object('acceptedBy',auth.uid(),'acceptedAt',now()) where id=p_id;
 elsif d.type='ENT' and p_action='resolve' then
 if d.status<>'disputed' or auth.uid()<>d.recipient_id and not public.can_manage_recipient(d.care_recipient_id) then raise exception 'resolution not authorized' using errcode='42501';end if;
 select * into strict l from public.document_lines where id=(p_body->>'lineId')::uuid and document_id=p_id;
 q:=coalesce((p_body->>'quantity')::numeric,0);
 if q<0 or q>l.quantity-l.accepted_quantity-l.reconciled_quantity or length(trim(coalesce(p_body->>'reason','')))<3 then raise exception 'invalid reconciliation';end if;
 if p_body->>'resolution'='received' then
 perform private.require_cap(d.care_recipient_id,'ent.receive');
 if auth.uid()<>d.recipient_id then raise exception 'only designated recipient may accept' using errcode='42501';end if;
 if q>0 then perform private.move_stock(d.care_recipient_id,l.product_id,q,'TRANSIT',d.payload->>'destination','Recebimento complementar ENT','document',d.id);end if;
 update public.document_lines set accepted_quantity=accepted_quantity+q where id=l.id;
 elsif p_body->>'resolution' in ('missing','returned') then
 if q>0 then perform private.move_stock(d.care_recipient_id,l.product_id,q,'TRANSIT',case when p_body->>'resolution'='returned' then d.payload->>'source' end,p_body->>'reason','document',d.id);end if;
 update public.document_lines set reconciled_quantity=reconciled_quantity+q where id=l.id;
 else raise exception 'invalid resolution';end if;
 update public.document_lines set fully_checked=accepted_quantity=quantity,metadata=metadata||jsonb_build_object('issueOpen',accepted_quantity+reconciled_quantity<quantity) where id=l.id;
 update public.operational_documents set status=case when exists(select 1 from public.document_lines where document_id=p_id and coalesce((metadata->>'issueOpen')::boolean,false)) then 'disputed' else 'confirmed' end where id=p_id;
 elsif d.type='BAL' and p_action='approve' then
 v_group:=p_body->>'group';s:=d.workflow_data->'reviewPolicy';
 if v_group not in ('family','supervisor') or not(s->'balApprovers' ? v_group) then raise exception 'review group not enabled';end if;
 perform private.require_cap(d.care_recipient_id,'bal.approve.'||v_group);
 if d.status not in ('submitted','approved') then raise exception 'BAL not submitted';end if;
 insert into public.bal_approvals(document_id,review_group,actor_id,count_version) values(p_id,v_group,auth.uid(),(d.workflow_data->>'countVersion')::integer);
 select count(*) into cnt from public.bal_approvals where document_id=p_id and count_version=(d.workflow_data->>'countVersion')::integer;
 if d.status<>'approved' and (s->>'balRequirement'='any' and cnt>0 or s->>'balRequirement'='all' and cnt=jsonb_array_length(s->'balApprovers')) then perform private.apply_bal(p_id);end if;
 elsif p_action='cancel' and d.type in ('COM','ENT','BAL') then
 if length(trim(coalesce(p_body->>'reason','')))<3 then raise exception 'reason required';end if;
 if d.type='ENT' then
 if exists(select 1 from public.document_lines where document_id=p_id and accepted_quantity>0) then
 perform private.require_cap(d.care_recipient_id,'ent.cancel');
 update public.operational_documents set status='cancellation_pending',workflow_data=workflow_data||jsonb_build_object('cancellationRequestedBy',auth.uid(),'cancellationReason',p_body->>'reason') where id=p_id;
 else
 if d.created_by<>auth.uid() and not public.can_manage_recipient(d.care_recipient_id) then raise exception 'cancel not authorized' using errcode='42501';end if;
 if d.status<>'draft' then for l in select * from public.document_lines where document_id=p_id order by product_id loop
 q:=l.quantity-l.accepted_quantity-l.reconciled_quantity;
 if q>0 then perform private.move_stock(d.care_recipient_id,l.product_id,q,'TRANSIT',d.payload->>'source','Cancelamento ENT antes do aceite','document',d.id);end if;
 end loop;end if;
 update public.operational_documents set status='cancelled' where id=p_id;
 end if;
 else
 perform private.require_cap(d.care_recipient_id,case d.type when 'COM' then 'com.approve' else 'access.manage' end);
 if exists(select 1 from public.document_lines where document_id=p_id and (accepted_quantity>0 or purchased_quantity>0)) or d.status='approved' and d.type='BAL' then raise exception 'reconciliation required before cancellation';end if;
 update public.operational_documents set status='cancelled' where id=p_id;
 end if;
 elsif d.type='ENT' and p_action='consent_cancel' then
 perform private.require_cap(d.care_recipient_id,'ent.receive');
 if d.status<>'cancellation_pending' or auth.uid()<>d.recipient_id then raise exception 'original recipient consent required' using errcode='42501';end if;
 if jsonb_array_length(p_body->'lines')<>(select count(*) from public.document_lines where document_id=p_id) or length(trim(coalesce(p_body->>'reason','')))<3 then raise exception 'cancellation reconciliation required';end if;
 if (select count(distinct z->>'lineId') from jsonb_array_elements(p_body->'lines') z)<>jsonb_array_length(p_body->'lines') then raise exception 'duplicate lines';end if;
 for l in select * from public.document_lines where document_id=p_id order by product_id loop
 select z into strict x from jsonb_array_elements(p_body->'lines') z where z->>'lineId'=l.id::text;
 v_return:=coalesce((x->>'returnQuantity')::numeric,0);v_consumed:=coalesce((x->>'consumedQuantity')::numeric,0);
 if v_return<0 or v_consumed<0 or v_return+v_consumed<>l.accepted_quantity then raise exception 'account for all accepted material';end if;
 if v_consumed>0 then
 select coalesce(sum(quantity),0) into q from public.stock_movements where care_recipient_id=d.care_recipient_id and product_id=l.product_id and source_location=d.payload->>'destination' and destination_location is null and reference_type='consumption' and created_at>=d.created_at;
 select coalesce(sum((z->>'consumedQuantity')::numeric),0) into delta from public.document_events e cross join lateral jsonb_array_elements(coalesce(e.body->'event'->'lines','[]')) z join public.document_lines dl on dl.id=(z->>'lineId')::uuid where e.care_recipient_id=d.care_recipient_id and e.action='ent.consent_cancel' and dl.product_id=l.product_id;
 if q-delta<v_consumed then raise exception 'record and reconcile actual consumption first';end if;
 end if;
 if v_return>0 then perform private.move_stock(d.care_recipient_id,l.product_id,v_return,d.payload->>'destination',d.payload->>'source','Devolução consentida no cancelamento ENT','document',d.id);end if;
 q:=l.quantity-l.accepted_quantity-l.reconciled_quantity;
 if q>0 then perform private.move_stock(d.care_recipient_id,l.product_id,q,'TRANSIT',d.payload->>'source','Regularização de trânsito no cancelamento ENT','document',d.id);end if;
 end loop;
 update public.operational_documents set status='cancelled' where id=p_id;
 else raise exception 'invalid operation for document state';
 end if;
 perform private.record_document_event(p_id,lower(d.type)||'.'||p_action,p_body,p_key);
 return public.operational_document(p_id);
end;$function$

CREATE OR REPLACE FUNCTION public.balance_command(p_patient uuid, p_action text, p_body jsonb, p_key uuid, p_version integer DEFAULT NULL::integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_old private.bal_commands;v_request jsonb;v_result jsonb;v_r public.bal_regimes;v_a public.bal_assignments;v_d public.bal_deferrals;
 v_c public.bal_cycles;v_doc public.operational_documents;v_s public.scheduled_shifts;v_id uuid;v_approve boolean;v_reason text:=trim(coalesce(p_body->>'reason',''));
begin
 perform private.require_cap(p_patient,'bal.read');
 if p_key is null or p_body is null or jsonb_typeof(p_body)<>'object' then raise exception 'invalid balance command';end if;
 if not exists(select 1 from public.care_recipients where id=p_patient and is_active) then raise exception 'inactive patient';end if;
 if p_action='assign_recount' then perform pg_advisory_xact_lock(hashtextextended('stock:'||p_patient,0));end if;
 perform pg_advisory_xact_lock(hashtextextended('bal:'||p_patient,0));
 v_request:=jsonb_build_object('action',p_action,'body',p_body,'version',p_version);
 select * into v_old from private.bal_commands where care_recipient_id=p_patient and actor_id=auth.uid() and key=p_key;
 if found then if v_old.request<>v_request then raise exception 'idempotency payload mismatch';end if;return v_old.result;end if;
 if p_action='configure' then
 if not private.bal_family_authority(p_patient,'bal.schedule.manage') then raise exception 'family balance scheduling authorization required' using errcode='42501';end if;
 select * into v_r from public.bal_regimes where care_recipient_id=p_patient for update;
 if v_r.version is distinct from p_version then raise exception 'stale document';end if;
 if length(v_reason)<3 or not exists(select 1 from pg_catalog.pg_timezone_names where name=p_body->>'timezone') then raise exception 'reason and valid timezone required';end if;
 if not exists(select 1 from public.shift_types where care_recipient_id=p_patient and id=(p_body->>'shiftTypeId')::uuid and is_active) then raise exception 'invalid balance shift type';end if;
 if p_body->>'professionalId' is not null and not private.schedule_worker(p_patient,(p_body->>'professionalId')::uuid) then raise exception 'invalid designated professional';end if;
 if (v_r.care_recipient_id is null or not v_r.enabled) and (p_body->>'startsOn')::date<(now() at time zone (p_body->>'timezone'))::date then raise exception 'balance activation cannot be retroactive';end if;
 if v_r.starts_on is not null and (p_body->>'startsOn')::date<v_r.starts_on then raise exception 'balance activation cannot be retroactive';end if;
 insert into public.bal_regimes(care_recipient_id,enabled,timezone,weekday,shift_type_id,designated_professional_id,starts_on,activated_at,updated_by)
 values(p_patient,(p_body->>'enabled')::boolean,p_body->>'timezone',(p_body->>'weekday')::integer,(p_body->>'shiftTypeId')::uuid,(p_body->>'professionalId')::uuid,(p_body->>'startsOn')::date,case when (p_body->>'enabled')::boolean then now() end,auth.uid())
 on conflict(care_recipient_id) do update set enabled=excluded.enabled,timezone=excluded.timezone,weekday=excluded.weekday,shift_type_id=excluded.shift_type_id,
 designated_professional_id=excluded.designated_professional_id,starts_on=excluded.starts_on,activated_at=coalesce(public.bal_regimes.activated_at,excluded.activated_at),version=public.bal_regimes.version+1,updated_by=auth.uid(),updated_at=now() returning * into v_r;
 perform private.bal_event(p_patient,null,null,'bal.cycle.configured',v_reason,to_jsonb(v_r),'config:'||v_r.version);
 perform private.process_bal_patient(p_patient);v_result:=to_jsonb(v_r);
 elsif p_action='refresh' then
 if not(private.can(p_patient,'bal.schedule.manage') or private.can(p_patient,'schedule.manage.team')) then raise exception 'balance scheduling authorization required' using errcode='42501';end if;
 perform private.process_bal_patient(p_patient);v_result:=jsonb_build_object('processed',true);
 elsif p_action in ('request_deferral','defer','decide_deferral') then
 perform private.process_bal_patient(p_patient);
 if length(v_reason)<3 then raise exception 'deferral reason required';end if;
 if p_action='decide_deferral' then
 if not private.bal_family_authority(p_patient,'bal.defer.approve') then raise exception 'family approval required' using errcode='42501';end if;
 select * into v_d from public.bal_deferrals where care_recipient_id=p_patient and id=(p_body->>'id')::uuid for update;
 if not found or v_d.status<>'pending' then raise exception 'stale document';end if;
 select * into v_a from public.bal_assignments where id=v_d.assignment_id for update;
 if v_a.status<>'active' or v_a.version<>v_d.assignment_version or v_a.ends_at<=now() then raise exception 'stale document';end if;
 select * into v_s from public.scheduled_shifts where id=v_d.target_shift_id for share;
 if not found or v_s.status<>'published' or v_s.version<>v_d.target_shift_version then raise exception 'stale document target shift';end if;v_approve:=(p_body->>'approve')::boolean;
 else
 select * into v_a from public.bal_assignments where id=(p_body->>'assignmentId')::uuid and care_recipient_id=p_patient for update;
 if not found or v_a.status<>'active' or v_a.version is distinct from p_version or v_a.ends_at<=now() then raise exception 'stale document';end if;
 if p_action='defer' then
 if not private.bal_family_authority(p_patient,'bal.defer.approve') then raise exception 'family approval required' using errcode='42501';end if;
 else
 if not private.can(p_patient,'bal.defer.request') or (v_a.professional_id<>auth.uid() and not exists(select 1 from public.care_recipient_memberships where care_recipient_id=p_patient and user_id=auth.uid() and status='active' and role='supervisor')) then raise exception 'deferral request authorization required' using errcode='42501';end if;
 end if;
 select * into v_s from public.scheduled_shifts where care_recipient_id=p_patient and id=(p_body->>'targetShiftId')::uuid for share;
 if not found or v_s.status<>'published' or v_s.starts_at<v_a.ends_at or not private.schedule_worker(p_patient,v_s.professional_id) or not private.member_can(p_patient,v_s.professional_id,'bal.count') then raise exception 'invalid deferral target shift';end if;
 insert into public.bal_deferrals(care_recipient_id,cycle_id,assignment_id,assignment_version,target_shift_id,target_shift_version,target_snapshot,reason,requested_by)
 values(p_patient,v_a.cycle_id,v_a.id,v_a.version,v_s.id,v_s.version,to_jsonb(v_s)||jsonb_build_object('professional_name',(select full_name from public.profiles where id=v_s.professional_id),'type_name',(select name from public.shift_types where id=v_s.shift_type_id)),v_reason,auth.uid()) returning * into v_d;
 v_approve:=p_action='defer';end if;
 if v_approve then
 update public.bal_assignments set status='deferred',version=version+1 where id=v_a.id;
 v_id:=private.bal_assign(p_patient,v_a.cycle_id,v_d.target_shift_id,'deferred'); update public.bal_obligations set effective_due=greatest(effective_due,(v_d.target_snapshot->>'ends_at')::timestamptz) where cycle_id=v_a.cycle_id and state='pending';
 update public.bal_deferrals set status='approved',decided_by=auth.uid(),decided_at=now(),decision_reason=v_reason where id=v_d.id returning * into v_d;
 perform private.bal_event(p_patient,v_a.cycle_id,v_id,'bal.cycle.deferred',v_reason,to_jsonb(v_d),'deferral:'||v_d.id||':approved');
 elsif p_action='decide_deferral' then
 update public.bal_deferrals set status='rejected',decided_by=auth.uid(),decided_at=now(),decision_reason=v_reason where id=v_d.id returning * into v_d;
 perform private.bal_event(p_patient,v_a.cycle_id,v_a.id,'bal.cycle.deferral_rejected',v_reason,to_jsonb(v_d),'deferral:'||v_d.id||':rejected');
 else perform private.bal_event(p_patient,v_a.cycle_id,v_a.id,'bal.cycle.deferral_requested',v_reason,to_jsonb(v_d),'deferral:'||v_d.id||':requested');end if;
 v_result:=to_jsonb(v_d);
 elsif p_action='assign_recount' then
 if not(private.can(p_patient,'bal.approve.family') or private.can(p_patient,'bal.approve.supervisor')) then raise exception 'balance review authorization required' using errcode='42501';end if;
 if length(v_reason)<3 then raise exception 'recount reason required';end if;
 select * into v_c from public.bal_cycles where care_recipient_id=p_patient and document_id=(p_body->>'documentId')::uuid and state='counted' for update;
 if not found or not exists(select 1 from public.operational_documents where id=v_c.document_id and type='BAL' and status='submitted') then raise exception 'pending balance review required';end if;
 select * into v_doc from public.operational_documents where id=v_c.document_id for update;
 if v_doc.version is distinct from p_version or v_doc.status<>'submitted' then raise exception 'stale document';end if;
 if exists(select 1 from public.bal_assignments where care_recipient_id=p_patient and status='active') then raise exception 'another balance assignment is active';end if;
 v_id:=private.bal_assign(p_patient,v_c.id,(p_body->>'targetShiftId')::uuid,'recount');
 perform private.bal_event(p_patient,v_c.id,v_id,'bal.cycle.recount_assigned',v_reason,jsonb_build_object('documentId',v_c.document_id),'recount:'||v_id);
 v_result:=jsonb_build_object('assignmentId',v_id);
 else raise exception 'invalid balance action';end if;
 insert into private.bal_commands(care_recipient_id,actor_id,key,request,result) values(p_patient,auth.uid(),p_key,v_request,v_result);
 return v_result;
end;$function$

CREATE OR REPLACE FUNCTION public.bind_notification_template(p_id uuid, p_worker uuid, p_name text, p_version integer, p_language text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare t public.meta_template_versions;begin
 if coalesce(auth.jwt()->>'role','')<>'service_role' or not public.validate_notification_job(p_id,p_worker) then raise exception 'verified worker required' using errcode='42501';end if;
 select * into t from public.meta_template_versions where name=p_name and version=p_version and language=p_language;
 if not found then return null;end if;
 update public.requisition_notifications set template_name=t.name,template_version=t.version,template_snapshot=t.definition where id=p_id;
 return t.definition||jsonb_build_object('name',t.name,'version',t.version,'language',t.language,'approval',t.approval);
end;$function$

CREATE OR REPLACE FUNCTION public.bind_validated_attachment(p_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare a public.attachments;d public.operational_documents;begin
 select * into strict a from public.attachments where id=p_id;
 if a.state<>'ready' or a.uploaded_by<>auth.uid() then raise exception 'validated evidence owner required' using errcode='42501';end if;
 if a.document_id is null then return;end if;
 select * into strict d from public.operational_documents where id=a.document_id for update;
 perform private.require_cap(d.care_recipient_id,lower(d.type)||'.read');
 if exists(select 1 from public.document_events where document_id=d.id and action='attachment.bound' and body->'event'->>'attachmentId'=p_id::text) then return;end if;
 update public.operational_documents set version=version+1 where id=d.id;
 perform private.record_document_event(d.id,'attachment.bound',jsonb_build_object('attachmentId',p_id,'sha256',a.sha256),p_id);
end;$function$

CREATE OR REPLACE FUNCTION public.claim_notification_jobs(p_limit integer, p_worker_id uuid, p_external_enabled boolean DEFAULT false)
 RETURNS SETOF requisition_notifications
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare attempt integer;
begin
 if not public.is_global_administrator() and coalesce(auth.role(),'')<>'service_role' then
  raise exception 'worker authorization required' using errcode='42501';
 end if;
 if p_worker_id is null then raise exception 'worker identity required';end if;
 for attempt in 1..3 loop
  begin
   return query select * from public.fluent_pre_retry_claim_jobs(p_limit,p_worker_id,p_external_enabled);
   return;
  exception when deadlock_detected then
   if attempt=3 then raise;end if;
   perform pg_catalog.pg_sleep(0.01*attempt+pg_catalog.random()*0.02);
  end;
 end loop;
end;
$function$

CREATE OR REPLACE FUNCTION public.configure_catalogue_unit(p_patient uuid, p_product text, p_unit text, p_decimals integer, p_barcode text DEFAULT NULL::text, p_presentation text DEFAULT NULL::text, p_base_quantity numeric DEFAULT NULL::numeric)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$declare v_id uuid;begin
 perform private.require_cap(p_patient,'catalog.manage');
 if p_decimals not between 0 and 6 or not exists(select 1 from public.measurement_units where code=p_unit and (care_recipient_id is null or care_recipient_id=p_patient)) then raise exception 'invalid measurement unit';end if;
 if exists(select 1 from public.stock_movements where care_recipient_id=p_patient and product_id=p_product) and exists(select 1 from public.care_recipient_products where care_recipient_id=p_patient and product_id=p_product and (unit<>p_unit or quantity_decimals<>p_decimals)) then raise exception 'unit with operational history is immutable';end if;
 update public.care_recipient_products set unit=p_unit,quantity_decimals=p_decimals where care_recipient_id=p_patient and product_id=p_product;
 if not found then raise exception 'product not found';end if;
 if p_barcode is not null then
 if p_base_quantity<=0 or p_base_quantity<>round(p_base_quantity,p_decimals) or length(trim(coalesce(p_presentation,'')))<2 then raise exception 'invalid presentation';end if;
 insert into public.product_presentations(care_recipient_id,product_id,barcode,name,base_quantity) values(p_patient,p_product,p_barcode,p_presentation,p_base_quantity)
 on conflict(care_recipient_id,barcode) do update set name=excluded.name,base_quantity=excluded.base_quantity where public.product_presentations.product_id=excluded.product_id returning id into v_id;
 if v_id is null then raise exception 'barcode already associated with another product';end if;
 end if;
 return jsonb_build_object('presentationId',v_id);
end;$function$

CREATE OR REPLACE FUNCTION public.configure_patient_access(p_patient uuid, p_kind text, p_change jsonb, p_key uuid, p_version integer, p_request_id uuid DEFAULT NULL::uuid, p_decision text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare c public.access_change_requests;result jsonb;begin
 if p_request_id is not null and p_decision='approve' then
 if not public.can_manage_recipient(p_patient) then raise exception 'local administrator required' using errcode='42501';end if;
 perform pg_advisory_xact_lock(hashtextextended('stock:'||p_patient,0));
 select * into strict c from public.access_change_requests where id=p_request_id and care_recipient_id=p_patient for update;
 if c.proposed_by=auth.uid() then raise exception 'distinct patient administrator required' using errcode='42501';end if;
 if c.status='pending' and c.kind='membership' and not exists(select 1 from public.care_recipient_memberships where care_recipient_id=p_patient and user_id=(c.proposed->>'userId')::uuid and status='active') then
 if coalesce(p_change->>'invitationTokenHash','')!~'^[0-9a-f]{64}$' then raise exception 'recipient invitation acceptance required' using errcode='23514';end if;
 insert into private.membership_invitation_intents values(pg_backend_pid(),txid_current(),c.id,p_change->>'invitationTokenHash');
 end if;end if;
 result:=public.v4_review_patient_access(p_patient,p_kind,p_change,p_key,p_version,p_request_id,p_decision);
 delete from private.membership_invitation_intents where backend_pid=pg_backend_pid() and transaction_id=txid_current();return result;
exception when sqlstate 'P0001' then
 -- A stale client revision cannot succeed through a database transaction retry.
 -- Keep real serialization failures untouched; expose this logical conflict once.
 if sqlerrm='stale policy version' then raise exception 'stale policy version' using errcode='PT409';end if;
 raise;
end;$function$

CREATE OR REPLACE FUNCTION public.configure_stock_alert(p_care_recipient_id uuid, p_product_id text, p_location text, p_low_threshold numeric, p_critical_threshold numeric, p_is_enabled boolean)
 RETURNS stock_alert_rules
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v public.stock_alert_rules;precision_limit integer;begin
 perform private.require_cap(p_care_recipient_id,'access.manage');
 select quantity_decimals into precision_limit from public.care_recipient_products where care_recipient_id=p_care_recipient_id and product_id=p_product_id;
 if precision_limit is null or p_low_threshold is null or p_critical_threshold is null or p_low_threshold<0 or p_low_threshold>1000000000 or p_critical_threshold<0 or p_critical_threshold>p_low_threshold
 or p_low_threshold<>round(p_low_threshold,precision_limit) or p_critical_threshold<>round(p_critical_threshold,precision_limit) then raise exception 'invalid product threshold precision';end if;
 perform pg_advisory_xact_lock(hashtextextended('stock:'||p_care_recipient_id,0));
 insert into public.stock_alert_rules(care_recipient_id,product_id,location,low_threshold,critical_threshold,is_enabled) values(p_care_recipient_id,p_product_id,p_location,p_low_threshold,p_critical_threshold,p_is_enabled)
 on conflict(care_recipient_id,product_id,location) do update set low_threshold=excluded.low_threshold,critical_threshold=excluded.critical_threshold,is_enabled=excluded.is_enabled returning * into v;
 perform public.evaluate_stock_alert(p_care_recipient_id,p_product_id,p_location);
 insert into public.audit_events(actor_id,action,entity_type,entity_id,metadata) values(auth.uid(),'stock.alert.configured','stock_alert_rule',v.id,jsonb_build_object('care_recipient_id',p_care_recipient_id));return v;
end;$function$

CREATE OR REPLACE FUNCTION public.configure_worker_schedule(p_token text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare sid uuid;begin
 if coalesce(auth.jwt()->>'role','')<>'service_role' or length(p_token) not between 32 and 512 then raise exception 'scoped worker secret required' using errcode='42501';end if;
 select id into sid from vault.secrets where name='hca_worker_url';
 if sid is null then perform vault.create_secret('https://home-care-assistant.vercel.app/api/notifications/worker','hca_worker_url');
 else perform vault.update_secret(sid,'https://home-care-assistant.vercel.app/api/notifications/worker');end if;
 select id into sid from vault.secrets where name='hca_worker_bearer';
 if sid is null then perform vault.create_secret(p_token,'hca_worker_bearer');else perform vault.update_secret(sid,p_token);end if;
end;$function$

CREATE OR REPLACE FUNCTION public.confirm_extraordinary_consumption(p_id uuid, p_accept boolean)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare r public.consumption_reports;x jsonb;q numeric;begin
 select * into r from public.consumption_reports where id=p_id;
 if not found then raise exception 'report not found';end if;
 perform private.require_cap(r.care_recipient_id,case r.location when 'FAMILY' then 'stock.family.manage' else 'consumption.confirm' end);
 perform pg_advisory_xact_lock(hashtextextended('stock:'||r.care_recipient_id,0));
 select * into r from public.consumption_reports where id=p_id for update;
 if r.status<>'reported' then return;end if;
 if p_accept and r.kind='consumption' then
 if jsonb_array_length(r.lines)=0 then raise exception 'structured confirmation required';end if;
 for x in select value from jsonb_array_elements(r.lines) loop
 q:=(x->>'quantity')::numeric;
 if q is null or q<=0 or q>1000000000 or not exists(select 1 from public.care_recipient_products where care_recipient_id=r.care_recipient_id and product_id=x->>'productId' and unit=x->>'unit') then raise exception 'ambiguous consumption';end if;
 perform private.move_stock(r.care_recipient_id,x->>'productId',q,r.location,null,'Consumo extraordinário confirmado','consumption',r.id);
 end loop;end if;
 update public.consumption_reports set status=case when p_accept then 'confirmed' else 'rejected' end,confirmed_by=auth.uid(),confirmed_at=now() where id=p_id;
 insert into public.audit_events(actor_id,action,entity_type,entity_id,metadata) values(auth.uid(),'consumption.reviewed','consumption',p_id,jsonb_build_object('care_recipient_id',r.care_recipient_id,'accepted',p_accept,'kind',r.kind));
end;$function$

CREATE OR REPLACE FUNCTION public.confirm_whatsapp_science(p_provider_id text, p_phone text, p_hash text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare c public.science_challenges;d public.operational_documents;begin
 if coalesce(auth.jwt()->>'role','')<>'service_role' then raise exception 'verified webhook required' using errcode='42501';end if;
 perform pg_advisory_xact_lock(hashtextextended('inbound:'||p_provider_id,0));
 if exists(select 1 from public.inbound_messages where provider_id=p_provider_id) then return false;end if;
 select * into c from public.science_challenges where token_hash=p_hash for update;
 if not found or c.used_at is not null or c.expires_at<=now() or c.phone<>'+'||ltrim(p_phone,'+') then return false;end if;
 select * into strict d from public.operational_documents where id=c.document_id;
 perform pg_advisory_xact_lock(hashtextextended('stock:'||d.care_recipient_id,0));
 select * into strict d from public.operational_documents where id=c.document_id for update;
 if d.status='cancelled' or d.version<>c.document_version or not exists(select 1 from public.verified_phones v join auth.users u on u.id=v.user_id where v.user_id=c.recipient_id and v.phone=c.phone and '+'||ltrim(u.phone,'+')=v.phone and u.phone_confirmed_at is not null)
 or not coalesce((select (notification_preferences->>'scienceWhatsApp')::boolean from public.profiles where id=c.recipient_id),false) then return false;end if;
 if not private.record_science(d.id,c.recipient_id,'whatsapp_confirm',jsonb_build_object('providerId',p_provider_id,'notificationId',c.notification_id,'documentVersion',c.document_version,'challengeId',c.id)) then return false;end if;
 update public.science_challenges set used_at=now() where id=c.id;
 insert into public.inbound_messages values(p_provider_id,encode(extensions.digest(p_phone,'sha256'),'hex'),'science','processed',now());return true;
end;$function$

CREATE OR REPLACE FUNCTION public.create_flow_session(p_patient uuid, p_hash text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$declare v uuid;begin
 perform private.require_cap(p_patient,'consumption.report');
 if not public.recent_session() or p_hash is null or p_hash!~'^[a-f0-9]{64}$' then raise exception 'recent session required' using errcode='42501';end if;
 insert into public.flow_sessions(care_recipient_id,user_id,token_hash,expires_at) values(p_patient,auth.uid(),p_hash,now()+interval '20 minutes') returning id into v;return v;
end;$function$

CREATE OR REPLACE FUNCTION public.create_measurement_unit(p_patient uuid, p_code text, p_name text, p_dimension text, p_decimals integer)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$declare v_id uuid;begin
 if p_patient is null then if not public.is_global_administrator() then raise exception 'global authorization required' using errcode='42501';end if;
 else perform private.require_cap(p_patient,'catalog.manage');end if;
 if length(trim(p_code)) not between 1 and 30 or length(trim(p_name)) not between 2 and 80 then raise exception 'invalid unit';end if;
 insert into public.measurement_units(care_recipient_id,code,name,dimension,decimals) values(p_patient,p_code,p_name,p_dimension,p_decimals) returning id into v_id;return v_id;
end;$function$

CREATE OR REPLACE FUNCTION public.create_patient_with_administrator(p_name text, p_development boolean, p_administrator_email text)
 RETURNS care_recipients
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare person uuid;patient public.care_recipients;begin
 if not public.is_global_administrator() then raise exception 'global authorization required' using errcode='42501';end if;
 select p.id into person from public.profiles p join auth.users u on u.id=p.id where lower(u.email)=lower(trim(p_administrator_email)) and u.email_confirmed_at is not null and p.status='active';
 if person is null then raise exception 'confirmed active administrator identity required';end if;
 patient:=public.admin_upsert_recipient(null,p_name,true,p_development);
 insert into private.membership_authority values(pg_backend_pid(),txid_current(),patient.id,person,'admin',true,true);
 insert into public.care_recipient_memberships(care_recipient_id,user_id,role,can_manage_stock,can_count_stock) values(patient.id,person,'admin',true,true);
 delete from private.membership_authority where backend_pid=pg_backend_pid() and transaction_id=txid_current() and care_recipient_id=patient.id;
 insert into public.audit_events(actor_id,action,entity_type,entity_id,metadata) values(auth.uid(),'patient.initial_administrator','patient',patient.id,jsonb_build_object('userId',person,'explicit',true));return patient;
end;$function$

CREATE OR REPLACE FUNCTION public.create_receipt_flow_session(p_document uuid, p_hash text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare d public.operational_documents;phone text;sid uuid;begin
 select * into d from public.operational_documents where id=p_document;
 perform private.require_cap(d.care_recipient_id,'ent.receive');
 if d.type<>'ENT' or d.status<>'pending_receipt' or d.recipient_id<>auth.uid() or not coalesce((select (settings->>'whatsappSimpleAcceptance')::boolean from public.patient_settings where care_recipient_id=d.care_recipient_id),false) then raise exception 'receipt flow authorization required' using errcode='42501';end if;
 select v.phone into phone from public.verified_phones v join auth.users u on u.id=v.user_id where v.user_id=auth.uid() and u.phone_confirmed_at is not null and '+'||ltrim(u.phone,'+')=v.phone;
 if phone is null or p_hash!~'^[a-f0-9]{64}$' then raise exception 'verified phone required' using errcode='42501';end if;
 insert into public.flow_sessions(care_recipient_id,user_id,token_hash,expires_at,purpose,document_id,document_version,verified_phone)
 values(d.care_recipient_id,auth.uid(),p_hash,now()+interval '10 minutes','ent_receipt',d.id,d.version,phone) returning id into sid;return sid;
end;$function$

CREATE OR REPLACE FUNCTION public.create_stock_inventory(p_care_recipient_id uuid, p_location text)
 RETURNS stock_inventories
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v public.stock_inventories;
begin
  if not public.recipient_can(p_care_recipient_id,'count') then raise exception 'inventory authorization required' using errcode='42501'; end if;
  if p_location is null or p_location not in ('FAMILY','CARE_TEAM') then raise exception 'invalid location'; end if;
  perform pg_advisory_xact_lock(hashtextextended('stock:'||p_care_recipient_id,0));
  insert into public.stock_inventories(care_recipient_id,location,counted_by,reference_at) values(p_care_recipient_id,p_location,auth.uid(),clock_timestamp()) returning * into v;
  -- Snapshot every active product, including zero balances, while movement writers are excluded.
  insert into public.stock_inventory_items(inventory_id,product_id,counted_quantity,expected_quantity,reference_movement_id)
  select v.id,p.product_id,0,coalesce((select balance from public.current_stock_balances where care_recipient_id=p_care_recipient_id and product_id=p.product_id and location=p_location),0),
    (select id from public.stock_movements where care_recipient_id=p_care_recipient_id and product_id=p.product_id and (source_location=p_location or destination_location=p_location) order by movement_revision desc limit 1)
  from public.care_recipient_products p where p.care_recipient_id=p_care_recipient_id and p.is_active;
  insert into public.audit_events(actor_id,action,entity_type,entity_id,metadata) values(auth.uid(),'inventory.created','stock_inventory',v.id,jsonb_build_object('care_recipient_id',p_care_recipient_id));
  return v;
end; $function$

CREATE OR REPLACE FUNCTION public.create_supply_document(p_patient uuid, p_type text, p_payload jsonb, p_key uuid, p_draft boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$declare v_context jsonb;v_result jsonb;v_existing public.operational_documents;begin
 if p_type='BAL' and exists(select 1 from public.bal_regimes where care_recipient_id=p_patient and activated_at is not null) then
 perform private.require_cap(p_patient,'bal.read');
 perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('stock:'||p_patient::text,0));
 perform private.require_cap(p_patient,'bal.read');
 select * into v_existing from public.operational_documents where care_recipient_id=p_patient and created_by=auth.uid() and idempotency_key=p_key and type='BAL';
 if found then if v_existing.payload-'balanceContext'<>p_payload-'balanceContext' then raise exception 'idempotency payload mismatch';end if;return public.operational_document(v_existing.id);end if;
 v_context:=private.bal_count_context(p_patient,null,p_payload);
 p_payload:=(p_payload-'balanceContext')||jsonb_build_object('balanceContext',v_context);
 v_result:=public.fluent_pre_shift_create(p_patient,p_type,p_payload,p_key,p_draft);
 update public.bal_cycles set document_id=(v_result->>'id')::uuid where id=(v_context->>'cycleId')::uuid;
 if not p_draft then perform private.finish_bal_count((v_result->>'id')::uuid,v_context);end if;
 return v_result;end if;
 return public.fluent_pre_shift_create(p_patient,p_type,p_payload-'balanceContext'-'balanceAssignment',p_key,p_draft);
end;$function$

CREATE OR REPLACE FUNCTION public.decline_invitation(p_token_hash text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare i public.care_recipient_invitations;begin
 if private.auth_session() is null then raise exception 'active Auth session required' using errcode='42501';end if;
 select * into i from public.care_recipient_invitations where token_hash=p_token_hash;
 if not found then raise exception 'invalid invitation' using errcode='42501';end if;
 perform pg_advisory_xact_lock(hashtextextended('stock:'||i.care_recipient_id,0));
 select * into strict i from public.care_recipient_invitations where id=i.id for update;
 if i.status<>'pending' or i.expires_at<=now() or not exists(select 1 from auth.users where id=auth.uid() and lower(email)=i.email and email_confirmed_at is not null) then raise exception 'invalid invitation' using errcode='42501';end if;
 update public.care_recipient_invitations set status='revoked' where id=i.id;
 update public.access_change_requests set status='rejected',resolution=resolution||jsonb_build_object('declinedAt',now()) where status='awaiting_acceptance' and resolution->>'invitationId'=i.id::text;
 insert into public.audit_events(actor_id,action,entity_type,entity_id,metadata) values(auth.uid(),'invitation.declined','invitation',i.id,jsonb_build_object('care_recipient_id',i.care_recipient_id));return true;
end;$function$

CREATE OR REPLACE FUNCTION public.enqueue_patient_event(p_patient uuid, p_requisition uuid, p_alert uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare e public.stock_alert_events;m record;begin
 if p_alert is null then return;end if;
 select * into e from public.stock_alert_events where id=p_alert and care_recipient_id=p_patient and state='open';if not found then return;end if;
 for m in select user_id,role from public.care_recipient_memberships where care_recipient_id=p_patient and status='active' and role<>'reader' loop
 if not private.member_can(p_patient,m.user_id,case when e.location='FAMILY' then 'stock.family.read' else 'stock.team.read' end) then continue;end if;
 if e.location='CARE_TEAM' and m.role='family' and not exists(select 1 from public.recipient_notification_settings where care_recipient_id=p_patient and recipient_user_id=m.user_id and recipient_group='family' and include_team_alerts and is_enabled) then continue;end if;
 perform private.enqueue_notice(p_patient,m.user_id,'stock.alert',null,null,e.id);end loop;
end;$function$

CREATE OR REPLACE FUNCTION public.evaluate_stock_alert(p_patient uuid, p_product text, p_location text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare r public.stock_alert_rules;e public.stock_alert_events;balance_now numeric;severity_now text;eid uuid;begin
 if p_location is null then return;end if;
 select * into r from public.stock_alert_rules where care_recipient_id=p_patient and product_id=p_product and location=p_location;
 select * into e from public.stock_alert_events where care_recipient_id=p_patient and product_id=p_product and location=p_location and state='open' for update;
 select coalesce(balance,0) into balance_now from public.current_stock_balances where care_recipient_id=p_patient and product_id=p_product and location=p_location;balance_now:=coalesce(balance_now,0);
 if r.is_enabled then severity_now:=case when balance_now<=r.critical_threshold then 'critical' when balance_now<=r.low_threshold then 'low' end;end if;
 if e.id is not null and e.severity is not distinct from severity_now then update public.stock_alert_events set balance=balance_now,observed_at=now() where id=e.id;return;end if;
 if e.id is not null then update public.stock_alert_events set state='resolved',balance=balance_now,observed_at=now(),resolved_at=now() where id=e.id;end if;
 if severity_now is not null then
 insert into public.stock_alert_events(care_recipient_id,product_id,location,severity,balance,observed_at) values(p_patient,p_product,p_location,severity_now,balance_now,now()) returning id into eid;
 perform public.enqueue_patient_event(p_patient,null,eid);end if;
end;$function$

CREATE OR REPLACE FUNCTION public.extraordinary_stock_adjustment(p_care_recipient_id uuid, p_product_id text, p_quantity integer, p_location text, p_justification text, p_confirmation boolean, p_idempotency_key uuid)
 RETURNS stock_movements
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare v public.stock_movements;v_hash text;
begin
  if not public.is_global_administrator() or not public.recipient_can(p_care_recipient_id,'stock') or not coalesce(p_confirmation,false) then raise exception 'confirmed global administrator required' using errcode='42501'; end if;
  if p_quantity is null or p_quantity=0 or p_quantity=-2147483648 or p_location is null or p_location not in ('FAMILY','CARE_TEAM') or p_idempotency_key is null or p_justification is null or length(trim(p_justification)) not between 1 and 1000 then raise exception 'invalid extraordinary adjustment'; end if;
  v_hash:=encode(digest(jsonb_build_array('extraordinary',p_care_recipient_id,p_product_id,p_quantity,p_location,trim(p_justification))::text,'sha256'),'hex');
  perform pg_advisory_xact_lock(hashtextextended('movement:'||auth.uid()||':'||p_idempotency_key,0));
  select * into v from public.stock_movements where performed_by=auth.uid() and idempotency_key=p_idempotency_key;
  if found then if v.payload_hash is distinct from v_hash then raise exception 'idempotency conflict'; end if;return v;end if;
  if not exists(select 1 from public.care_recipient_products where care_recipient_id=p_care_recipient_id and product_id=p_product_id and is_active) then raise exception 'invalid patient catalogue product'; end if;
  insert into public.stock_movements(product_id,quantity,movement_type,performed_by,justification,care_recipient_id,source_location,destination_location,idempotency_key,reference_type,payload_hash,extraordinary_confirmed)
  values(p_product_id,abs(p_quantity),'adjustment',auth.uid(),trim(p_justification),p_care_recipient_id,case when p_quantity<0 then p_location end,case when p_quantity>0 then p_location end,p_idempotency_key,'extraordinary_adjustment',v_hash,true) returning * into v;
  insert into public.audit_events(actor_id,action,entity_type,entity_id,metadata) values(auth.uid(),'stock.extraordinary.adjustment','stock_movement',v.id,jsonb_build_object('care_recipient_id',p_care_recipient_id,'quantity',p_quantity,'location',p_location,'reason',trim(p_justification),'confirmed',true));
  return v;
end; $function$

CREATE OR REPLACE FUNCTION public.family_stock_movement(p_patient uuid, p_product text, p_quantity numeric, p_action text, p_reason text, p_key uuid, p_reference uuid DEFAULT NULL::uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v public.stock_movements;v_id uuid;h text;begin
 perform private.require_cap(p_patient,'stock.family.manage');
 if p_quantity<=0 or p_quantity is null or p_quantity>1000000000 or p_action not in ('inbound','outbound','correction_in','correction_out') or length(trim(coalesce(p_reason,''))) not between 3 and 1000 or p_key is null then raise exception 'invalid family movement';end if;
 h:=encode(extensions.digest(jsonb_build_array(p_patient,p_product,p_quantity,p_action,trim(p_reason),p_reference)::text,'sha256'),'hex');
 perform pg_advisory_xact_lock(hashtextextended('stock:'||p_patient,0));
 select * into v from public.stock_movements where performed_by=auth.uid() and idempotency_key=p_key;
 if found then if v.payload_hash<>h then raise exception 'idempotency conflict' using errcode='23505';end if;return v.id;end if;
 if p_reference is not null and not exists(select 1 from public.stock_movements where id=p_reference and care_recipient_id=p_patient and product_id=p_product and reference_type='family_manual') then raise exception 'invalid compensation reference';end if;
 v_id:=private.move_stock(p_patient,p_product,p_quantity,case when p_action in ('outbound','correction_out') then 'FAMILY' end,case when p_action in ('inbound','correction_in') then 'FAMILY' end,trim(p_reason),'family_manual',p_reference);
 update public.stock_movements set idempotency_key=p_key,payload_hash=h where id=v_id;
 insert into public.audit_events(actor_id,action,entity_type,entity_id,metadata) values(auth.uid(),'stock.family.'||p_action,'stock_movement',v_id,jsonb_build_object('care_recipient_id',p_patient));
 return v_id;
end;$function$

CREATE OR REPLACE FUNCTION public.finalize_attachment(p_id uuid, p_actor uuid, p_hash text, p_mime text, p_bytes bigint, p_valid boolean)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$declare a public.attachments;begin
 if coalesce(auth.jwt()->>'role','')<>'service_role' then raise exception 'server validation required' using errcode='42501';end if;
 select * into strict a from public.attachments where id=p_id for update;
 if not exists(select 1 from public.profiles where id=p_actor and status='active') or not (case when a.document_id is not null then private.user_can(a.care_recipient_id,p_actor,(select lower(type)||'.read' from public.operational_documents where id=a.document_id)) else private.user_can(a.care_recipient_id,p_actor,'stock.family.manage') end) then raise exception 'evidence permission revoked' using errcode='42501';end if;
 if p_hash is null or p_valid is null or a.uploaded_by<>p_actor or a.bytes<>p_bytes or a.mime_type<>p_mime or p_hash!~'^[a-f0-9]{64}$' then raise exception 'attachment integrity mismatch';end if;
 if a.state<>'quarantine' then if a.sha256<>p_hash then raise exception 'immutable attachment';end if;return;end if;
 update public.attachments set state=case when p_valid then 'ready' else 'rejected' end,sha256=p_hash,confirmed_at=now() where id=p_id;
 insert into public.audit_events(actor_id,action,entity_type,entity_id,metadata) values(p_actor,case when p_valid then 'attachment.validated' else 'attachment.rejected' end,'attachment',p_id,jsonb_build_object('care_recipient_id',a.care_recipient_id,'document_id',a.document_id,'sha256',p_hash));
end;$function$

CREATE OR REPLACE FUNCTION public.flow_exchange(p_hash text, p_submit jsonb DEFAULT NULL::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare s public.flow_sessions;d public.operational_documents;v_line public.document_lines;q numeric;state jsonb;diffs jsonb;result jsonb;claims text;sub text;previous text;summary text;begin
 if coalesce(auth.jwt()->>'role','')<>'service_role' then raise exception 'verified Flow endpoint required' using errcode='42501';end if;
 select * into s from public.flow_sessions where token_hash=p_hash for update;
 if not found or s.expires_at<=now() then raise exception 'flow session expired' using errcode='42501';end if;
 if s.purpose='occurrence' then
 if p_submit is null then return public.v3_flow_exchange(p_hash,null)||jsonb_build_object('screen','REPORT_MODE','purpose','occurrence');end if;
 if p_submit->>'operation'='occurrence_mode' and p_submit->>'kind' in ('consumption','shortage') then
 update public.flow_sessions set payload_state=jsonb_build_object('kind',p_submit->>'kind') where id=s.id;
 return public.v3_flow_exchange(p_hash,null)||jsonb_build_object('screen','REPORT','kind',p_submit->>'kind','purpose','occurrence');end if;
 if p_submit->>'kind'='no_issues' then
 if not private.member_can(s.care_recipient_id,s.user_id,'consumption.report') or s.used_at is not null then raise exception 'flow session expired or revoked' using errcode='42501';end if;
 insert into public.flow_submissions(session_id,care_recipient_id,user_id,body,status) values(s.id,s.care_recipient_id,s.user_id,p_submit,'no_issues');
 update public.flow_sessions set used_at=now() where id=s.id;
 insert into public.audit_events(actor_id,action,entity_type,entity_id,metadata) values(s.user_id,'shift.no_issues','flow',s.id,jsonb_build_object('care_recipient_id',s.care_recipient_id,'stockChanged',false));
 return jsonb_build_object('purpose','occurrence','pendingConfirmation',false,'noIssues',true);end if;
 return public.v3_flow_exchange(p_hash,p_submit);end if;
 if not private.member_can(s.care_recipient_id,s.user_id,'ent.receive') then raise exception 'Flow recipient revoked' using errcode='42501';end if;
 if s.used_at is not null then
 if p_submit->>'operation'='confirm' then return s.payload_state->'result';end if;
 raise exception 'Flow token already used' using errcode='42501';end if;
 perform pg_advisory_xact_lock(hashtextextended('stock:'||s.care_recipient_id,0));
 select * into strict d from public.operational_documents where id=s.document_id for update;
 if d.recipient_id<>s.user_id or d.version<>s.document_version or d.status<>'pending_receipt'
 or not coalesce((select (settings->>'whatsappSimpleAcceptance')::boolean from public.patient_settings where care_recipient_id=d.care_recipient_id),false)
 or not exists(select 1 from public.verified_phones v join auth.users u on u.id=v.user_id where v.user_id=s.user_id and v.phone=s.verified_phone and '+'||ltrim(u.phone,'+')=v.phone and u.phone_confirmed_at is not null) then raise exception 'stale or unauthorized receipt Flow' using errcode='42501';end if;
 state:=s.payload_state;
 if p_submit->>'operation'='mode' and p_submit->>'mode'='all' then state:='{}';update public.flow_sessions set payload_state=state where id=s.id;end if;
 if p_submit->>'operation'='mode' and p_submit->>'mode' not in ('all','divergence') then raise exception 'invalid receipt mode';end if;
 if p_submit->>'operation'='line' then
 select * into v_line from public.document_lines where document_id=d.id and id=(p_submit->>'lineId')::uuid;
 q:=(p_submit->>'acceptedQuantity')::numeric;
 if not found or q is null or q<0 or q>v_line.quantity or q<>round(q,(select quantity_decimals from public.care_recipient_products where care_recipient_id=d.care_recipient_id and product_id=v_line.product_id)) or length(coalesce(p_submit->>'notes',''))>1000 then raise exception 'invalid Flow divergence';end if;
 state:=state||jsonb_build_object(v_line.id::text,jsonb_build_object('lineId',v_line.id,'acceptedQuantity',q::text,'notes',p_submit->>'notes'));
 update public.flow_sessions set payload_state=state where id=s.id;
 end if;
 select coalesce(jsonb_agg(value),'[]') into diffs from jsonb_each(state);
 select string_agg(l.name_snapshot||': expedido '||l.quantity::text||', aceito '||coalesce(state->l.id::text->>'acceptedQuantity',l.quantity::text),E'\n' order by l.name_snapshot) into summary from public.document_lines l where l.document_id=d.id;
 if p_submit->>'operation'='confirm' then
 if not s.review_ready then raise exception 'receipt review required';end if;
 insert into private.worker_authority values(pg_backend_pid(),txid_current(),s.user_id,s.care_recipient_id,'verified_whatsapp_flow_receipt');
 claims:=current_setting('request.jwt.claims',true);sub:=current_setting('request.jwt.claim.sub',true);previous:=current_setting('hca.verified_whatsapp_provider',true);
 perform set_config('request.jwt.claims',jsonb_build_object('sub',s.user_id,'role','authenticated')::text,true);perform set_config('request.jwt.claim.sub',s.user_id::text,true);
 perform set_config('hca.verified_whatsapp_provider','flow:'||s.id,true);
 result:=public.supply_document_command(d.id,'receive',jsonb_build_object('divergences',diffs),s.id,d.version);
 perform set_config('request.jwt.claims',coalesce(claims,''),true);perform set_config('request.jwt.claim.sub',coalesce(sub,''),true);perform set_config('hca.verified_whatsapp_provider',coalesce(previous,''),true);
 delete from private.worker_authority where backend_pid=pg_backend_pid() and transaction_id=txid_current();
 result:=jsonb_build_object('purpose','ent_receipt','accepted',true,'documentId',d.id,'status',result->>'status');
 update public.flow_sessions set used_at=now(),payload_state=jsonb_build_object('result',result) where id=s.id;
 insert into public.flow_submissions(session_id,care_recipient_id,user_id,body,status) values(s.id,s.care_recipient_id,s.user_id,jsonb_build_object('divergences',diffs),'accepted');
 return result;
 end if;
 if p_submit->>'operation'='mode' and p_submit->>'mode'='all' or p_submit->>'operation'='line' and p_submit->>'next'='review' then update public.flow_sessions set review_ready=true where id=s.id;
 elsif p_submit is not null then update public.flow_sessions set review_ready=false where id=s.id;end if;
 return jsonb_build_object('purpose','ent_receipt','screen',case when p_submit is null then 'RECEIPT_MODE' when p_submit->>'operation'='mode' and p_submit->>'mode'='divergence' or p_submit->>'operation'='line' and p_submit->>'next'='another' then 'RECEIPT_LINE' else 'RECEIPT_REVIEW' end,
 'documentCode',d.code,'reviewText',summary,
 'lines',(select jsonb_agg(jsonb_build_object('id',l.id,'title',l.name_snapshot||' - expedido '||l.quantity::text||' '||l.unit_snapshot) order by l.name_snapshot) from public.document_lines l where document_id=d.id));
end;$function$

CREATE OR REPLACE FUNCTION public.global_patient_administration(p_patient uuid, p_section text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
 if not public.is_global_administrator() or not exists(select 1 from public.care_recipients where id=p_patient) then raise exception 'global administration required' using errcode='42501';end if;
 case p_section
 when 'catalog' then return coalesce((select jsonb_agg(to_jsonb(c)||jsonb_build_object('id',c.product_id) order by c.sort_order,c.name) from public.care_recipient_products c where care_recipient_id=p_patient),'[]');
 when 'products' then return coalesce((select jsonb_agg(to_jsonb(p) order by p.name) from public.products p where p.owner_care_recipient_id is null and p.is_active),'[]');
 when 'memberships' then return coalesce((select jsonb_agg(to_jsonb(m)||jsonb_build_object('full_name',p.full_name) order by p.full_name) from public.care_recipient_memberships m join public.profiles p on p.id=m.user_id where m.care_recipient_id=p_patient),'[]');
 when 'alerts' then return coalesce((select jsonb_agg(to_jsonb(r)) from public.stock_alert_rules r where care_recipient_id=p_patient),'[]');
 when 'notificationRecipients' then return coalesce((select jsonb_agg(to_jsonb(r)) from public.recipient_notification_settings r where care_recipient_id=p_patient),'[]');
 else raise exception 'patient operating context required' using errcode='42501';end case;
end;$function$

CREATE OR REPLACE FUNCTION public.governance_legacy_patient_access(p_patient uuid, p_kind text, p_change jsonb, p_key uuid, p_version integer, p_request_id uuid DEFAULT NULL::uuid, p_decision text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
 perform private.require_cap(p_patient,'access.manage');
 if p_request_id is null then
 if jsonb_typeof(p_change) is distinct from 'object' then raise exception 'invalid access change';end if;
 if p_kind='settings' then
 if exists(select 1 from jsonb_each(p_change) e where
 e.key='balDay' and not(e.value='null'::jsonb or jsonb_typeof(e.value)='number' and e.value::text~'^[0-6]$')
 or e.key='balReview' and (jsonb_typeof(e.value)<>'string' or e.value#>>'{}' not in ('optional','required'))
 or e.key='balRequirement' and (jsonb_typeof(e.value)<>'string' or e.value#>>'{}' not in ('any','all'))
 or e.key='whatsappSimpleAcceptance' and jsonb_typeof(e.value)<>'boolean'
 or e.key='balApprovers' and jsonb_typeof(e.value)<>'array') then raise exception 'invalid settings';end if;
 if p_change ? 'balApprovers' and (
 jsonb_array_length(p_change->'balApprovers') not between 1 and 2
 or exists(select 1 from jsonb_array_elements(p_change->'balApprovers') a where jsonb_typeof(a)<>'string' or a#>>'{}' not in ('family','supervisor'))
 or (select count(distinct a) from jsonb_array_elements(p_change->'balApprovers') a)<>jsonb_array_length(p_change->'balApprovers')) then raise exception 'invalid approvers';end if;
 elsif p_kind='capability' then
 if exists(select 1 from jsonb_object_keys(p_change) k where k not in ('capability','subjectUser','subjectRole','enabled'))
 or p_change ? 'subjectRole' and coalesce(p_change->>'subjectRole','') not in ('admin','family','supervisor','professional','reader') then raise exception 'invalid capability subject';end if;
 elsif p_kind='membership' then
 if exists(select 1 from jsonb_object_keys(p_change) k where k not in ('userId','role'))
 or coalesce(p_change->>'role','') not in ('admin','family','supervisor','professional','reader')
 or p_change->>'userId' is null then raise exception 'invalid membership change';end if;
 end if;
 end if;
 return public.validated_legacy_patient_access(p_patient,p_kind,p_change,p_key,p_version,p_request_id,p_decision);
end;$function$

CREATE OR REPLACE FUNCTION public.guard_patient_product_owner()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_owner uuid;
begin
  select owner_care_recipient_id into v_owner from public.products where id=new.product_id;
  if v_owner is not null and v_owner<>new.care_recipient_id then raise exception 'exclusive product belongs to another patient' using errcode='23514';end if;
  return new;
end; $function$

CREATE OR REPLACE FUNCTION public.guard_stock_movement_balance()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare s numeric:=0;t numeric:=0;precision_limit integer;
begin
 if new.care_recipient_id is null then raise exception 'patient required';end if;
 perform pg_advisory_xact_lock(hashtextextended('stock:'||new.care_recipient_id,0));
 select quantity_decimals into precision_limit from public.care_recipient_products where care_recipient_id=new.care_recipient_id and product_id=new.product_id;
 if new.quantity<>round(new.quantity,precision_limit) then raise exception 'incompatible product precision';end if;
 if new.source_location is null and new.destination_location is null or new.source_location=new.destination_location then raise exception 'invalid stock locations';end if;
 new.movement_revision:=nextval(pg_get_serial_sequence('public.stock_movements','movement_revision'));
 if new.source_location is not null then
 select coalesce(sum(case when destination_location=new.source_location then quantity else 0 end-case when source_location=new.source_location then quantity else 0 end),0)
 into s from public.stock_movements where care_recipient_id=new.care_recipient_id and product_id=new.product_id;
 if s<new.quantity and not(new.extraordinary_confirmed and new.reference_type='extraordinary_adjustment' and public.is_global_administrator()) then raise exception 'insufficient stock' using errcode='23514';end if;
 new.source_balance_before:=s;new.source_balance_after:=s-new.quantity;
 end if;
 if new.destination_location is not null then
 select coalesce(sum(case when destination_location=new.destination_location then quantity else 0 end-case when source_location=new.destination_location then quantity else 0 end),0)
 into t from public.stock_movements where care_recipient_id=new.care_recipient_id and product_id=new.product_id;
 new.destination_balance_before:=t;new.destination_balance_after:=t+new.quantity;
 end if;
 return new;
end;$function$

CREATE OR REPLACE FUNCTION public.inbound_report_context(p_phone text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare u uuid;p uuid;begin
 if coalesce(auth.role(),'')<>'service_role' then raise exception 'webhook worker required' using errcode='42501';end if;
 select v.user_id into u from public.verified_phones v join auth.users a on a.id=v.user_id where v.phone='+'||ltrim(p_phone,'+') and '+'||ltrim(a.phone,'+')=v.phone and a.phone_confirmed_at is not null;
 if u is null or (select count(*) from public.care_recipient_memberships where user_id=u and status='active' and private.user_can(care_recipient_id,u,'consumption.report'))<>1 then return null;end if;
 select care_recipient_id into p from public.care_recipient_memberships where user_id=u and status='active' and private.user_can(care_recipient_id,u,'consumption.report');
 return jsonb_build_object('patientId',p,'userId',u,'catalog',coalesce((select jsonb_agg(jsonb_build_object('id',product_id,'name',name,'aliases',aliases,'unit',unit)) from public.care_recipient_products where care_recipient_id=p and is_active),'[]'));
end;$function$

CREATE OR REPLACE FUNCTION public.ingest_whatsapp_report(p_provider_id text, p_phone text, p_text text, p_lines jsonb, p_kind text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare c jsonb;result jsonb;begin
 if coalesce(auth.jwt()->>'role','')<>'service_role' then raise exception 'webhook worker required' using errcode='42501';end if;
 c:=public.inbound_report_context(p_phone);if c is null then return jsonb_build_object('needsAuthenticatedSelection',true);end if;
 insert into private.worker_authority values(pg_backend_pid(),txid_current(),(c->>'userId')::uuid,(c->>'patientId')::uuid,'pending_whatsapp_report');
 result:=public.v3_ingest_whatsapp_report(p_provider_id,p_phone,p_text,p_lines,p_kind);
 delete from private.worker_authority where backend_pid=pg_backend_pid() and transaction_id=txid_current();return result;
end;$function$

CREATE OR REPLACE FUNCTION public.issue_reminder_challenge(p_notification uuid, p_worker uuid, p_hash text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare n public.requisition_notifications;phone text;begin
 if coalesce(auth.jwt()->>'role','')<>'service_role' or not public.validate_notification_job(p_notification,p_worker) then raise exception 'verified worker required' using errcode='42501';end if;
 select * into n from public.requisition_notifications where id=p_notification;
 if n.event_key<>'shift.reminder' or not exists(select 1 from public.operational_reminders where id=n.reminder_id and user_id=n.recipient_user_id and kind='shift' and acknowledged_at is null) then return false;end if;
 select v.phone into phone from public.verified_phones v join auth.users u on u.id=v.user_id where v.user_id=n.recipient_user_id and u.phone_confirmed_at is not null and '+'||ltrim(u.phone,'+')=v.phone and ltrim(v.phone,'+')=ltrim(n.destination,'+');
 if phone is null then return false;end if;
 insert into public.reminder_challenges(reminder_id,user_id,phone,token_hash,expires_at) values(n.reminder_id,n.recipient_user_id,phone,p_hash,now()+interval '20 minutes');return true;
end;$function$

CREATE OR REPLACE FUNCTION public.issue_science_challenge(p_notification uuid, p_worker uuid, p_hash text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare n public.requisition_notifications;s public.requisition_lifecycle;d public.operational_documents;phone text;begin
 if coalesce(auth.jwt()->>'role','')<>'service_role' or not public.validate_notification_job(p_notification,p_worker) then raise exception 'verified worker required' using errcode='42501';end if;
 select * into n from public.requisition_notifications where id=p_notification;
 select * into d from public.operational_documents where id=n.document_id;
 select * into s from public.requisition_lifecycle where requisition_id=d.id;
 if d.type<>'REQ' or d.status='cancelled' or n.event_key<>'req.issued' or not(n.recipient_user_id=any(s.eligible_users))
 or not coalesce((s.policy->>'scienceWhatsApp')::boolean,false)
 or not coalesce((select (notification_preferences->>'scienceWhatsApp')::boolean from public.profiles where id=n.recipient_user_id),false)
 or not private.member_can(d.care_recipient_id,n.recipient_user_id,'req.science')
 or not exists(select 1 from public.document_events where id=n.document_event_id and version=d.version)
 or not exists(select 1 from public.meta_template_versions where name='hca_req_ciencia_simplificada_v4' and approval='APPROVED') then return false;end if;
 select v.phone into phone from public.verified_phones v join auth.users u on u.id=v.user_id where v.user_id=n.recipient_user_id and u.phone_confirmed_at is not null and '+'||ltrim(u.phone,'+')=v.phone and ltrim(v.phone,'+')=ltrim(n.destination,'+');
 if phone is null then return false;end if;
 insert into public.science_challenges(notification_id,document_id,recipient_id,token_hash,phone,document_version,expires_at) values(n.id,d.id,n.recipient_user_id,p_hash,phone,d.version,now()+interval '10 minutes');return true;
end;$function$

CREATE OR REPLACE FUNCTION public.issue_whatsapp_challenge(p_notification uuid, p_worker uuid, p_hash text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare n public.requisition_notifications;d public.operational_documents;p text;begin
 if coalesce(auth.role(),'')<>'service_role' or not public.validate_notification_job(p_notification,p_worker) then raise exception 'verified worker required' using errcode='42501';end if;
 if p_hash is null or p_hash!~'^[a-f0-9]{64}$' then raise exception 'invalid challenge hash';end if;
 select * into n from public.requisition_notifications where id=p_notification;
 select * into d from public.operational_documents where id=n.document_id;
 if d.type<>'ENT' or d.status<>'pending_receipt' or d.recipient_id<>n.recipient_user_id or not private.user_can(d.care_recipient_id,d.recipient_id,'ent.receive')
 or not coalesce((select (settings->>'whatsappSimpleAcceptance')::boolean from public.patient_settings where care_recipient_id=d.care_recipient_id),false)
 or not exists(select 1 from public.document_events where id=n.document_event_id and version=d.version) then return null;end if;
 select v.phone into p from public.verified_phones v join auth.users u on u.id=v.user_id and '+'||ltrim(u.phone,'+')=v.phone and u.phone_confirmed_at is not null where v.user_id=d.recipient_id;
 if p is null or ltrim(p,'+')<>ltrim(n.destination,'+') then return null;end if;
 insert into public.whatsapp_challenges(document_id,recipient_id,token_hash,phone,expires_at,document_version) values(d.id,d.recipient_id,p_hash,p,now()+interval '10 minutes',d.version);
 return jsonb_build_object('enabled',true);
end;$function$

CREATE OR REPLACE FUNCTION public.legacy_import_historical_requisitions(p_source_hash text, p_rows jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare
  b public.requisition_import_batches;x jsonb;v_lines jsonb;v_extras jsonb;v_observations jsonb;
  v_hash text;v_row_hash text;v_id uuid;v_recipient uuid;v_protocol text;
  v_report jsonb:='[]';v_imported integer:=0;v_rejected integer:=0;
begin
  if auth.uid() is null or jsonb_typeof(p_rows) is distinct from 'array' or jsonb_array_length(p_rows) not between 1 and 1000 then raise exception 'invalid import';end if;
  -- Authorize every patient before replaying any report or processing rows.
  for x in select value from jsonb_array_elements(p_rows) loop
    v_recipient:=(x->>'careRecipientId')::uuid;
    if v_recipient is null or not public.recipient_can(v_recipient,'admin') then raise exception 'import authorization required' using errcode='42501';end if;
  end loop;
  v_hash:=encode(digest(p_rows::text,'sha256'),'hex');
  perform pg_advisory_xact_lock(hashtextextended('historical-import',0));
  select * into b from public.requisition_import_batches where source_hash=v_hash;
  if found then return jsonb_build_object('batchId',b.id,'total',b.total_rows,'imported',b.imported_rows,'rejected',b.rejected_rows,'report',b.report,'replayed',true);end if;
  insert into public.requisition_import_batches(source_hash,imported_by,total_rows) values(v_hash,auth.uid(),jsonb_array_length(p_rows)) returning * into b;
  for x in select value from jsonb_array_elements(p_rows) loop
    begin
      v_lines:=coalesce(x->'lines','[]'::jsonb);v_extras:=coalesce(x->'extraItems','[]'::jsonb);v_observations:=coalesce(x->'observations','[]'::jsonb);
      if jsonb_typeof(x) is distinct from 'object' or jsonb_typeof(x->'physicalProtocol') is distinct from 'number'
        or (x->>'physicalProtocol')!~'^[1-9]$|^1[01]$'
        or jsonb_typeof(v_lines) is distinct from 'array' or jsonb_array_length(v_lines)>1000
        or jsonb_typeof(v_extras) is distinct from 'array' or jsonb_array_length(v_extras)>20
        or jsonb_array_length(v_lines)+jsonb_array_length(v_extras)=0
        or jsonb_typeof(v_observations) is distinct from 'array' or jsonb_array_length(v_observations)>50
        or exists(select 1 from jsonb_object_keys(x) k where k not in ('physicalProtocol','careRecipientId','createdAt','requesterName','status','lines','extraItems','observations')) then raise exception 'invalid row';end if;
      v_recipient:=(x->>'careRecipientId')::uuid;v_protocol:='HC-'||lpad(x->>'physicalProtocol',6,'0');v_row_hash:=encode(digest(x::text,'sha256'),'hex');
      if exists(select 1 from public.requisitions where protocol=v_protocol) then raise exception 'duplicate protocol';end if;
      if exists(select 1 from jsonb_array_elements(v_lines) l where jsonb_typeof(l) is distinct from 'object'
        or jsonb_typeof(l->'productId') is distinct from 'string'
        or not exists(select 1 from public.care_recipient_products c where c.care_recipient_id=v_recipient and c.product_id=l->>'productId')
        or exists(select 1 from jsonb_object_keys(l) k where k not in ('productId','currentStock','urgent')))
        or exists(select 1 from jsonb_array_elements(v_lines) l group by l->>'productId' having count(*)>1) then raise exception 'invalid patient product';end if;
      if exists(select 1 from jsonb_array_elements(v_extras) e where jsonb_typeof(e) is distinct from 'object'
        or jsonb_typeof(e->'customName') is distinct from 'string' or length(trim(e->>'customName')) not between 1 and 200
        or exists(select 1 from jsonb_object_keys(e) k where k not in ('customName','currentStock','urgent'))) then raise exception 'invalid historical extra item';end if;
      if exists(select 1 from jsonb_array_elements(v_lines||v_extras) i where
        case when coalesce(jsonb_typeof(i->'currentStock'),'null')='null' then false
          when jsonb_typeof(i->'currentStock')='number' then (i->>'currentStock')!~'^[0-9]+$' or (i->>'currentStock')::numeric>100000
          else true end
        or (i ? 'urgent' and jsonb_typeof(i->'urgent') is distinct from 'boolean')) then raise exception 'invalid historical count';end if;
      if (x ? 'requesterName' and coalesce(jsonb_typeof(x->'requesterName'),'null') not in ('string','null'))
        or (x->>'requesterName' is not null and length(trim(x->>'requesterName')) not between 1 and 160)
        or (x ? 'createdAt' and coalesce(jsonb_typeof(x->'createdAt'),'null') not in ('string','null'))
        or (x ? 'status' and coalesce(jsonb_typeof(x->'status'),'null') not in ('string','null')) then raise exception 'invalid historical source facts';end if;
      if exists(select 1 from jsonb_array_elements(v_observations) o where jsonb_typeof(o) is distinct from 'string' or length(trim(o#>>'{}')) not between 1 and 1000) then raise exception 'invalid observation';end if;
      insert into public.requisitions(protocol,created_by,care_recipient_id,status,idempotency_key,payload_hash,is_historical,created_at,updated_at,requester_name_snapshot,recipient_name_snapshot)
      values(v_protocol,null,v_recipient,(x->>'status')::public.requisition_status,gen_random_uuid(),v_row_hash,true,(x->>'createdAt')::timestamptz,now(),nullif(trim(x->>'requesterName'),''),(select display_name from public.care_recipients where id=v_recipient)) returning id into v_id;
      insert into public.requisition_items(requisition_id,product_id,current_stock,urgent,product_name_snapshot,category_snapshot,unit_snapshot,snapshot_source)
      select v_id,c.product_id,(l->>'currentStock')::integer,coalesce((l->>'urgent')::boolean,false),c.name,c.category::text,c.unit,'legacy_reconstructed'
      from jsonb_array_elements(v_lines) l join public.care_recipient_products c on c.care_recipient_id=v_recipient and c.product_id=l->>'productId';
      -- Preserve custom names literally. A coinciding catalogue name is not proof
      -- of a product identity and must never become an automatic association.
      insert into public.requisition_items(requisition_id,custom_name,current_stock,urgent,product_name_snapshot,snapshot_source)
      select v_id,trim(e->>'customName'),(e->>'currentStock')::integer,coalesce((e->>'urgent')::boolean,false),trim(e->>'customName'),'legacy_reconstructed'
      from jsonb_array_elements(v_extras) e;
      insert into public.requisition_observations(requisition_id,created_by,body) select v_id,auth.uid(),trim(value) from jsonb_array_elements_text(v_observations);
      insert into public.historical_requisition_imports(batch_id,physical_protocol,requisition_id,row_hash) values(b.id,(x->>'physicalProtocol')::integer,v_id,v_row_hash);
      v_imported:=v_imported+1;v_report:=v_report||jsonb_build_array(jsonb_build_object('row',x->>'physicalProtocol','status','imported'));
    exception when others then
      v_rejected:=v_rejected+1;v_report:=v_report||jsonb_build_array(jsonb_build_object('row',x->>'physicalProtocol','status','rejected','reason','invalid or duplicate record'));
    end;
  end loop;
  update public.requisition_import_batches set imported_rows=v_imported,rejected_rows=v_rejected,report=v_report where id=b.id;
  insert into public.audit_events(actor_id,action,entity_type,entity_id,metadata) values(auth.uid(),'requisition.import.completed','requisition_import_batch',b.id,jsonb_build_object('imported',v_imported,'rejected',v_rejected));
  return jsonb_build_object('batchId',b.id,'total',jsonb_array_length(p_rows),'imported',v_imported,'rejected',v_rejected,'report',v_report,'replayed',false);
end; $function$

CREATE OR REPLACE FUNCTION public.legacy_transition_requisition_status(p_requisition_id uuid, p_to_status requisition_status, p_reason text DEFAULT NULL::text)
 RETURNS requisitions
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare r public.requisitions; v_from public.requisition_status;
begin
  select * into r from public.requisitions where id=p_requisition_id for update;
  if not found or not public.recipient_can(r.care_recipient_id,'review') then raise exception 'status transition not authorized' using errcode='42501'; end if;
  if not coalesce((r.status,p_to_status) in (('submitted','under_review'),('submitted','cancelled'),('under_review','approved'),('under_review','cancelled'),('approved','separated'),('separated','delivered')),false)
    then raise exception 'invalid status transition'; end if;
  if p_reason is null or length(trim(p_reason)) not between 1 and 1000 then raise exception 'transition reason required'; end if;
  v_from:=r.status;
  update public.requisitions set status=p_to_status,updated_at=now() where id=r.id returning * into r;
  update public.requisition_status_history set reason=trim(p_reason) where id=(select id from public.requisition_status_history where requisition_id=r.id order by changed_at desc,id desc limit 1);
  insert into public.audit_events(actor_id,action,entity_type,entity_id,metadata) values(auth.uid(),'requisition.status.changed','requisition',r.id,jsonb_build_object('care_recipient_id',r.care_recipient_id,'from',v_from,'to',p_to_status));
  return r;
end; $function$

CREATE OR REPLACE FUNCTION public.normalize_local_capabilities()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$begin
  new.can_manage_stock:=new.role='admin' and coalesce(new.can_manage_stock,false);
  new.can_count_stock:=new.role in ('admin','supervisor','professional') and coalesce(new.can_count_stock,false);
  return new;
end;$function$

CREATE OR REPLACE FUNCTION public.notification_document_payload(p_id uuid, p_worker_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare n public.requisition_notifications;d public.operational_documents;e public.document_events;begin
 if not public.validate_notification_job(p_id,p_worker_id) then raise exception 'invalid notification job' using errcode='42501';end if;
 select * into n from public.requisition_notifications where id=p_id;
 select * into d from public.operational_documents where id=coalesce(n.document_id,n.requisition_id);
 if not found then return null;end if;
 if n.document_event_id is not null then select * into e from public.document_events where id=n.document_event_id;
 else select * into e from public.document_events where document_id=d.id order by version limit 1;end if;
 return jsonb_build_object('documentId',d.id,'patientId',d.care_recipient_id,'code',d.code,'type',d.type,'protocol',d.protocol,'version',e.version,'snapshot',e.body,'hash',e.content_hash,
 'eventKey',coalesce(n.event_key,e.action),'recipientName',n.recipient_label,'isDesignatedRecipient',n.recipient_user_id=d.recipient_id,'includePdf',n.include_pdf,
 'shortPatientName',coalesce((select nullif(settings->>'patientShortName','') from public.patient_settings where care_recipient_id=d.care_recipient_id),e.body->'actors'->'patient'->>'name'));
end;$function$

CREATE OR REPLACE FUNCTION public.notification_notice_payload(p_id uuid, p_worker uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare n public.requisition_notifications;e public.stock_alert_events;r public.consumption_reports;rem public.operational_reminders;values jsonb;begin
 if coalesce(auth.jwt()->>'role','')<>'service_role' or not public.validate_notification_job(p_id,p_worker) then raise exception 'verified worker required' using errcode='42501';end if;
 select * into strict n from public.requisition_notifications where id=p_id;
 values:=jsonb_build_object('nome_destinatario',n.recipient_label,'nome_paciente',(select coalesce(nullif(s.settings->>'patientShortName',''),c.display_name) from public.care_recipients c left join public.patient_settings s on s.care_recipient_id=c.id where c.id=n.care_recipient_id));
 if n.alert_event_id is not null then
 select * into e from public.stock_alert_events where id=n.alert_event_id;
 values:=values||jsonb_build_object('nome_produto',(select name from public.care_recipient_products where care_recipient_id=e.care_recipient_id and product_id=e.product_id),'nome_local',case when e.location='FAMILY' then 'Família' else 'Equipe' end,'saldo_atual',e.balance::text,'saldo_minimo',(select low_threshold::text from public.stock_alert_rules where care_recipient_id=e.care_recipient_id and product_id=e.product_id and location=e.location),'data_hora',to_char(e.observed_at at time zone 'America/Sao_Paulo','DD/MM/YYYY "às" HH24"h"MI'));
 return jsonb_build_object('event','stock.alert','suffix',e.product_id||'&careRecipientId='||e.care_recipient_id,'values',values);
 elsif n.consumption_report_id is not null then
 select * into r from public.consumption_reports where id=n.consumption_report_id;
 values:=values||jsonb_build_object('tipo_evento',case when r.kind='shortage' then 'Falta de material' else 'Consumo extraordinário para revisão' end,'data_hora',to_char(r.created_at at time zone 'America/Sao_Paulo','DD/MM/YYYY "às" HH24"h"MI'));
 return jsonb_build_object('event','occurrence.received','suffix',r.id::text||'&careRecipientId='||r.care_recipient_id,'values',values);
 elsif n.reminder_id is not null then
 select * into rem from public.operational_reminders where id=n.reminder_id;
 values:=values||jsonb_build_object('data_prevista',to_char(rem.expected_at at time zone 'America/Sao_Paulo','DD/MM/YYYY HH24:MI'),'quantidade_itens',(select count(*)::text from public.care_recipient_products where care_recipient_id=rem.care_recipient_id and is_active),'periodo_plantao',to_char(rem.expected_at at time zone 'America/Sao_Paulo','DD/MM/YYYY HH24:MI'));
 return jsonb_build_object('event',case when rem.kind='bal' then 'bal.reminder' else 'shift.reminder' end,'suffix',rem.id::text||'&careRecipientId='||rem.care_recipient_id,'values',values);end if;
 return null;
end;$function$

CREATE OR REPLACE FUNCTION public.notification_safe_failure(p_reference text, p_code text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$begin
 if coalesce(auth.role(),'')<>'service_role' then raise exception 'verified provider worker required' using errcode='42501';end if;
