CREATE OR REPLACE FUNCTION public.process_internal_notifications(p_limit integer DEFAULT 50)
 RETURNS TABLE(processed integer, external_pending integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_processed integer;v_external integer;
begin
  if not public.is_global_administrator() then raise exception 'notification processing not authorized' using errcode='42501';end if;
  update public.requisition_notifications set state='delivered',attempts=attempts+1,attempted_at=now(),delivered_at=now(),provider_reference='internal'
    where id in(select n.id from public.requisition_notifications n join public.profiles p on p.id=n.recipient_user_id and p.status='active'
      where n.state='pending' and n.channel='internal' and public.can_access_recipient(n.care_recipient_id)
        and (p.role='admin' and p.global_scope or exists(select 1 from public.care_recipient_memberships m where m.care_recipient_id=n.care_recipient_id and m.user_id=p.id and m.status='active'))
      order by n.created_at for update of n skip locked limit greatest(1,least(coalesce(p_limit,50),100)));
  get diagnostics v_processed=row_count;
  select count(*) into v_external from public.requisition_notifications where state='pending' and channel<>'internal';
  return query select v_processed,v_external;
end; $function$

CREATE OR REPLACE FUNCTION public.protect_last_global_admin()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_old boolean:=false; v_new boolean:=false;
begin
  if tg_op<>'INSERT' then v_old:=old.status='active' and old.role='admin' and old.global_scope; end if;
  if tg_op<>'DELETE' then v_new:=new.status='active' and new.role='admin' and new.global_scope; end if;
  if v_old and not v_new then
    update public.global_admin_guard set active_count=active_count-1 where singleton and active_count>1;
    if not found then raise exception 'last global administrator cannot be removed' using errcode='23514'; end if;
  elsif v_new and not v_old then
    update public.global_admin_guard set active_count=active_count+1 where singleton;
  end if;
  if tg_op='DELETE' then return old; end if;
  return new;
end; $function$

CREATE OR REPLACE FUNCTION public.protect_requisition_identity()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$ begin
  if (new.protocol,new.protocol_number,new.created_by,new.care_recipient_id,new.idempotency_key,new.request_intent,new.payload_hash)
    is distinct from (old.protocol,old.protocol_number,old.created_by,old.care_recipient_id,old.idempotency_key,old.request_intent,old.payload_hash)
  then raise exception 'requisition identity is immutable'; end if;
  return new;
end; $function$

CREATE OR REPLACE FUNCTION public.record_requisition_status_transition()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if new.status is distinct from old.status then
    insert into public.requisition_status_history (
      requisition_id, from_status, to_status, changed_by
    ) values (
      new.id, old.status, new.status, auth.uid()
    );
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.record_stock_movement(p_care_recipient_id uuid, p_product_id text, p_quantity integer, p_movement_type stock_movement_type, p_source_location text, p_destination_location text, p_justification text, p_idempotency_key uuid DEFAULT NULL::uuid, p_reference_type text DEFAULT NULL::text, p_reference_id uuid DEFAULT NULL::uuid)
 RETURNS stock_movements
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare v public.stock_movements;v_hash text;
begin
  if not public.recipient_can(p_care_recipient_id,'stock') then raise exception 'stock management not authorized' using errcode='42501'; end if;
  if p_quantity is null or p_quantity<=0 or p_movement_type is null or p_justification is null or length(trim(p_justification)) not between 1 and 1000 or p_idempotency_key is null then raise exception 'invalid stock movement'; end if;
  v_hash:=encode(digest(jsonb_build_array(p_care_recipient_id,p_product_id,p_quantity,p_movement_type,p_source_location,p_destination_location,trim(p_justification),p_reference_type,p_reference_id)::text,'sha256'),'hex');
  perform pg_advisory_xact_lock(hashtextextended('movement:'||auth.uid()||':'||p_idempotency_key,0));
  select * into v from public.stock_movements where performed_by=auth.uid() and idempotency_key=p_idempotency_key;
  if found then
    if v.payload_hash is distinct from v_hash then raise exception 'idempotency conflict' using errcode='23505'; end if;
    return v;
  end if;
  if not exists(select 1 from public.care_recipient_products where care_recipient_id=p_care_recipient_id and product_id=p_product_id and is_active) then raise exception 'invalid patient catalogue product'; end if;
  insert into public.stock_movements(product_id,quantity,movement_type,performed_by,justification,care_recipient_id,source_location,destination_location,idempotency_key,reference_type,reference_id,payload_hash)
  values(p_product_id,p_quantity,p_movement_type,auth.uid(),trim(p_justification),p_care_recipient_id,p_source_location,p_destination_location,p_idempotency_key,p_reference_type,p_reference_id,v_hash) returning * into v;
  insert into public.audit_events(actor_id,action,entity_type,entity_id,metadata) values(auth.uid(),'stock.movement.created','stock_movement',v.id,jsonb_build_object('care_recipient_id',p_care_recipient_id,'product_id',p_product_id,'quantity',p_quantity,'source_before',v.source_balance_before,'source_after',v.source_balance_after,'destination_before',v.destination_balance_before,'destination_after',v.destination_balance_after));
  return v;
end; $function$

CREATE OR REPLACE FUNCTION public.recount_stock_inventory(p_inventory_id uuid)
 RETURNS stock_inventories
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare i public.stock_inventories;v public.stock_inventories;
begin
  select * into i from public.stock_inventories where id=p_inventory_id for update;
  if not found or not public.recipient_can(i.care_recipient_id,'count') or i.status in ('approved','cancelled') then raise exception 'inventory cannot be recounted' using errcode='42501'; end if;
  update public.stock_inventories set status='cancelled',review_reason='substituído por nova contagem' where id=i.id;
  v:=public.create_stock_inventory(i.care_recipient_id,i.location);
  insert into public.audit_events(actor_id,action,entity_type,entity_id,metadata) values(auth.uid(),'inventory.recounted','stock_inventory',v.id,jsonb_build_object('care_recipient_id',i.care_recipient_id,'previous_inventory_id',i.id));
  return v;
end; $function$

CREATE OR REPLACE FUNCTION public.register_document_pdf(p_document uuid, p_version integer, p_path text, p_hash text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare r public.document_pdfs;begin
 if coalesce(auth.role(),'')<>'service_role' then raise exception 'server required' using errcode='42501';end if;
 if p_hash is null or p_hash!~'^[a-f0-9]{64}$' or not exists(select 1 from public.document_events where document_id=p_document and version=p_version) or p_path<>p_document||'/'||p_version||'.pdf' then raise exception 'invalid PDF version';end if;
 insert into public.document_pdfs(document_id,version,object_path,sha256) values(p_document,p_version,p_path,p_hash) on conflict(document_id,version) do nothing;
 select * into strict r from public.document_pdfs where document_id=p_document and version=p_version;
 if r.sha256<>p_hash then raise exception 'PDF immutable';end if;return to_jsonb(r);
end;$function$

CREATE OR REPLACE FUNCTION public.register_document_render(p_document uuid, p_version integer, p_renderer integer, p_path text, p_hash text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare r public.document_pdf_renders;begin
 if coalesce(auth.jwt()->>'role','')<>'service_role' then raise exception 'PDF worker required' using errcode='42501';end if;
 if p_path<>p_document::text||'/'||p_version||'/render-'||p_renderer||'.pdf' or not exists(select 1 from public.document_events where document_id=p_document and version=p_version)
 or not exists(select 1 from storage.objects where bucket_id='document-receipts' and name=p_path) then raise exception 'invalid PDF evidence';end if;
 insert into public.document_pdf_renders(document_id,version,renderer,object_path,sha256) values(p_document,p_version,p_renderer,p_path,p_hash) on conflict do nothing;
 select * into strict r from public.document_pdf_renders where document_id=p_document and version=p_version and renderer=p_renderer;
 if r.object_path<>p_path or r.sha256<>p_hash then raise exception 'immutable PDF artifact conflict';end if;
 return to_jsonb(r);
end;$function$

CREATE OR REPLACE FUNCTION public.register_verified_phone()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare p text;begin
 if not public.recent_session() then raise exception 'recent authentication required' using errcode='42501';end if;
 select '+'||ltrim(phone,'+') into p from auth.users where id=auth.uid() and phone_confirmed_at is not null and length(phone)>7;
 if p is null then raise exception 'confirm phone with Auth OTP first';end if;
 insert into public.verified_phones(user_id,phone) values(auth.uid(),p) on conflict(user_id) do update set phone=excluded.phone,verified_at=now();
end;$function$

CREATE OR REPLACE FUNCTION public.report_extraordinary_consumption(p_patient uuid, p_kind text, p_location text, p_text text, p_lines jsonb, p_key uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$declare v public.consumption_reports;x jsonb;canonical jsonb:='[]';c public.care_recipient_products;q numeric;begin
 perform private.require_cap(p_patient,'consumption.report');
 if p_kind not in ('consumption','shortage') or p_location not in ('FAMILY','CARE_TEAM') or length(trim(p_text)) not between 3 and 2000 or jsonb_typeof(p_lines)<>'array' or jsonb_array_length(p_lines)>100 or p_key is null then raise exception 'invalid consumption report';end if;
 if p_location='FAMILY' and public.recipient_role(p_patient) not in ('admin','family') then raise exception 'family scope required' using errcode='42501';end if;
 if jsonb_typeof(p_lines) is distinct from 'array' then raise exception 'invalid report lines';end if;
 if (select count(distinct z->>'productId') from jsonb_array_elements(p_lines) z)<>jsonb_array_length(p_lines) then raise exception 'duplicate report product';end if;
 for x in select value from jsonb_array_elements(p_lines) loop
 select * into c from public.care_recipient_products where care_recipient_id=p_patient and product_id=x->>'productId' and is_active;
 q:=(x->>'quantity')::numeric;
 if not found or q is null or q<=0 or q>1000000000 or q<>round(q,c.quantity_decimals) or x ? 'unit' and x->>'unit'<>c.unit then raise exception 'invalid structured consumption';end if;
 canonical:=canonical||jsonb_build_array(jsonb_build_object('productId',c.product_id,'quantity',q::text,'unit',c.unit));
 end loop;
 p_lines:=canonical;
 perform pg_advisory_xact_lock(hashtextextended('report:'||auth.uid()||p_key,0));
 select * into v from public.consumption_reports where reported_by=auth.uid() and idempotency_key=p_key;
 if found then if v.care_recipient_id<>p_patient or v.kind<>p_kind or v.location<>p_location or v.body<>p_text or v.lines<>p_lines then raise exception 'idempotency conflict' using errcode='23505';end if;return v.id;end if;
 insert into public.consumption_reports(care_recipient_id,reported_by,kind,location,body,lines,idempotency_key) values(p_patient,auth.uid(),p_kind,p_location,p_text,p_lines,p_key) returning * into v;
 return v.id;
end;$function$

CREATE OR REPLACE FUNCTION public.requisition_fulfillment(p_requisition uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare p uuid;begin
 select care_recipient_id into p from public.requisitions where id=p_requisition;
 if not private.can(p,'req.read') then raise exception 'required permission' using errcode='42501';end if;
 return (select jsonb_build_object('total',count(*),'fulfilled',count(*) filter(where attended),'lines',coalesce(jsonb_agg(jsonb_build_object('id',i.id,'productId',private.effective_requisition_product(i.id),'attended',attended,'deliveries',deliveries)),'[]'))
 from (select i.*,exists(select 1 from public.document_request_links x join public.document_lines l on l.id=x.document_line_id join public.operational_documents d on d.id=l.document_id where x.requisition_item_id=i.id and d.type='ENT' and d.status<>'cancelled' and l.accepted_quantity>0) attended,
 coalesce((select jsonb_agg(jsonb_build_object('id',d.id,'code',d.code,'acceptedQuantity',l.accepted_quantity::text,'status',d.status)) from public.document_request_links x join public.document_lines l on l.id=x.document_line_id join public.operational_documents d on d.id=l.document_id where x.requisition_item_id=i.id and d.type='ENT'),'[]') deliveries
 from public.requisition_items i where i.requisition_id=p_requisition) i);
end;$function$

CREATE OR REPLACE FUNCTION public.requisition_fulfillments(p_ids uuid[])
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$begin
 if cardinality(p_ids)>100 then raise exception 'invalid batch';end if;
 if exists(select 1 from public.requisitions where id=any(p_ids) and not private.can(care_recipient_id,'req.read')) then raise exception 'required permission' using errcode='42501';end if;
 return coalesce((select jsonb_object_agg(id,public.requisition_fulfillment(id)) from public.requisitions where id=any(p_ids)),'{}');
end;$function$

CREATE OR REPLACE FUNCTION public.requisition_progress(p_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare s public.requisition_lifecycle;d public.operational_documents;begin
 select * into d from public.operational_documents where id=p_id;
 if not private.can(d.care_recipient_id,'req.read') then raise exception 'required permission' using errcode='42501';end if;
 select * into s from public.requisition_lifecycle where requisition_id=p_id;
 return jsonb_build_object('version',d.version,'preferences',(select notification_preferences from public.profiles where id=auth.uid()),'science',coalesce((select jsonb_agg(to_jsonb(e) order by e.created_at,e.id) from public.requisition_science_events e where requisition_id=p_id),'[]'),
 'scienceSatisfied',coalesce(private.science_satisfied(p_id),false),'eligible',auth.uid()=any(s.eligible_users),
 'policy',s.policy,'completedAt',s.completed_at,'manualArchiveRequired',s.manual_archive_required,'archivedAt',s.archived_at,'archiveReason',s.archive_reason,
 'events',coalesce((select jsonb_agg(jsonb_build_object('id',e.id,'action',e.action,'createdAt',e.created_at,'actorId',e.actor_id,'actorName',coalesce(e.actor_name,e.body->>'actorName',case when e.actor_id is null then 'Sistema' else 'Identidade do registro legado' end),'version',e.version) order by e.version)
 from public.document_events e left join public.profiles p on p.id=e.actor_id where e.document_id=p_id),'[]'));
end;$function$

CREATE OR REPLACE FUNCTION public.reserve_attachment(p_patient uuid, p_document uuid, p_movement uuid, p_filename text, p_mime text, p_bytes bigint, p_key uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$declare d public.operational_documents;v public.attachments;v_id uuid:=gen_random_uuid();begin
 if p_key is null then raise exception 'attachment key required';end if;
 if num_nonnulls(p_document,p_movement)<>1 or p_mime not in ('image/jpeg','image/png','image/webp','application/pdf') or p_bytes not between 1 and 10485760 or length(p_filename) not between 1 and 180 then raise exception 'invalid attachment';end if;
 if p_document is not null then
 select * into d from public.operational_documents where id=p_document and care_recipient_id=p_patient;
 if not found then raise exception 'document not found';end if;
 perform private.require_cap(p_patient,lower(d.type)||'.read');
 if not (d.created_by=auth.uid() or d.recipient_id=auth.uid() or public.can_manage_recipient(p_patient) or d.type='BAL' and private.can(p_patient,'bal.count')) then raise exception 'attachment write not authorized' using errcode='42501';end if;
 else
 perform private.require_cap(p_patient,'stock.family.manage');
 if not exists(select 1 from public.stock_movements where id=p_movement and care_recipient_id=p_patient and reference_type='family_manual') then raise exception 'invalid movement';end if;
 end if;
 perform pg_advisory_xact_lock(hashtextextended('attachments:'||coalesce(p_document,p_movement),0));
 select * into v from public.attachments where uploaded_by=auth.uid() and upload_key=p_key;
 if found then
 if v.care_recipient_id<>p_patient or v.document_id is distinct from p_document or v.movement_id is distinct from p_movement or v.filename<>p_filename or v.mime_type<>p_mime or v.bytes<>p_bytes then raise exception 'attachment idempotency conflict' using errcode='23505';end if;return to_jsonb(v);
 end if;
 if (select count(*) from public.attachments where coalesce(document_id,movement_id)=coalesce(p_document,p_movement) and state<>'rejected')>=10 then raise exception 'attachment limit reached';end if;
 insert into public.attachments(id,care_recipient_id,document_id,movement_id,uploaded_by,filename,mime_type,bytes,object_path,upload_key)
 values(v_id,p_patient,p_document,p_movement,auth.uid(),p_filename,p_mime,p_bytes,p_patient||'/'||auth.uid()||'/'||v_id||'/original',p_key) returning * into v;return to_jsonb(v);
end;$function$

CREATE OR REPLACE FUNCTION public.resolve_balance_assignment(p_patient uuid, p_cycle uuid, p_shift uuid, p_reason text, p_key uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_old private.bal_commands;v_request jsonb;v_id uuid;v_result jsonb;v_c public.bal_cycles;v_s public.scheduled_shifts;
 v_previous public.bal_assignments;v_due timestamptz;v_defer boolean;v_deferral public.bal_deferrals;
begin
 if not private.bal_family_authority(p_patient,'bal.schedule.manage') then raise exception 'family balance scheduling authorization required' using errcode='42501';end if;
 if p_key is null or length(trim(coalesce(p_reason,''))) not between 3 and 1000 then raise exception 'assignment reason required';end if;
 if not exists(select 1 from public.care_recipients where id=p_patient and is_active) then raise exception 'inactive patient';end if;
 perform pg_advisory_xact_lock(hashtextextended('bal:'||p_patient,0));
 v_request:=jsonb_build_object('action','assign','cycleId',p_cycle,'shiftId',p_shift,'reason',p_reason);
 select * into v_old from private.bal_commands where care_recipient_id=p_patient and actor_id=auth.uid() and key=p_key;
 if found then if v_old.request<>v_request then raise exception 'idempotency payload mismatch';end if;return v_old.result;end if;
 select * into v_c from public.bal_cycles where id=p_cycle and care_recipient_id=p_patient and state='open' for update;
 if not found or exists(select 1 from public.bal_assignments where care_recipient_id=p_patient and status='active') then raise exception 'stale balance assignment';end if;
 select * into v_s from public.scheduled_shifts where id=p_shift and care_recipient_id=p_patient for share;
 if not found or v_s.starts_at<(select min(original_start) from public.bal_obligations where cycle_id=p_cycle) then raise exception 'invalid balance target shift';end if;
 select min(effective_due) into v_due from public.bal_obligations where cycle_id=p_cycle and state='pending' and effective_due>now();
 v_defer:=coalesce(v_s.ends_at>v_due,false);
 if v_defer and not private.bal_family_authority(p_patient,'bal.defer.approve') then raise exception 'family deferral approval required' using errcode='42501';end if;
 v_id:=private.bal_assign(p_patient,p_cycle,p_shift,case when v_defer then 'deferred' else 'transfer' end);
 if v_defer then
 select * into v_previous from public.bal_assignments where cycle_id=p_cycle and id<>v_id order by created_at desc limit 1;
 insert into public.bal_deferrals(care_recipient_id,cycle_id,assignment_id,assignment_version,target_shift_id,target_shift_version,target_snapshot,reason,requested_by,status,decided_by,decision_reason,decided_at)
 values(p_patient,p_cycle,v_previous.id,v_previous.version,v_s.id,v_s.version,to_jsonb(v_s)||jsonb_build_object('professional_name',(select full_name from public.profiles where id=v_s.professional_id),'type_name',(select name from public.shift_types where id=v_s.shift_type_id)),p_reason,auth.uid(),'approved',auth.uid(),p_reason,now()) returning * into v_deferral;
 update public.bal_obligations set effective_due=greatest(effective_due,v_s.ends_at) where cycle_id=p_cycle and state='pending';
 perform private.bal_event(p_patient,p_cycle,v_id,'bal.cycle.deferred',p_reason,to_jsonb(v_deferral),'deferral:'||v_deferral.id||':approved');
 end if;
 perform private.bal_event(p_patient,p_cycle,v_id,'bal.cycle.assignment_resolved',p_reason,jsonb_build_object('shiftId',p_shift,'authorizedDeferral',v_defer),'resolve:'||v_id);
 v_result:=jsonb_build_object('assignmentId',v_id);
 insert into private.bal_commands(care_recipient_id,actor_id,key,request,result) values(p_patient,auth.uid(),p_key,v_request,v_result);
 return v_result;
end;$function$

CREATE OR REPLACE FUNCTION public.resolve_requisition_item(p_item uuid, p_product text, p_reason text, p_key uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare i public.requisition_items;r public.requisition_item_resolutions;begin
 select * into strict i from public.requisition_items where id=p_item for update;
 perform private.require_cap(i.care_recipient_id,'catalog.manage');
 perform private.require_cap(i.care_recipient_id,'req.review');
 if p_key is null or p_reason is null or length(trim(p_reason)) not between 3 and 1000
 or i.product_id is not null or i.custom_name is null then raise exception 'invalid custom item resolution';end if;
 select * into r from public.requisition_item_resolutions where resolved_by=auth.uid() and idempotency_key=p_key;
 if found then
 if r.requisition_item_id<>p_item or r.product_id<>p_product or r.reason<>trim(p_reason) then raise exception 'idempotency conflict' using errcode='23505';end if;
 return to_jsonb(r);end if;
 if exists(select 1 from public.requisition_item_resolutions where requisition_item_id=p_item)
 or not exists(select 1 from public.care_recipient_products where care_recipient_id=i.care_recipient_id and product_id=p_product and is_active)
 or not exists(select 1 from public.requisitions where id=i.requisition_id and status<>'cancelled') then raise exception 'invalid custom item product';end if;
 insert into public.requisition_item_resolutions(requisition_item_id,care_recipient_id,product_id,resolved_by,reason,idempotency_key)
 values(i.id,i.care_recipient_id,p_product,auth.uid(),trim(p_reason),p_key) returning * into r;
 update public.operational_documents set version=version+1 where id=i.requisition_id;
 perform private.record_document_event(i.requisition_id,'req.item_resolved',
 jsonb_build_object('itemId',i.id,'originalName',i.custom_name,'productId',p_product,'reason',trim(p_reason)),p_key);
 return to_jsonb(r);
end;$function$

CREATE OR REPLACE FUNCTION public.retry_notification_job(p_id uuid, p_confirm_uncertain boolean DEFAULT false)
 RETURNS requisition_notifications
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v public.requisition_notifications;v_previous text;
begin
  select * into v from public.requisition_notifications where id=p_id for update;
  if not found or not public.can_manage_recipient(v.care_recipient_id) then raise exception 'notification retry not authorized' using errcode='42501';end if;
  if v.state not in ('failed','uncertain') then raise exception 'notification is not retryable';end if;
  if v.state='uncertain' and not coalesce(p_confirm_uncertain,false) then raise exception 'uncertain notification requires explicit reconciliation confirmation';end if;
  v_previous:=v.state;
  update public.requisition_notifications set state='pending',attempts=0,next_attempt_at=now(),leased_by=null,lease_expires_at=null,last_error=null where id=v.id returning * into v;
  insert into public.audit_events(actor_id,action,entity_type,entity_id,metadata)
    values(auth.uid(),'notification.retry.requested','notification',v.id,jsonb_build_object('care_recipient_id',v.care_recipient_id,'previous_state',v_previous,'confirmed_uncertain',coalesce(p_confirm_uncertain,false)));
  return v;
end; $function$

CREATE OR REPLACE FUNCTION public.review_flow_submission(p_id uuid, p_accept boolean, p_kind text, p_text text, p_lines jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare s public.flow_submissions;v uuid;begin
 select * into strict s from public.flow_submissions where id=p_id for update;
 perform private.require_cap(s.care_recipient_id,'consumption.report');
 if s.user_id<>auth.uid() or p_accept is null then raise exception 'flow owner required' using errcode='42501';end if;
 if s.status<>'pending_confirmation' then return jsonb_build_object('status',s.status,'reportId',s.report_id);end if;
 if p_accept then
 v:=public.report_extraordinary_consumption(s.care_recipient_id,p_kind,'CARE_TEAM',p_text,p_lines,s.id);
 update public.flow_submissions set status='confirmed',report_id=v,reviewed_at=now() where id=s.id;
 else update public.flow_submissions set status='rejected',reviewed_at=now() where id=s.id;end if;
 insert into public.audit_events(actor_id,action,entity_type,entity_id,metadata)
 values(auth.uid(),case when p_accept then 'flow.confirmed' else 'flow.rejected' end,'flow_submission',s.id,
 jsonb_build_object('care_recipient_id',s.care_recipient_id,'report_id',v));
 return jsonb_build_object('status',case when p_accept then 'confirmed' else 'rejected' end,'reportId',v);
end;$function$

CREATE OR REPLACE FUNCTION public.review_stock_inventory(p_inventory_id uuid, p_action text, p_reason text DEFAULT NULL::text)
 RETURNS stock_inventories
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare i public.stock_inventories;
begin
  select * into i from public.stock_inventories where id=p_inventory_id for update;
  if not found or not public.recipient_can(i.care_recipient_id,'review') then raise exception 'inventory review authorization required' using errcode='42501'; end if;
  if p_action is null or p_action not in ('under_review','rejected','cancelled') or p_reason is null or length(trim(p_reason)) not between 1 and 1000 then raise exception 'invalid inventory review'; end if;
  if i.status in ('approved','rejected','cancelled') or p_action='under_review' and i.status<>'submitted' or p_action='rejected' and i.status not in ('submitted','under_review') then raise exception 'invalid inventory transition'; end if;
  update public.stock_inventories set status=p_action,review_reason=trim(p_reason) where id=i.id returning * into i;
  insert into public.audit_events(actor_id,action,entity_type,entity_id,metadata) values(auth.uid(),'inventory.'||p_action,'stock_inventory',i.id,jsonb_build_object('care_recipient_id',i.care_recipient_id,'reason',trim(p_reason)));
  return i;
end; $function$

CREATE OR REPLACE FUNCTION public.revise_supply_document(p_id uuid, p_payload jsonb, p_key uuid, p_version integer, p_recount boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$declare v_d public.operational_documents;v_context jsonb;v_result jsonb;v_event public.document_events;begin
 select * into v_d from public.operational_documents where id=p_id;
 if v_d.type='BAL' and (exists(select 1 from public.bal_cycles where document_id=p_id) or exists(select 1 from public.bal_regimes where care_recipient_id=v_d.care_recipient_id and activated_at is not null)) then
 perform private.require_cap(v_d.care_recipient_id,'bal.read');
 perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('stock:'||v_d.care_recipient_id::text,0));
 perform private.require_cap(v_d.care_recipient_id,'bal.read');
 select * into v_event from public.document_events where actor_id=auth.uid() and idempotency_key=p_key;
 if found then if v_event.document_id<>p_id or (v_event.body->'event')-'balanceContext'<>p_payload-'balanceContext' or v_event.action<>(case when p_recount then 'bal.recount' else 'bal.draft_updated' end) then raise exception 'idempotency payload mismatch';end if;return public.operational_document(p_id);end if;
 v_context:=private.bal_count_context(v_d.care_recipient_id,p_id,p_payload);
 if p_recount and v_context->>'kind'<>'recount' then raise exception 'formal recount assignment required';end if;
 p_payload:=(p_payload-'balanceContext')||jsonb_build_object('balanceContext',v_context);
 update public.operational_documents set workflow_data=workflow_data||jsonb_build_object('referenceRevision',private.team_revision(v_d.care_recipient_id)) where id=p_id;v_result:=public.fluent_pre_shift_revise(p_id,p_payload,p_key,p_version,p_recount);
 if p_recount then perform private.finish_bal_count(p_id,v_context);end if;return v_result;end if;
 return public.fluent_pre_shift_revise(p_id,p_payload-'balanceContext'-'balanceAssignment',p_key,p_version,p_recount);
end;$function$

CREATE OR REPLACE FUNCTION public.revoke_invitation(p_invitation_id uuid)
 RETURNS care_recipient_invitations
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v public.care_recipient_invitations;
begin
  select * into v from public.care_recipient_invitations where id=p_invitation_id for update;
  if not found or not public.can_manage_recipient(v.care_recipient_id) then raise exception 'invitation not authorized' using errcode='42501';end if;
  if v.status='accepted' then raise exception 'accepted invitation cannot be revoked; revoke the membership';end if;
  update public.care_recipient_invitations set status='revoked' where id=v.id returning * into v;
  insert into public.audit_events(actor_id,action,entity_type,entity_id,metadata) values(auth.uid(),'invitation.revoked','invitation',v.id,jsonb_build_object('care_recipient_id',v.care_recipient_id));return v;
end; $function$

CREATE OR REPLACE FUNCTION public.run_operational_schedule()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_result jsonb;
  v_cursor uuid;
  v_batch uuid[];
  v_patient uuid;
  v_assignments integer := 0;
  v_processed integer := 0;
begin
  if coalesce(auth.jwt()->>'role','') <> 'service_role' then
    raise exception 'worker authorization required' using errcode='42501';
  end if;
  v_result := public.fluent_pre_shift_scheduler();
  -- The singleton row serializes overlapping workers. Cursor movement and all
  -- patient processing commit together; a failed transaction advances neither.
  select last_patient into strict v_cursor
    from private.bal_scheduler_progress where singleton for update;
  if v_cursor is null then
    v_batch := array(select care_recipient_id from public.bal_regimes
      where enabled order by care_recipient_id limit 100);
  else
    v_batch := array(select care_recipient_id from public.bal_regimes
      where enabled and care_recipient_id > v_cursor order by care_recipient_id limit 100);
    v_batch := v_batch || array(select care_recipient_id from public.bal_regimes
      where enabled and care_recipient_id <= v_cursor order by care_recipient_id
      limit (100 - cardinality(v_batch)));
  end if;
  foreach v_patient in array v_batch loop
    v_assignments := v_assignments + private.process_bal_patient(v_patient);
    v_processed := v_processed + 1;
  end loop;
  if v_processed > 0 then
    update private.bal_scheduler_progress
      set last_patient=v_patient, updated_at=clock_timestamp() where singleton;
  end if;
  return v_result || jsonb_build_object('balanceAssignments',v_assignments,'balancePatientsProcessed',v_processed);
end;
$function$

CREATE OR REPLACE FUNCTION public.schedule_command(p_patient uuid, p_action text, p_body jsonb, p_key uuid, p_version integer DEFAULT NULL::integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
<<schedule_decision>>
declare old private.schedule_commands;req jsonb;result jsonb;typ public.shift_types;ser public.shift_series;s public.scheduled_shifts;proposal public.shift_change_requests;
 worker uuid;sid uuid;before_row jsonb;day date;begin_at timestamptz;end_at timestamptz;can_publish boolean;event_name text;reason text:=trim(coalesce(p_body->>'reason',''));cutoff date;
begin
 if auth.uid() is null or not public.can_access_recipient(p_patient) or not exists(select 1 from public.care_recipients where id=p_patient and is_active) then raise exception 'schedule authorization required' using errcode='42501';end if;
 if p_key is null or p_body is null or jsonb_typeof(p_body)<>'object' then raise exception 'invalid schedule command';end if;
 perform pg_advisory_xact_lock(hashtextextended('schedule:'||p_patient,0));
 req:=jsonb_build_object('action',p_action,'body',p_body,'version',p_version);
 select * into old from private.schedule_commands where care_recipient_id=p_patient and actor_id=auth.uid() and key=p_key;
 if found then
 if not(private.can(p_patient,'schedule.manage.team') or private.can(p_patient,'schedule.manage.own') or private.can(p_patient,'schedule.propose') or private.can(p_patient,'schedule.types.manage')) then raise exception 'schedule authorization required' using errcode='42501';end if;
 if old.request<>req then raise exception 'idempotency payload mismatch';end if;return old.result;end if;
 if p_action='type' then
 perform private.require_cap(p_patient,'schedule.types.manage');
 if p_body->>'id' is not null then
 select * into typ from public.shift_types where id=(p_body->>'id')::uuid and care_recipient_id=p_patient for update;
 if not found then raise exception 'shift type not found';end if;
 if typ.version is distinct from p_version then raise exception 'stale document';end if;before_row:=to_jsonb(typ);
 -- Existing occurrences retain their real intervals; changing a type affects new series only.
 update public.shift_types set name=trim(p_body->>'name'),starts_local=(p_body->>'startsLocal')::time,duration_minutes=(p_body->>'durationMinutes')::integer,
 is_active=coalesce((p_body->>'active')::boolean,true),version=version+1 where id=typ.id returning * into typ;
 else
 insert into public.shift_types(care_recipient_id,name,starts_local,duration_minutes,created_by)
 values(p_patient,trim(p_body->>'name'),(p_body->>'startsLocal')::time,(p_body->>'durationMinutes')::integer,auth.uid()) returning * into typ;
 end if;
 result:=to_jsonb(typ);perform private.schedule_event(p_patient,null,null,null,'schedule.type',reason,before_row,result);
 elsif p_action='series' then
 worker:=(p_body->>'professionalId')::uuid;
 can_publish:=private.can(p_patient,'schedule.manage.team') or worker=auth.uid() and private.can(p_patient,'schedule.manage.own');
 if not can_publish and not(worker=auth.uid() and private.can(p_patient,'schedule.propose')) then raise exception 'schedule authorization required' using errcode='42501';end if;
 if not private.schedule_worker(p_patient,worker) then raise exception 'invalid scheduled professional';end if;
 select * into typ from public.shift_types where id=(p_body->>'shiftTypeId')::uuid and care_recipient_id=p_patient and is_active;
 if not found then raise exception 'shift type not found';end if;
 if not exists(select 1 from pg_catalog.pg_timezone_names where name=coalesce(p_body->>'timezone','America/Sao_Paulo')) then raise exception 'invalid timezone';end if;
 if (p_body->>'anchorDate')::date<(now() at time zone coalesce(p_body->>'timezone','America/Sao_Paulo'))::date and length(reason)<3 then raise exception 'retroactive reason required';end if;
 if p_body->>'recurrence'='cycle' and typ.duration_minutes<>(p_body->>'workHours')::integer*60 then raise exception 'cycle duration differs from shift type';end if;
 if p_body->>'replacesId' is not null then
 select * into ser from public.shift_series where id=(p_body->>'replacesId')::uuid and care_recipient_id=p_patient for update;
 if not found or ser.ended_on is null or not can_publish then raise exception 'end the previous series before replacing it';end if;
 end if;
 insert into public.shift_series(care_recipient_id,professional_id,shift_type_id,timezone,recurrence,weekdays,work_hours,rest_hours,anchor_date,valid_until,status,notes,created_by,replaces_id)
 values(p_patient,worker,typ.id,coalesce(p_body->>'timezone','America/Sao_Paulo'),p_body->>'recurrence',
 array(select jsonb_array_elements_text(coalesce(p_body->'weekdays','[]'))::integer),(p_body->>'workHours')::integer,(p_body->>'restHours')::integer,
 (p_body->>'anchorDate')::date,case when p_body->>'recurrence'='once' then (p_body->>'anchorDate')::date else (p_body->>'validUntil')::date end,
 case when can_publish then 'published' else 'proposed' end,coalesce(p_body->>'notes',''),auth.uid(),(p_body->>'replacesId')::uuid) returning * into ser;
 perform pg_advisory_xact_lock(hashtextextended('schedule-worker:'||worker,0));
 begin_at:=(ser.anchor_date+typ.starts_local) at time zone ser.timezone;
 for day in select generate_series(ser.anchor_date::timestamp,ser.valid_until::timestamp,interval '1 day')::date loop
 if ser.recurrence='weekly' and not(extract(dow from day)::integer=any(ser.weekdays)) then continue;end if;
 if ser.recurrence<>'cycle' then begin_at:=(day+typ.starts_local) at time zone ser.timezone;
 elsif day<>ser.anchor_date then continue;end if;
 loop
 end_at:=begin_at+make_interval(mins=>typ.duration_minutes);
 insert into public.scheduled_shifts(care_recipient_id,series_id,professional_id,shift_type_id,starts_at,ends_at,timezone,original_starts_at,status,notes)
 values(p_patient,ser.id,worker,typ.id,begin_at,end_at,ser.timezone,begin_at,ser.status,ser.notes);
 exit when ser.recurrence<>'cycle';
 begin_at:=begin_at+make_interval(hours=>ser.work_hours+ser.rest_hours);
 exit when (begin_at at time zone ser.timezone)::date>ser.valid_until;
 end loop;end loop;
 result:=to_jsonb(ser);perform private.schedule_event(p_patient,ser.id,null,worker,'schedule.'||ser.status,reason,null,result);
 elsif p_action in ('approve','reject','end_series') then
 select * into ser from public.shift_series where care_recipient_id=p_patient and id=(p_body->>'id')::uuid for update;
 if not found then raise exception 'series not found';end if;
 if not(private.can(p_patient,'schedule.manage.team') or ser.professional_id=auth.uid() and private.can(p_patient,'schedule.manage.own')) then raise exception 'schedule authorization required' using errcode='42501';end if;
 if ser.version is distinct from p_version then raise exception 'stale document';end if;
 before_row:=to_jsonb(ser);worker:=ser.professional_id;
 perform pg_advisory_xact_lock(hashtextextended('schedule-worker:'||worker,0));
 if p_action='end_series' then
 cutoff:=(p_body->>'fromDate')::date;
 if cutoff is null or length(reason)<3 then raise exception 'reason and effective date required';end if;
 update public.shift_series set ended_on=cutoff,version=version+1 where id=ser.id returning * into ser;
 update public.scheduled_shifts set status='cancelled',version=version+1 where series_id=ser.id and (starts_at at time zone timezone)::date>=cutoff and status in ('published','proposed');
 else
 if ser.status<>'proposed' then raise exception 'invalid proposal state';end if;
 if p_action='reject' and length(reason)<3 then raise exception 'rejection reason required';end if;
 update public.shift_series set status=case when p_action='approve' then 'published' else 'rejected' end,version=version+1 where id=ser.id returning * into ser;
 update public.scheduled_shifts set status=ser.status,version=version+1 where series_id=ser.id;
 end if;
 result:=to_jsonb(ser);perform private.schedule_event(p_patient,ser.id,null,worker,'schedule.'||p_action,reason,before_row,result);
 elsif p_action='propose_change' then
 perform private.require_cap(p_patient,'schedule.propose');
 select * into s from public.scheduled_shifts where care_recipient_id=p_patient and id=(p_body->>'id')::uuid for update;
 if not found then raise exception 'shift not found';end if;
 if s.professional_id<>auth.uid() and not private.can(p_patient,'schedule.read.team') then raise exception 'schedule authorization required' using errcode='42501';end if;
 if s.version is distinct from p_version then raise exception 'stale document';end if;
 worker:=coalesce((p_body->>'professionalId')::uuid,s.professional_id);
 if s.status<>'published' or not private.schedule_worker(p_patient,worker) then raise exception 'invalid proposed shift';end if;
 insert into public.shift_change_requests(care_recipient_id,shift_id,professional_id,proposed_professional_id,starts_at,ends_at,reason,shift_version)
 values(p_patient,s.id,s.professional_id,worker,coalesce((p_body->>'startsAt')::timestamptz,s.starts_at),coalesce((p_body->>'endsAt')::timestamptz,s.ends_at),reason,s.version) returning * into proposal;
 result:=to_jsonb(proposal);perform private.schedule_event(p_patient,s.series_id,s.id,s.professional_id,'schedule.change_requested',reason,to_jsonb(s),result);
 elsif p_action='decide_change' then
 perform private.require_cap(p_patient,'schedule.manage.team');
 select * into proposal from public.shift_change_requests where id=(p_body->>'id')::uuid and care_recipient_id=p_patient for update;
 if not found then raise exception 'proposal not found';end if;
 if proposal.status<>'pending' then raise exception 'stale document';end if;
 if (p_body->>'approve')::boolean then
 result:=public.schedule_command(p_patient,'change',jsonb_build_object('id',proposal.shift_id,'professionalId',proposal.proposed_professional_id,'startsAt',proposal.starts_at,'endsAt',proposal.ends_at,'reason',proposal.reason),gen_random_uuid(),proposal.shift_version);
 elsif length(reason)<3 then raise exception 'rejection reason required';end if;
 update public.shift_change_requests set status=case when (p_body->>'approve')::boolean then 'approved' else 'rejected' end,decided_by=auth.uid(),decision_reason=schedule_decision.reason where id=proposal.id returning * into proposal;
 result:=to_jsonb(proposal);perform private.schedule_event(p_patient,null,proposal.shift_id,proposal.professional_id,'schedule.change_decided',reason,null,result);
 elsif p_action in ('change','cancel') then
 select * into s from public.scheduled_shifts where care_recipient_id=p_patient and id=(p_body->>'id')::uuid for update;
 if not found then raise exception 'shift not found';end if;
 if not(private.can(p_patient,'schedule.manage.team') or s.professional_id=auth.uid() and private.can(p_patient,'schedule.manage.own')) then raise exception 'schedule authorization required' using errcode='42501';end if;
 if s.version is distinct from p_version then raise exception 'stale document';end if;
 if s.status<>'published' or length(reason)<3 then raise exception 'published shift and reason required';end if;
 before_row:=to_jsonb(s);worker:=coalesce((p_body->>'professionalId')::uuid,s.professional_id);
 -- Lock both identities in a deterministic order for concurrent substitutions.
 for sid in select distinct x from unnest(array[worker,s.professional_id]) x order by x loop
 perform pg_advisory_xact_lock(hashtextextended('schedule-worker:'||sid,0));end loop;
 if not private.schedule_worker(p_patient,worker) then raise exception 'invalid scheduled professional';end if;
 if worker<>s.professional_id and not private.can(p_patient,'schedule.manage.team') then raise exception 'schedule authorization required' using errcode='42501';end if;
 update public.scheduled_shifts set professional_id=worker,starts_at=coalesce((p_body->>'startsAt')::timestamptz,starts_at),
 ends_at=coalesce((p_body->>'endsAt')::timestamptz,ends_at),status=case when p_action='cancel' then 'cancelled' else status end,
 is_exception=true,notes=coalesce(p_body->>'notes',notes),version=version+1 where id=s.id returning * into s;
 result:=to_jsonb(s);perform private.schedule_event(p_patient,s.series_id,s.id,worker,'schedule.'||p_action,reason,before_row,result);
 else raise exception 'invalid schedule action';end if;
 insert into private.schedule_commands(care_recipient_id,actor_id,key,request,result) values(p_patient,auth.uid(),p_key,req,result);
