end;$function$

CREATE OR REPLACE FUNCTION public.submit_requisition(p_care_recipient_id uuid, p_idempotency_key uuid, p_payload_hash text, p_lines jsonb, p_extra_items jsonb, p_observations jsonb)
 RETURNS TABLE(requisition_id uuid, protocol text, created_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare r public.requisitions;d public.operational_documents;intent jsonb;x jsonb;p public.care_recipient_products;q numeric;reason text;
begin
 perform private.require_cap(p_care_recipient_id,'req.create');
 if p_idempotency_key is null or jsonb_typeof(p_lines) is distinct from 'array' or jsonb_typeof(p_extra_items) is distinct from 'array' or jsonb_typeof(p_observations) is distinct from 'array'
 or jsonb_array_length(p_lines)>1000 or jsonb_array_length(p_extra_items)>20 or jsonb_array_length(p_observations)>50 or jsonb_array_length(p_lines)+jsonb_array_length(p_extra_items)=0 then raise exception 'invalid requisition payload';end if;
 if exists(select 1 from jsonb_array_elements(p_lines) z group by z->>'productId' having count(*)>1) then raise exception 'duplicate product';end if;
 if exists(select 1 from jsonb_array_elements(p_observations) z where jsonb_typeof(z) is distinct from 'string' or length(trim(z#>>'{}')) not between 1 and 1000) then raise exception 'invalid observation';end if;
 intent:=jsonb_build_object('careRecipientId',p_care_recipient_id,
 'lines',coalesce((select jsonb_agg(jsonb_build_object('productId',z->>'productId','currentStock',(z->>'currentStock')::numeric,'urgent',(z->>'urgent')::boolean,'repeatReason',nullif(trim(z->>'repeatReason'),'')) order by z->>'productId') from jsonb_array_elements(p_lines) z),'[]'),
 'extraItems',coalesce((select jsonb_agg(jsonb_build_object('customName',trim(z->>'customName'),'currentStock',(z->>'currentStock')::numeric,'urgent',(z->>'urgent')::boolean) order by trim(z->>'customName'),(z->>'currentStock')::numeric,(z->>'urgent')::boolean) from jsonb_array_elements(p_extra_items) z),'[]'),
 'observations',coalesce((select jsonb_agg(trim(value) order by trim(value)) from jsonb_array_elements_text(p_observations)),'[]'));
 perform pg_advisory_xact_lock(hashtextextended('requisition-patient:'||p_care_recipient_id,0));
 select * into r from public.requisitions where created_by=auth.uid() and idempotency_key=p_idempotency_key;
 if found then
 if r.care_recipient_id<>p_care_recipient_id or r.request_intent<>intent then raise exception 'idempotency conflict' using errcode='23505';end if;
 return query select r.id,r.protocol,r.created_at;return;end if;
 for x in select value from jsonb_array_elements(p_lines) loop
 select * into p from public.care_recipient_products where care_recipient_id=p_care_recipient_id and product_id=x->>'productId' and is_active;
 q:=(x->>'currentStock')::numeric;reason:=nullif(trim(x->>'repeatReason'),'');
 if not found or q is null or q<0 or q>100000 or q<>round(q,p.quantity_decimals) or jsonb_typeof(x->'urgent') is distinct from 'boolean' or length(coalesce(reason,''))>1000 then raise exception 'invalid requisition line';end if;
 if exists(select 1 from public.requisition_items i join public.requisitions oldr on oldr.id=i.requisition_id where i.care_recipient_id=p_care_recipient_id and private.effective_requisition_product(i.id)=p.product_id and oldr.status<>'cancelled'
 and not exists(select 1 from public.document_request_links k join public.document_lines l on l.id=k.document_line_id join public.operational_documents od on od.id=l.document_id where k.requisition_item_id=i.id and od.type='ENT' and od.status<>'cancelled' and l.accepted_quantity>0))
 and length(coalesce(reason,''))<3 then raise exception 'duplicate review required' using errcode='P0001';end if;
 end loop;
 for x in select value from jsonb_array_elements(p_extra_items) loop
 q:=(x->>'currentStock')::numeric;
 if q is null or q<0 or q>100000 or length(trim(coalesce(x->>'customName',''))) not between 1 and 200 or jsonb_typeof(x->'urgent') is distinct from 'boolean' then raise exception 'invalid extra';end if;
 if exists(select 1 from public.care_recipient_products c cross join lateral unnest(array_append(c.aliases,c.name)) a where c.care_recipient_id=p_care_recipient_id and c.is_active and public.unaccent(lower(trim(a)))=public.unaccent(lower(trim(x->>'customName')))) then raise exception 'custom item matches patient catalogue';end if;
 end loop;
 insert into public.operational_documents(care_recipient_id,type,created_by,status,idempotency_key,payload)
 values(p_care_recipient_id,'REQ',auth.uid(),'submitted',p_idempotency_key,jsonb_build_object('intent',intent,'requesterName',(select full_name from public.profiles where id=auth.uid()),'patientName',(select display_name from public.care_recipients where id=p_care_recipient_id))) returning * into d;
 perform private.emit_document(d.id);select * into d from public.operational_documents where id=d.id;
 insert into public.requisitions(id,protocol,code,created_by,care_recipient_id,status,idempotency_key,payload_hash,request_intent,requester_name_snapshot,recipient_name_snapshot)
 values(d.id,d.protocol,d.code,auth.uid(),p_care_recipient_id,'submitted',p_idempotency_key,encode(extensions.digest(intent::text,'sha256'),'hex'),intent,
 (select full_name from public.profiles where id=auth.uid()),(select display_name from public.care_recipients where id=p_care_recipient_id)) returning * into r;
 insert into public.requisition_items(requisition_id,product_id,current_stock,urgent,product_name_snapshot,category_snapshot,unit_snapshot,snapshot_source)
 select r.id,c.product_id,(z->>'currentStock')::numeric,(z->>'urgent')::boolean,c.name,c.category::text,c.unit,'persisted' from jsonb_array_elements(p_lines) z join public.care_recipient_products c on c.care_recipient_id=p_care_recipient_id and c.product_id=z->>'productId';
 insert into public.requisition_items(requisition_id,custom_name,current_stock,urgent,product_name_snapshot,snapshot_source)
 select r.id,trim(z->>'customName'),(z->>'currentStock')::numeric,(z->>'urgent')::boolean,trim(z->>'customName'),'persisted' from jsonb_array_elements(p_extra_items) z;
 insert into public.requisition_observations(requisition_id,created_by,body) select r.id,auth.uid(),trim(value) from jsonb_array_elements_text(p_observations);
 perform private.record_document_event(d.id,'req.issued',intent,p_idempotency_key);
 return query select r.id,r.protocol,r.created_at;
end;$function$

CREATE OR REPLACE FUNCTION public.submit_stock_inventory(p_inventory_id uuid)
 RETURNS stock_inventories
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare i public.stock_inventories;
begin
  select * into i from public.stock_inventories where id=p_inventory_id for update;
  if not found or i.status<>'draft' or not public.recipient_can(i.care_recipient_id,'count') then raise exception 'inventory cannot be submitted' using errcode='42501'; end if;
  if not exists(select 1 from public.stock_inventory_items where inventory_id=i.id)
    or exists(select 1 from public.stock_inventory_items where inventory_id=i.id and (not is_counted or expected_quantity is null or counted_quantity<>expected_quantity and justification is null)) then raise exception 'complete all counts and justify divergences'; end if;
  update public.stock_inventories set status='submitted',counted_at=now() where id=i.id returning * into i;
  return i;
end; $function$

CREATE OR REPLACE FUNCTION public.supply_document_command(p_id uuid, p_action text, p_body jsonb, p_key uuid, p_version integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$declare v_d public.operational_documents;v_context jsonb;v_result jsonb;v_event public.document_events;begin
 select * into v_d from public.operational_documents where id=p_id;
 if v_d.type='BAL' and p_action='approve' and v_d.payload->'balanceContext'->>'professionalId'=auth.uid()::text then raise exception 'distinct balance reviewer required' using errcode='42501';end if;
 if v_d.type='BAL' and p_action='approve' and p_body->>'group'='family' and not private.bal_family_authority(v_d.care_recipient_id,'bal.approve.family') then raise exception 'family approval required' using errcode='42501';end if;
 if v_d.type='BAL' and p_action='cancel' and exists(select 1 from public.bal_cycles where document_id=p_id and state='counted') then raise exception 'scheduled balance requires formal recount';end if;
 if v_d.type='BAL' and p_action='submit' and (exists(select 1 from public.bal_cycles where document_id=p_id) or exists(select 1 from public.bal_regimes where care_recipient_id=v_d.care_recipient_id and activated_at is not null)) then
 perform private.require_cap(v_d.care_recipient_id,'bal.read');
 perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('stock:'||v_d.care_recipient_id::text,0));
 perform private.require_cap(v_d.care_recipient_id,'bal.read');
 select * into v_event from public.document_events where actor_id=auth.uid() and idempotency_key=p_key;
 if found then if v_event.document_id<>p_id or v_event.action<>'bal.submit' or v_event.body->'event'<>p_body then raise exception 'idempotency payload mismatch';end if;return public.operational_document(p_id);end if;
 v_context:=private.bal_count_context(v_d.care_recipient_id,p_id,v_d.payload);
 update public.operational_documents set payload=(payload-'balanceContext')||jsonb_build_object('balanceContext',v_context) where id=p_id;
 v_result:=public.fluent_pre_shift_command(p_id,p_action,p_body,p_key,p_version);
 perform private.finish_bal_count(p_id,v_context);return v_result;end if;
 return public.fluent_pre_shift_command(p_id,p_action,p_body,p_key,p_version);
end;$function$

CREATE OR REPLACE FUNCTION public.transition_requisition_status(p_requisition_id uuid, p_to_status requisition_status, p_reason text DEFAULT NULL::text)
 RETURNS requisitions
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$declare patient_id uuid;begin
 if p_to_status<>'cancelled' then raise exception 'requisition progress is derived from confirmed events';end if;
 select care_recipient_id into patient_id from public.requisitions where id=p_requisition_id;
 perform private.require_cap(patient_id,'req.review');
 perform pg_advisory_xact_lock(hashtextextended('stock:'||patient_id,0));
 if exists(select 1 from public.requisition_lifecycle where requisition_id=p_requisition_id and (completed_at is not null or archived_at is not null)) then raise exception 'completed requisition requires compensating operations';end if;
 if exists(select 1 from public.document_request_links k join public.requisition_items i on i.id=k.requisition_item_id join public.document_lines l on l.id=k.document_line_id join public.operational_documents d on d.id=l.document_id where i.requisition_id=p_requisition_id and d.status<>'cancelled' and d.type='ENT') then raise exception 'resolve linked deliveries before cancellation';end if;
 return public.v3_transition_requisition_status(p_requisition_id,p_to_status,p_reason);
end;$function$

CREATE OR REPLACE FUNCTION public.update_my_profile(p_name text, p_registration text, p_state text, p_category text, p_preferences jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$begin
 if auth.uid() is null or length(trim(p_name)) not between 2 and 160 or length(coalesce(p_registration,''))>30 or p_state is not null and p_state!~'^[A-Z]{2}$' or length(coalesce(p_category,''))>80 or jsonb_typeof(p_preferences)<>'object' then raise exception 'invalid profile';end if;
 update public.profiles set full_name=trim(p_name),professional_registration=nullif(trim(p_registration),''),professional_state=p_state,professional_category=p_category,notification_preferences=p_preferences where id=auth.uid() and status='active';
 if not found then raise exception 'profile unavailable' using errcode='42501';end if;
end;$function$

CREATE OR REPLACE FUNCTION public.v3_accept_invitation(p_token_hash text)
 RETURNS care_recipient_memberships
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare i public.care_recipient_invitations;v public.care_recipient_memberships;v_email text;v_name text;
begin
  if auth.uid() is null then raise exception 'authentication required' using errcode='42501';end if;
  select lower(email),coalesce(nullif(raw_user_meta_data->>'full_name',''),split_part(email,'@',1)) into v_email,v_name from auth.users where id=auth.uid() and email_confirmed_at is not null;
  select * into i from public.care_recipient_invitations where token_hash=p_token_hash for update;
  if not found or v_email is null or i.email<>v_email or not exists(select 1 from public.care_recipients where id=i.care_recipient_id and is_active) then raise exception 'invalid or expired invitation' using errcode='42501';end if;
  if exists(select 1 from public.profiles where id=auth.uid() and status='revoked') then raise exception 'account revoked' using errcode='42501';end if;
  if i.status='accepted' and i.accepted_by=auth.uid() then
    select * into v from public.care_recipient_memberships where care_recipient_id=i.care_recipient_id and user_id=auth.uid() and status='active';
    if found then return v;end if;
    raise exception 'membership revoked' using errcode='42501';
  end if;
  if i.status<>'pending' or i.expires_at<=now() or not exists(
    select 1 from public.profiles p where p.id=i.invited_by and p.status='active' and
      (p.role='admin' and p.global_scope or exists(select 1 from public.care_recipient_memberships m where m.user_id=p.id and m.care_recipient_id=i.care_recipient_id and m.role='admin' and m.status='active')))
  then raise exception 'invalid or expired invitation' using errcode='42501';end if;
  -- Serialize acceptance with updates of an established membership. Revocation
  -- invalidates pending invitations; an explicit new invitation can restore access.
  perform 1 from public.care_recipient_memberships where care_recipient_id=i.care_recipient_id and user_id=auth.uid() for update;
  select status into v.status from public.care_recipient_invitations where id=i.id;
  if v.status<>'pending' then raise exception 'invitation revoked' using errcode='42501';end if;
  insert into public.profiles(id,full_name,role,status,global_scope) values(auth.uid(),left(case when length(v_name)<2 then 'Usuário' else v_name end,160),'professional','active',false) on conflict(id) do nothing;
  insert into public.care_recipient_memberships(care_recipient_id,user_id,role,can_manage_stock,can_count_stock)
  values(i.care_recipient_id,auth.uid(),i.role,i.role<>'reader' and i.can_manage_stock,i.role<>'reader' and i.can_count_stock)
  on conflict(care_recipient_id,user_id) do update set role=excluded.role,can_manage_stock=excluded.can_manage_stock,can_count_stock=excluded.can_count_stock,status='active' returning * into v;
  update public.care_recipient_invitations set status='accepted',accepted_by=auth.uid(),accepted_at=now() where id=i.id;
  insert into public.audit_events(actor_id,action,entity_type,entity_id,metadata) values(auth.uid(),'invitation.accepted','invitation',i.id,jsonb_build_object('care_recipient_id',i.care_recipient_id));return v;
end; $function$

CREATE OR REPLACE FUNCTION public.v3_admin_upsert_recipient(p_id uuid, p_display_name text, p_is_active boolean, p_is_development boolean)
 RETURNS care_recipients
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v public.care_recipients;
begin
  if not public.is_global_administrator() and not (p_id is not null and public.can_manage_recipient(p_id)) then
    raise exception 'admin authorization required' using errcode='42501'; end if;
  if p_display_name is null or length(trim(p_display_name)) not between 2 and 160 then raise exception 'invalid recipient'; end if;
  insert into public.care_recipients(id,display_name,is_active,is_development)
  values(coalesce(p_id,gen_random_uuid()),trim(p_display_name),p_is_active,p_is_development)
  on conflict(id) do update set display_name=excluded.display_name,is_active=excluded.is_active,is_development=excluded.is_development returning * into v;
  insert into public.audit_events(actor_id,action,entity_type,entity_id,metadata) values(auth.uid(),'recipient.updated','care_recipient',v.id,jsonb_build_object('care_recipient_id',v.id,'is_active',v.is_active));
  return v;
end; $function$

CREATE OR REPLACE FUNCTION public.v3_configure_stock_alert(p_care_recipient_id uuid, p_product_id text, p_location text, p_low_threshold bigint, p_critical_threshold bigint, p_is_enabled boolean)
 RETURNS stock_alert_rules
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v public.stock_alert_rules;
begin
  if not public.recipient_can(p_care_recipient_id,'admin') then raise exception 'alert admin authorization required' using errcode='42501';end if;
  perform pg_advisory_xact_lock(hashtextextended('stock:'||p_care_recipient_id,0));
  insert into public.stock_alert_rules(care_recipient_id,product_id,location,low_threshold,critical_threshold,is_enabled)
  values(p_care_recipient_id,p_product_id,p_location,p_low_threshold,p_critical_threshold,p_is_enabled)
  on conflict(care_recipient_id,product_id,location) do update set low_threshold=excluded.low_threshold,critical_threshold=excluded.critical_threshold,is_enabled=excluded.is_enabled returning * into v;
  perform public.evaluate_stock_alert(p_care_recipient_id,p_product_id,p_location);
  insert into public.audit_events(actor_id,action,entity_type,entity_id,metadata) values(auth.uid(),'stock.alert.configured','stock_alert_rule',v.id,jsonb_build_object('care_recipient_id',p_care_recipient_id,'enabled',p_is_enabled));return v;
end; $function$

CREATE OR REPLACE FUNCTION public.v3_create_supply_document(p_patient uuid, p_type text, p_payload jsonb, p_key uuid, p_draft boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare d public.operational_documents;x jsonb;p public.care_recipient_products;q numeric;l_id uuid;r_id uuid;s jsonb;v_cap text;v_recipient uuid;
begin
 if p_type not in ('COM','ENT','BAL') or p_key is null or jsonb_typeof(p_payload) is distinct from 'object' then raise exception 'invalid document';end if;
 v_cap:=case p_type when 'COM' then 'com.create' when 'ENT' then 'ent.create' else 'bal.count' end;
 perform private.require_cap(p_patient,v_cap);
 perform pg_advisory_xact_lock(hashtextextended('stock:'||p_patient,0));
 perform pg_advisory_xact_lock(hashtextextended('document:'||auth.uid()||':'||p_key,0));
 select * into d from public.operational_documents where created_by=auth.uid() and idempotency_key=p_key;
 if found then
 if d.care_recipient_id<>p_patient or d.type<>p_type or d.payload<>p_payload then raise exception 'idempotency conflict' using errcode='23505';end if;
 return public.operational_document(d.id);end if;
 if jsonb_typeof(p_payload->'lines') is distinct from 'array' or jsonb_array_length(p_payload->'lines') not between 1 and 1000 then raise exception 'invalid lines';end if;
 if p_type='ENT' then
 if coalesce(p_payload->>'source','') not in ('FAMILY','CARE_TEAM') or coalesce(p_payload->>'destination','') not in ('FAMILY','CARE_TEAM') or p_payload->>'source'=p_payload->>'destination' then raise exception 'invalid custody';end if;
 v_recipient:=(p_payload->>'recipientId')::uuid;
 if v_recipient is null or not private.user_can(p_patient,v_recipient,'ent.receive') or v_recipient=auth.uid() or not exists(select 1 from public.care_recipient_memberships m join public.profiles a on a.id=m.user_id where m.care_recipient_id=p_patient and m.user_id=v_recipient and m.status='active' and a.status='active'
 and (m.role::text in (case when p_payload->>'destination'='FAMILY' then 'family' else 'professional' end,'admin') or p_payload->>'destination'='CARE_TEAM' and m.role::text='supervisor')) then raise exception 'invalid designated recipient';end if;
 end if;
 insert into public.patient_settings(care_recipient_id) values(p_patient) on conflict do nothing;
 select settings into s from public.patient_settings where care_recipient_id=p_patient;
 insert into public.operational_documents(care_recipient_id,type,created_by,recipient_id,idempotency_key,payload,status,workflow_data)
 values(p_patient,p_type,auth.uid(),v_recipient,p_key,p_payload,'draft',case when p_type='BAL' then jsonb_build_object('referenceRevision',private.team_revision(p_patient),'countVersion',1,'reviewPolicy',s) else '{}' end) returning * into d;
 for x in select value from jsonb_array_elements(p_payload->'lines') loop
 select * into p from public.care_recipient_products where care_recipient_id=p_patient and product_id=x->>'productId' and is_active;
 if not found then raise exception 'invalid patient catalogue product';end if;
 q:=(x->>'quantity')::numeric;
 if q is null or q<0 or (p_type<>'BAL' and q=0) or q>1000000000 or q<>round(q,p.quantity_decimals) then raise exception 'invalid product quantity';end if;
 insert into public.document_lines(document_id,care_recipient_id,product_id,name_snapshot,unit_snapshot,category_snapshot,quantity,approved_quantity,metadata)
 values(d.id,p_patient,p.product_id,p.name,p.unit,p.category::text,q,case when p_type='COM' and public.recipient_role(p_patient)='admin' then q else 0 end,
 case when p_type='BAL' then jsonb_build_object('expectedQuantity',private.stock_quantity(p_patient,p.product_id,'CARE_TEAM')) else coalesce(x->'metadata','{}') end) returning id into l_id;
 for r_id in select value::text::uuid from jsonb_array_elements_text(coalesce(x->'requisitionItemIds','[]')) loop
 if not exists(select 1 from public.requisition_items i join public.requisitions r on r.id=i.requisition_id where i.id=r_id and i.care_recipient_id=p_patient and private.effective_requisition_product(i.id)=p.product_id and r.status<>'cancelled') then raise exception 'invalid requisition line link';end if;
 insert into public.document_request_links values(l_id,r_id);
 end loop;
 end loop;
 if p_type='BAL' and (select count(*) from public.document_lines where document_id=d.id)<>(select count(*) from public.care_recipient_products where care_recipient_id=p_patient and is_active) then raise exception 'count every active catalogue product';end if;
 if not p_draft then
 perform private.emit_document(d.id);
 update public.operational_documents set status=case p_type when 'COM' then case when public.recipient_role(p_patient)='admin' then 'approved' else 'pending_approval' end when 'ENT' then 'pending_receipt' else 'submitted' end where id=d.id;
 if p_type='ENT' then for x in select to_jsonb(l) from public.document_lines l where document_id=d.id order by product_id loop
 perform private.move_stock(p_patient,x->>'product_id',(x->>'quantity')::numeric,p_payload->>'source','TRANSIT','Expedição ENT','document',d.id);end loop;end if;
 if p_type='BAL' and s->>'balReview'='optional' then perform private.apply_bal(d.id);end if;
 end if;
 perform private.record_document_event(d.id,lower(p_type)||case when p_draft then '.draft' else '.issued' end,p_payload,p_key);
 return public.operational_document(d.id);
end;$function$

CREATE OR REPLACE FUNCTION public.v3_flow_exchange(p_hash text, p_submit jsonb DEFAULT NULL::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare s public.flow_sessions;v uuid;begin
 if coalesce(auth.role(),'')<>'service_role' then raise exception 'verified flow endpoint required' using errcode='42501';end if;
 select * into s from public.flow_sessions where token_hash=p_hash for update;
 if not found or s.expires_at<=now() or not private.user_can(s.care_recipient_id,s.user_id,'consumption.report') then raise exception 'flow session expired or revoked' using errcode='42501';end if;
 if p_submit is null then
 if s.used_at is not null then raise exception 'flow token used' using errcode='42501';end if;
 return jsonb_build_object('catalog',coalesce((select jsonb_agg(jsonb_build_object('id',product_id,'title',name,'unit',unit)) from public.care_recipient_products where care_recipient_id=s.care_recipient_id and is_active),'[]'));end if;
 if s.used_at is not null then
 if exists(select 1 from public.flow_submissions where session_id=s.id and body=p_submit) then return jsonb_build_object('pendingConfirmation',true);end if;
 raise exception 'flow replay conflict' using errcode='42501';end if;
 if jsonb_typeof(p_submit) is distinct from 'object' or length(p_submit::text)>10000 then raise exception 'invalid flow submission';end if;
 insert into public.flow_submissions(session_id,care_recipient_id,user_id,body) values(s.id,s.care_recipient_id,s.user_id,p_submit) returning id into v;
 update public.flow_sessions set used_at=now() where id=s.id;
 return jsonb_build_object('pendingConfirmation',true,'submissionId',v);
end;$function$

CREATE OR REPLACE FUNCTION public.v3_ingest_whatsapp_report(p_provider_id text, p_phone text, p_text text, p_lines jsonb, p_kind text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare c jsonb;claims text;sub text;v uuid;k uuid;begin
 if coalesce(auth.role(),'')<>'service_role' then raise exception 'webhook worker required' using errcode='42501';end if;
 perform pg_advisory_xact_lock(hashtextextended('inbound:'||p_provider_id,0));
 if exists(select 1 from public.inbound_messages where provider_id=p_provider_id) then return jsonb_build_object('duplicate',true);end if;
 c:=public.inbound_report_context(p_phone);if c is null then return jsonb_build_object('needsAuthenticatedSelection',true);end if;
 k:=gen_random_uuid();claims:=current_setting('request.jwt.claims',true);sub:=current_setting('request.jwt.claim.sub',true);
 perform set_config('request.jwt.claims',jsonb_build_object('sub',c->>'userId','role','authenticated')::text,true);perform set_config('request.jwt.claim.sub',c->>'userId',true);
 v:=public.report_extraordinary_consumption((c->>'patientId')::uuid,p_kind,'CARE_TEAM',p_text,p_lines,k);
 perform set_config('request.jwt.claims',coalesce(claims,''),true);perform set_config('request.jwt.claim.sub',coalesce(sub,''),true);
 insert into public.inbound_messages values(p_provider_id,encode(extensions.digest(p_phone,'sha256'),'hex'),'report','pending_confirmation',now());return jsonb_build_object('reportId',v,'pendingConfirmation',true);
end;$function$

CREATE OR REPLACE FUNCTION public.v3_revise_supply_document(p_id uuid, p_payload jsonb, p_key uuid, p_version integer, p_recount boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare d public.operational_documents;e public.document_events;x jsonb;p public.care_recipient_products;q numeric;l_id uuid;r_id uuid;p_patient uuid;p_type text;begin
 select * into strict d from public.operational_documents where id=p_id;
 p_patient:=d.care_recipient_id;p_type:=d.type;
 perform private.require_cap(p_patient,case d.type when 'BAL' then 'bal.count' else lower(d.type)||'.create' end);
 if d.created_by<>auth.uid() and not public.can_manage_recipient(p_patient) and not (d.type='BAL' and exists(select 1 from public.bal_cycles where document_id=p_id) and private.bal_count_context(p_patient,p_id,p_payload) is not null) then raise exception 'draft owner required' using errcode='42501';end if;
 perform pg_advisory_xact_lock(hashtextextended('stock:'||p_patient,0));
 select * into strict d from public.operational_documents where id=p_id for update;
 select * into e from public.document_events where actor_id=auth.uid() and idempotency_key=p_key;
 if found then if e.document_id<>p_id or e.body->'event'<>p_payload then raise exception 'idempotency conflict' using errcode='23505';end if;return public.operational_document(p_id);end if;
 if p_key is null or p_version is null or d.version<>p_version then raise exception 'stale document version' using errcode='P0001';end if;
 if not(d.status='draft' or p_recount and d.type='BAL' and d.status='submitted') or d.type='REQ' then raise exception 'only drafts or pending BAL may be revised';end if;
 if jsonb_typeof(p_payload) is distinct from 'object' or jsonb_typeof(p_payload->'lines') is distinct from 'array' or jsonb_array_length(p_payload->'lines') not between 1 and 1000 then raise exception 'invalid draft lines';end if;
 if d.type='ENT' and (not private.user_can(p_patient,(p_payload->>'recipientId')::uuid,'ent.receive') or (p_payload->>'recipientId')::uuid=d.created_by or coalesce(p_payload->>'source','') not in ('FAMILY','CARE_TEAM') or coalesce(p_payload->>'destination','') not in ('FAMILY','CARE_TEAM') or p_payload->>'source'=p_payload->>'destination') then raise exception 'invalid ENT recipient or custody';end if;
 delete from public.document_request_links where document_line_id in(select id from public.document_lines where document_id=p_id);
 delete from public.document_lines where document_id=p_id;
 for x in select value from jsonb_array_elements(p_payload->'lines') loop
 select * into p from public.care_recipient_products where care_recipient_id=p_patient and product_id=x->>'productId' and is_active;
 if not found then raise exception 'invalid patient catalogue product';end if;
 q:=(x->>'quantity')::numeric;
 if q is null or q<0 or (p_type<>'BAL' and q=0) or q>1000000000 or q<>round(q,p.quantity_decimals) then raise exception 'invalid product quantity';end if;
 insert into public.document_lines(document_id,care_recipient_id,product_id,name_snapshot,unit_snapshot,category_snapshot,quantity,approved_quantity,metadata)
 values(p_id,p_patient,p.product_id,p.name,p.unit,p.category::text,q,case when p_type='COM' and public.recipient_role(p_patient)='admin' then q else 0 end,
 case when p_type='BAL' then jsonb_build_object('expectedQuantity',private.stock_quantity(p_patient,p.product_id,'CARE_TEAM')) else coalesce(x->'metadata','{}') end) returning id into l_id;
 for r_id in select value::text::uuid from jsonb_array_elements_text(coalesce(x->'requisitionItemIds','[]')) loop
 if not exists(select 1 from public.requisition_items i join public.requisitions r on r.id=i.requisition_id where i.id=r_id and i.care_recipient_id=p_patient and private.effective_requisition_product(i.id)=p.product_id and r.status<>'cancelled') then raise exception 'invalid requisition line link';end if;
 insert into public.document_request_links values(l_id,r_id);
 end loop;
 end loop;
 if p_type='BAL' and (select count(*) from public.document_lines where document_id=p_id)<>(select count(*) from public.care_recipient_products where care_recipient_id=p_patient and is_active) then raise exception 'count every active catalogue product';end if;

 update public.operational_documents set payload=p_payload,recipient_id=case when type='ENT' then (p_payload->>'recipientId')::uuid else recipient_id end,version=version+1,
 workflow_data=case when type='BAL' then workflow_data||jsonb_build_object('referenceRevision',case when p_recount then private.team_revision(p_patient) else (workflow_data->>'referenceRevision')::bigint end,'countVersion',coalesce((workflow_data->>'countVersion')::integer,0)+1) else workflow_data end where id=p_id;
 perform private.record_document_event(p_id,lower(d.type)||case when p_recount then '.recount' else '.draft_updated' end,p_payload,p_key);
 return public.operational_document(p_id);
end;$function$

CREATE OR REPLACE FUNCTION public.v3_transition_requisition_status(p_requisition_id uuid, p_to_status requisition_status, p_reason text DEFAULT NULL::text)
 RETURNS requisitions
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$declare r public.requisitions;begin
 if p_to_status='delivered' then raise exception 'physical fulfillment is derived from ENT receipts';end if;
 r:=public.legacy_transition_requisition_status(p_requisition_id,p_to_status,p_reason);
 if exists(select 1 from public.operational_documents where id=r.id) then
 update public.operational_documents set status=r.status::text,version=version+1 where id=r.id;
 perform private.record_document_event(r.id,'req.status',jsonb_build_object('status',p_to_status,'reason',p_reason),gen_random_uuid());end if;
 return r;
end;$function$

CREATE OR REPLACE FUNCTION public.v4_accept_invitation(p_token_hash text)
 RETURNS care_recipient_memberships
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare i public.care_recipient_invitations;result public.care_recipient_memberships;begin
 if not exists(select 1 from auth.sessions where id=nullif(auth.jwt()->>'session_id','')::uuid and user_id=auth.uid() and (not_after is null or not_after>now())) then raise exception 'active Auth session required' using errcode='42501';end if;
 select * into i from public.care_recipient_invitations where token_hash=p_token_hash;
 if not found then raise exception 'invalid invitation' using errcode='42501';end if;
 perform pg_advisory_xact_lock(hashtextextended('stock:'||i.care_recipient_id,0));
 select * into i from public.care_recipient_invitations where token_hash=p_token_hash for update;
 if not found or not exists(select 1 from auth.users where id=auth.uid() and lower(email)=i.email and email_confirmed_at is not null) then raise exception 'invalid invitation' using errcode='42501';end if;
 if i.status<>'accepted' and (i.status<>'pending' or i.expires_at<=now() or not exists(select 1 from public.care_recipient_memberships m join public.profiles p on p.id=m.user_id where m.care_recipient_id=i.care_recipient_id and m.user_id=i.invited_by and m.status='active' and m.role='admin' and p.status='active')) then raise exception 'invalid or expired invitation' using errcode='42501';end if;
 insert into private.membership_authority values(pg_backend_pid(),txid_current(),i.care_recipient_id,auth.uid(),i.role,i.role<>'reader' and i.can_manage_stock,i.role<>'reader' and i.can_count_stock) on conflict do nothing;
 result:=public.v3_accept_invitation(p_token_hash);
 delete from private.membership_authority where backend_pid=pg_backend_pid() and transaction_id=txid_current() and care_recipient_id=i.care_recipient_id and user_id=auth.uid();return result;
end;$function$

CREATE OR REPLACE FUNCTION public.v4_admin_set_membership_status(p_care_recipient_id uuid, p_user_id uuid, p_status text)
 RETURNS care_recipient_memberships
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v public.care_recipient_memberships;
begin
  if not public.can_manage_recipient(p_care_recipient_id) then raise exception 'admin authorization required' using errcode='42501'; end if;
  if p_status is null or p_status not in ('active','revoked') then raise exception 'invalid membership status'; end if;
  update public.care_recipient_memberships set status=p_status where care_recipient_id=p_care_recipient_id and user_id=p_user_id returning * into v;
  if not found then raise exception 'membership not found'; end if;
  insert into public.audit_events(actor_id,action,entity_type,entity_id,metadata) values(auth.uid(),'membership.status.changed','care_recipient_membership',v.id,jsonb_build_object('care_recipient_id',p_care_recipient_id,'user_id',p_user_id,'status',p_status));
  return v;
end; $function$

CREATE OR REPLACE FUNCTION public.v4_admin_upsert_membership(p_care_recipient_id uuid, p_user_id uuid, p_role profile_role, p_can_manage_stock boolean, p_can_count_stock boolean)
 RETURNS care_recipient_memberships
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v public.care_recipient_memberships;
begin
  if not public.can_manage_recipient(p_care_recipient_id) then raise exception 'admin authorization required' using errcode='42501';end if;
  -- A local administrator can edit their established memberships. Adding an identity
  -- requires authenticated invitation acceptance, rather than account enumeration.
  if not public.is_global_administrator() and not exists(select 1 from public.care_recipient_memberships where care_recipient_id=p_care_recipient_id and user_id=p_user_id) then raise exception 'invitation acceptance required' using errcode='42501';end if;
  if p_role is null or not exists(select 1 from public.profiles where id=p_user_id and status='active') then raise exception 'invalid membership';end if;
  insert into public.care_recipient_memberships(care_recipient_id,user_id,role,can_manage_stock,can_count_stock)
  values(p_care_recipient_id,p_user_id,p_role,p_role<>'reader' and p_can_manage_stock,p_role<>'reader' and p_can_count_stock)
  on conflict(care_recipient_id,user_id) do update set role=excluded.role,can_manage_stock=excluded.can_manage_stock,can_count_stock=excluded.can_count_stock,status='active' returning * into v;
  insert into public.audit_events(actor_id,action,entity_type,entity_id,metadata) values(auth.uid(),'membership.updated','care_recipient_membership',v.id,jsonb_build_object('care_recipient_id',p_care_recipient_id,'user_id',p_user_id,'role',p_role));return v;
end; $function$

CREATE OR REPLACE FUNCTION public.v4_complete_notification_job(p_id uuid, p_worker_id uuid, p_state text, p_provider_reference text DEFAULT NULL::text, p_error text DEFAULT NULL::text)
 RETURNS requisition_notifications
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v public.requisition_notifications;
begin
  if not public.is_global_administrator() and coalesce(auth.role(),'')<>'service_role' then raise exception 'worker authorization required' using errcode='42501';end if;
  if p_state is null or p_state not in ('accepted','delivered','read','failed','pending','uncertain') then raise exception 'invalid notification result';end if;
  select * into v from public.requisition_notifications where id=p_id and leased_by=p_worker_id and state='processing' and lease_expires_at>now() for update;
  if not found then raise exception 'notification lease lost';end if;
  if v.channel='internal' and p_state='accepted' then raise exception 'internal notification requires delivered state';end if;
  update public.requisition_notifications set state=case when p_state='pending' and attempts>=5 then 'failed' else p_state end,
    provider_reference=coalesce(p_provider_reference,provider_reference),last_error=left(p_error,500),leased_by=null,lease_expires_at=null,
    next_attempt_at=now()+make_interval(secs=>least(3600,(30*power(2,attempts))::integer)),
    delivered_at=case when p_state in ('delivered','read') then now() else delivered_at end,read_at=case when p_state='read' then now() else read_at end
  where id=v.id returning * into v;return v;
end; $function$

CREATE OR REPLACE FUNCTION public.v4_configure_patient_access(p_patient uuid, p_kind text, p_change jsonb, p_key uuid, p_version integer, p_request_id uuid DEFAULT NULL::uuid, p_decision text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare s public.patient_settings;c public.access_change_requests;rid uuid;local_admin boolean:=public.can_manage_recipient(p_patient);x jsonb;begin
 if not local_admin and not public.is_global_administrator() then raise exception 'administrator authorization required' using errcode='42501';end if;
 if not exists(select 1 from public.care_recipients where id=p_patient) then raise exception 'patient required';end if;
 perform pg_advisory_xact_lock(hashtextextended('stock:'||p_patient,0));
 insert into public.patient_settings(care_recipient_id) values(p_patient) on conflict do nothing;
 select * into s from public.patient_settings where care_recipient_id=p_patient for update;
 if p_request_id is not null then
 select * into strict c from public.access_change_requests where id=p_request_id and care_recipient_id=p_patient for update;
 if not local_admin or c.proposed_by=auth.uid() then raise exception 'distinct patient administrator required' using errcode='42501';end if;
 if c.status<>'pending' then return to_jsonb(c);end if;
 if p_decision is null or p_decision not in ('approve','reject') then raise exception 'invalid decision';end if;
 if p_decision='approve' and s.version<>c.base_version then raise exception 'stale policy version' using errcode='P0001';end if;
 update public.access_change_requests set approved_by=auth.uid() where id=c.id;
 if p_decision='approve' then perform private.apply_access_change(c.id);
 else update public.access_change_requests set status='rejected',decided_at=now() where id=c.id;end if;
 return (select to_jsonb(q) from public.access_change_requests q where id=c.id);
 end if;
 if p_key is null then raise exception 'idempotency key required';end if;
 select * into c from public.access_change_requests where care_recipient_id=p_patient and idempotency_key=p_key;
 if found then
 if c.kind<>p_kind or c.proposed<>p_change or c.proposed_by<>auth.uid() then raise exception 'idempotency conflict' using errcode='23505';end if;
 return to_jsonb(c);end if;
 if p_version is null or p_version<>s.version then raise exception 'stale policy version' using errcode='P0001';end if;
 if jsonb_typeof(p_change) is distinct from 'object' or length(p_change::text)>64000 then raise exception 'invalid change';end if;
 if p_kind='settings' then
 if exists(select 1 from jsonb_object_keys(p_change) k where k not in ('balDay','balReview','balApprovers','balRequirement','whatsappSimpleAcceptance','scienceRequired','scienceRoles','scienceUsers','scienceRequirement','scienceByDispatch','scienceAutomatic','scienceWhatsApp','archiveDays','patientShortName','reminderHours','reminderRepeatHours','shareWaitSeconds','shiftReminder','balReminderUsers'))
 or p_change ? 'balDay' and p_change->'balDay'<>'null'::jsonb and (p_change->>'balDay')::integer not between 0 and 6
 or p_change ? 'balReview' and p_change->>'balReview' not in ('optional','required')
 or p_change ? 'balRequirement' and p_change->>'balRequirement' not in ('any','all')
 or p_change ? 'scienceRequirement' and p_change->>'scienceRequirement' not in ('any','all')
 or p_change ? 'balApprovers' and (jsonb_typeof(p_change->'balApprovers')<>'array' or jsonb_array_length(p_change->'balApprovers') not between 1 and 2 or exists(select 1 from jsonb_array_elements_text(p_change->'balApprovers') z where z not in ('family','supervisor')))
 or p_change ? 'scienceRoles' and (jsonb_typeof(p_change->'scienceRoles')<>'array' or exists(select 1 from jsonb_array_elements_text(p_change->'scienceRoles') z where z not in ('admin','family','supervisor','professional')))
 or p_change ? 'scienceUsers' and (jsonb_typeof(p_change->'scienceUsers')<>'array' or exists(select 1 from jsonb_array_elements_text(p_change->'scienceUsers') z where not exists(select 1 from public.care_recipient_memberships where care_recipient_id=p_patient and user_id=z::uuid and status='active')))
 or exists(select 1 from jsonb_each(p_change) z where z.key in ('whatsappSimpleAcceptance','scienceRequired','scienceByDispatch','scienceAutomatic','scienceWhatsApp') and jsonb_typeof(z.value)<>'boolean')
 or p_change ? 'archiveDays' and (p_change->>'archiveDays')::integer not between 1 and 365
 or p_change ? 'reminderHours' and (p_change->>'reminderHours')::integer not between 1 and 720
 or p_change ? 'reminderRepeatHours' and (p_change->>'reminderRepeatHours')::integer not between 1 and 720
 or p_change ? 'shareWaitSeconds' and (p_change->>'shareWaitSeconds')::integer not between 0 and 10
 or p_change ? 'patientShortName' and length(trim(p_change->>'patientShortName')) not between 1 and 60 then raise exception 'invalid patient settings';end if;
 if p_change ? 'balReminderUsers' and (jsonb_typeof(p_change->'balReminderUsers') is distinct from 'array' or jsonb_array_length(p_change->'balReminderUsers')>100 or exists(select 1 from jsonb_array_elements_text(p_change->'balReminderUsers') u where not private.member_can(p_patient,u::uuid,'bal.count'))) then raise exception 'invalid BAL reminder recipients';end if;
 if p_change ? 'shiftReminder' and (jsonb_typeof(p_change->'shiftReminder') is distinct from 'object' or jsonb_typeof(p_change->'shiftReminder'->'enabled') is distinct from 'boolean' or coalesce((p_change->'shiftReminder'->>'hour')::integer,-1) not between 0 and 23
 or jsonb_typeof(p_change->'shiftReminder'->'days') is distinct from 'array' or jsonb_typeof(p_change->'shiftReminder'->'userIds') is distinct from 'array'
 or exists(select 1 from jsonb_array_elements_text(p_change->'shiftReminder'->'days') d where d not in ('0','1','2','3','4','5','6'))
 or exists(select 1 from jsonb_array_elements_text(p_change->'shiftReminder'->'userIds') u where not private.member_can(p_patient,u::uuid,'consumption.report'))) then raise exception 'invalid shift reminder policy';end if;
 elsif p_kind='capability' then
 if not exists(select 1 from public.capability_definitions where code=p_change->>'capability')
 or (p_change->>'subjectUser' is null)=(p_change->>'subjectRole' is null)
 or not(p_change ? 'enabled') or p_change->'enabled'<>'null'::jsonb and jsonb_typeof(p_change->'enabled')<>'boolean'
 or p_change->>'subjectRole' is not null and p_change->>'subjectRole' not in ('admin','family','supervisor','professional','reader') then raise exception 'invalid capability override';end if;
 if p_change->>'subjectUser' is not null and not exists(select 1 from public.care_recipient_memberships where care_recipient_id=p_patient and user_id=(p_change->>'subjectUser')::uuid and status='active') then raise exception 'invalid patient member';end if;
 if p_change->>'capability'='access.manage' then raise exception 'administrator governance cannot be overridden';end if;
 elsif p_kind='membership' then
 if p_change->>'role' is null or p_change->>'role' not in ('admin','family','supervisor','professional','reader') or not exists(select 1 from public.profiles where id=(p_change->>'userId')::uuid and status='active') then raise exception 'invalid membership';end if;
 elsif p_kind='notification_rule' then
 if p_change->>'event' is null or p_change->>'role' not in ('admin','family','supervisor','professional','reader') or jsonb_typeof(p_change->'channels') is distinct from 'array' then raise exception 'invalid notification rule';end if;
 if p_change ? 'mode' and p_change->>'mode' not in ('required','optional','silent') then raise exception 'invalid notification mode';end if;
 elsif p_kind='administration' then
 if p_change->>'operation' is null or p_change->>'operation' not in ('recipient','product','adoptProduct','membershipStatus','alertRule','notificationRecipient') or jsonb_typeof(p_change->'args') is distinct from 'object' then raise exception 'invalid administrative proposal';end if;
 else raise exception 'invalid access change';end if;
 insert into public.access_change_requests(care_recipient_id,kind,proposed,base_version,proposed_by,idempotency_key)
 values(p_patient,p_kind,p_change,s.version,auth.uid(),p_key) returning id into rid;
 if local_admin then
 if p_kind='capability' and p_change->'enabled'='null'::jsonb then
 delete from public.capability_overrides where care_recipient_id=p_patient and capability=p_change->>'capability'
 and (subject_role=p_change->>'subjectRole' or subject_user=(p_change->>'subjectUser')::uuid);
 update public.patient_settings set version=version+1,updated_at=now() where care_recipient_id=p_patient;
 update public.access_change_requests set status='applied',decided_at=now() where id=rid;
 else perform private.apply_access_change(rid);end if;
 end if;
 insert into public.audit_events(actor_id,action,entity_type,entity_id,metadata) values(auth.uid(),case when local_admin then 'access.changed.local' else 'access.proposed.global' end,'access_change',rid,jsonb_build_object('care_recipient_id',p_patient,'kind',p_kind));
 return (select to_jsonb(q) from public.access_change_requests q where id=rid);
end;$function$

CREATE OR REPLACE FUNCTION public.v4_lifecycle_schedule()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare s public.requisition_lifecycle;d public.operational_documents;n integer:=0;archived integer:=0;locked_patients uuid[];patient_id uuid;begin
 if coalesce(auth.jwt()->>'role','')<>'service_role' then raise exception 'worker authorization required' using errcode='42501';end if;
 perform pg_advisory_xact_lock(hashtextextended('hca:operational-scheduler',0));
 select array_agg(id order by id) into locked_patients from (select care_recipient_id id,min(due) from (
 select care_recipient_id,next_reminder_at due from public.requisition_lifecycle where archived_at is null and not exists(select 1 from public.requisitions r where r.id=requisition_id and r.is_historical) and ((completed_at is null or not coalesce(private.science_satisfied(requisition_id),false)) and next_reminder_at<=now() or completed_at is not null and not manual_archive_required and coalesce(private.science_satisfied(requisition_id),false) and now()>=completed_at+make_interval(days=>coalesce((policy->>'archiveDays')::integer,7)))
 union all select care_recipient_id,updated_at due from public.operational_documents where type='ENT' and status='pending_receipt' and updated_at<now()-interval '24 hours') x group by care_recipient_id order by min(due) limit 25) x;
 for patient_id in select unnest(locked_patients) order by 1 loop perform pg_advisory_xact_lock(hashtextextended('stock:'||patient_id,0));end loop;
 for s in select * from public.requisition_lifecycle where archived_at is null and not exists(select 1 from public.requisitions r where r.id=requisition_id and r.is_historical) and ((completed_at is null or not coalesce(private.science_satisfied(requisition_id),false)) and next_reminder_at<=now() or completed_at is not null and not manual_archive_required and coalesce(private.science_satisfied(requisition_id),false) and now()>=completed_at+make_interval(days=>coalesce((policy->>'archiveDays')::integer,7))) and care_recipient_id=any(locked_patients) order by next_reminder_at limit 100 for update skip locked loop
 perform private.refresh_requisition_lifecycle(s.requisition_id);
 select * into s from public.requisition_lifecycle where requisition_id=s.requisition_id;
 select * into d from public.operational_documents where id=s.requisition_id for update;
 if d.status='cancelled' then continue;end if;
 if s.completed_at is not null and not s.manual_archive_required and coalesce(private.science_satisfied(d.id),false)
 and now()>=s.completed_at+make_interval(days=>coalesce((s.policy->>'archiveDays')::integer,7)) then
 update public.requisition_lifecycle set archived_at=now(),archive_reason='Prazo automático após conclusão e ciência válidas' where requisition_id=d.id;
 update public.operational_documents set version=version+1 where id=d.id;
 perform private.record_document_event(d.id,'req.archived.automatic',jsonb_build_object('scheduled',true),gen_random_uuid());archived:=archived+1;
 elsif (s.completed_at is null or not coalesce(private.science_satisfied(d.id),false)) and s.next_reminder_at<=now() then
 update public.requisition_lifecycle set next_reminder_at=now()+make_interval(hours=>coalesce((s.policy->>'reminderRepeatHours')::integer,24)),reminders=reminders+1 where requisition_id=d.id;
 update public.operational_documents set version=version+1 where id=d.id;
 perform private.record_document_event(d.id,'req.reminder',jsonb_build_object('sciencePending',not coalesce(private.science_satisfied(d.id),false)),gen_random_uuid());n:=n+1;
 end if;end loop;
 for d in select * from public.operational_documents where type='ENT' and status='pending_receipt' and care_recipient_id=any(locked_patients)
 and updated_at<now()-interval '24 hours' order by updated_at limit 50 for update skip locked loop
 update public.operational_documents set version=version+1,updated_at=now() where id=d.id;
 perform private.record_document_event(d.id,'ent.reminder','{"scheduled":true}',gen_random_uuid());n:=n+1;
 end loop;
 insert into private.scheduler_health(singleton,last_run,processed) values(true,now(),n+archived) on conflict(singleton) do update set last_run=now(),processed=excluded.processed;
 return jsonb_build_object('reminders',n,'archived',archived);
end;$function$

CREATE OR REPLACE FUNCTION public.v4_review_archive_requisition(p_id uuid, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare s public.requisition_lifecycle;begin
 select * into strict s from public.requisition_lifecycle where requisition_id=p_id;
 perform private.require_cap(s.care_recipient_id,'req.archive');
 perform pg_advisory_xact_lock(hashtextextended('stock:'||s.care_recipient_id,0));
 select * into strict s from public.requisition_lifecycle where requisition_id=p_id for update;
 if length(trim(coalesce(p_reason,''))) not between 3 and 1000 then raise exception 'archive reason required';end if;
 perform private.refresh_requisition_lifecycle(p_id);
 select * into s from public.requisition_lifecycle where requisition_id=p_id;
 if s.archived_at is not null then return public.requisition_progress(p_id);end if;
 if s.completed_at is null then raise exception 'operational completion required';end if;
 update public.requisition_lifecycle set archived_at=now(),archived_by=auth.uid(),archive_reason=trim(p_reason) where requisition_id=p_id;
 update public.operational_documents set version=version+1 where id=p_id;
 perform private.record_document_event(p_id,'req.archived.manual',jsonb_build_object('reason',trim(p_reason),'scienceSatisfied',private.science_satisfied(p_id)),gen_random_uuid());
 return public.requisition_progress(p_id);
end;$function$

CREATE OR REPLACE FUNCTION public.v4_review_patient_access(p_patient uuid, p_kind text, p_change jsonb, p_key uuid, p_version integer, p_request_id uuid DEFAULT NULL::uuid, p_decision text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare change jsonb:=p_change;kind text:=p_kind;item record;elements integer;begin
 if not public.can_manage_recipient(p_patient) and not public.is_global_administrator() then raise exception 'administrator authorization required' using errcode='42501';end if;
 if p_request_id is not null then select proposed,c.kind into change,kind from public.access_change_requests c where c.id=p_request_id and c.care_recipient_id=p_patient;end if;
 if kind='settings' then
 for item in select key,value from jsonb_each(change) loop
 if item.key in ('balReview','balRequirement','scienceRequirement','patientShortName') and (jsonb_typeof(item.value) is distinct from 'string' or length(trim(item.value#>>'{}'))=0) then raise exception 'invalid patient settings';end if;
 if item.key in ('archiveDays','reminderHours','reminderRepeatHours','shareWaitSeconds') or item.key='balDay' and item.value<>'null'::jsonb then
 if jsonb_typeof(item.value) is distinct from 'number' or (item.value#>>'{}')!~'^[0-9]+$' then raise exception 'integer patient setting required';end if;end if;
 if item.key in ('balApprovers','scienceRoles','scienceUsers','balReminderUsers') then
 if jsonb_typeof(item.value) is distinct from 'array' then raise exception 'array patient setting required';end if;
 elements:=jsonb_array_length(item.value);
 if elements>100 or exists(select 1 from jsonb_array_elements(item.value) e where jsonb_typeof(e) is distinct from 'string') or (select count(distinct e) from jsonb_array_elements_text(item.value) e)<>elements then raise exception 'unique string settings required';end if;end if;
 if item.key='shiftReminder' then
 if jsonb_typeof(item.value) is distinct from 'object' or exists(select 1 from jsonb_object_keys(item.value) k where k not in ('enabled','hour','days','userIds'))
 or jsonb_typeof(item.value->'hour') is distinct from 'number' or coalesce(item.value->>'hour','')!~'^[0-9]+$' then raise exception 'invalid shift settings';end if;
 if jsonb_typeof(item.value->'days') is distinct from 'array' or jsonb_typeof(item.value->'userIds') is distinct from 'array' then raise exception 'invalid shift recipients or days';end if;
 if exists(select 1 from jsonb_array_elements(item.value->'days') e where jsonb_typeof(e) is distinct from 'string') or exists(select 1 from jsonb_array_elements(item.value->'userIds') e where jsonb_typeof(e) is distinct from 'string') then raise exception 'invalid shift values';end if;
 end if;
 end loop;
 elsif kind='capability' and change->>'capability'='access.manage' then raise exception 'administrator governance cannot be overridden' using errcode='23514';
 elsif kind='notification_rule' and change ? 'mode' and (jsonb_typeof(change->'mode') is distinct from 'string' or change->>'mode' not in ('required','optional','silent')) then raise exception 'invalid notification mode';end if;
 return public.v4_configure_patient_access(p_patient,p_kind,p_change,p_key,p_version,p_request_id,p_decision);
end;$function$

CREATE OR REPLACE FUNCTION public.v4_validate_notification_job(p_id uuid, p_worker_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare n public.requisition_notifications;d public.operational_documents;e public.stock_alert_events;r public.consumption_reports;rem public.operational_reminders;allowed boolean:=false;begin
 if not public.is_global_administrator() and coalesce(auth.jwt()->>'role','')<>'service_role' then raise exception 'worker authorization required' using errcode='42501';end if;
 select * into n from public.requisition_notifications where id=p_id and leased_by=p_worker_id and state='processing' and lease_expires_at>now() for update;if not found then return false;end if;
 if n.document_id is not null then select * into d from public.operational_documents where id=n.document_id;allowed:=private.member_can(n.care_recipient_id,n.recipient_user_id,lower(d.type)||'.read');
 elsif n.requisition_id is not null then allowed:=private.member_can(n.care_recipient_id,n.recipient_user_id,'req.read');
 elsif n.alert_event_id is not null then select * into e from public.stock_alert_events where id=n.alert_event_id;allowed:=e.state='open' and private.member_can(n.care_recipient_id,n.recipient_user_id,case when e.location='FAMILY' then 'stock.family.read' else 'stock.team.read' end);
 elsif n.consumption_report_id is not null then select * into r from public.consumption_reports where id=n.consumption_report_id;allowed:=private.member_can(n.care_recipient_id,n.recipient_user_id,'consumption.report') and (r.reported_by=n.recipient_user_id or private.member_can(n.care_recipient_id,n.recipient_user_id,'consumption.confirm'));
 elsif n.reminder_id is not null then select * into rem from public.operational_reminders where id=n.reminder_id;allowed:=rem.user_id=n.recipient_user_id and rem.acknowledged_at is null and private.reminder_recipient_can(rem.id,n.recipient_user_id);end if;
 if n.channel='whatsapp' then allowed:=allowed and coalesce((select (notification_preferences->>'whatsapp')::boolean from public.profiles where id=n.recipient_user_id),false)
 and exists(select 1 from public.verified_phones v join auth.users u on u.id=v.user_id where v.user_id=n.recipient_user_id and u.phone_confirmed_at is not null and '+'||ltrim(u.phone,'+')=v.phone and ltrim(v.phone,'+')=ltrim(n.destination,'+'));end if;
 if coalesce(allowed,false) then return true;end if;
 update public.requisition_notifications set state='cancelled',last_error='RECIPIENT_REVOKED_OR_CONTACT_UNVERIFIED',leased_by=null,lease_expires_at=null where id=n.id;return false;
end;$function$

CREATE OR REPLACE FUNCTION public.validate_notification_job(p_id uuid, p_worker_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare n public.requisition_notifications;r public.notification_event_rules;begin
 if not public.v4_validate_notification_job(p_id,p_worker_id) then return false;end if;
 select * into strict n from public.requisition_notifications where id=p_id for update;
 if n.channel='whatsapp' and n.event_key is not null then
 select * into r from public.notification_event_rules where care_recipient_id=n.care_recipient_id and subject_role=(select role::text from public.care_recipient_memberships where care_recipient_id=n.care_recipient_id and user_id=n.recipient_user_id) and event=case n.event_key when 'com.submit' then 'com.issued' when 'ent.submit' then 'ent.issued' else n.event_key end;
 if not private.whatsapp_event_supported(n.event_key) or r.event is not null and (not('whatsapp'=any(r.channels)) or r.mode='silent') then
 update public.requisition_notifications set state='cancelled',last_error='EVENT_DISABLED',leased_by=null,lease_expires_at=null where id=n.id;return false;end if;
 end if;return true;
end;$function$

CREATE OR REPLACE FUNCTION public.validated_legacy_patient_access(p_patient uuid, p_kind text, p_change jsonb, p_key uuid, p_version integer, p_request_id uuid DEFAULT NULL::uuid, p_decision text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare s public.patient_settings;c public.access_change_requests;critical_change boolean;v_id uuid;
begin
 perform private.require_cap(p_patient,'access.manage');
 insert into public.patient_settings(care_recipient_id) values(p_patient) on conflict do nothing;
 select * into s from public.patient_settings where care_recipient_id=p_patient for update;
 if p_request_id is not null then
 select * into strict c from public.access_change_requests where id=p_request_id and care_recipient_id=p_patient for update;
 if c.status<>'pending' then return to_jsonb(c);end if;
 if c.proposed_by=auth.uid() or not exists(select 1 from public.care_recipient_memberships where care_recipient_id=p_patient and user_id=auth.uid() and role='admin' and status='active')
 or (select count(*) from public.care_recipient_memberships m join public.profiles p on p.id=m.user_id where m.care_recipient_id=p_patient and m.role='admin' and m.status='active' and p.status='active')<2 then raise exception 'distinct patient administrator required' using errcode='42501';end if;
 if s.version<>c.base_version then raise exception 'stale policy version' using errcode='P0001';end if;
 if p_decision not in ('approve','reject') then raise exception 'invalid decision';end if;
 update public.access_change_requests set approved_by=auth.uid() where id=c.id;
 if p_decision='approve' then perform private.apply_access_change(c.id);else update public.access_change_requests set status='rejected',decided_at=now() where id=c.id;end if;
 return (select to_jsonb(q) from public.access_change_requests q where id=c.id);
 end if;
 select * into c from public.access_change_requests where care_recipient_id=p_patient and idempotency_key=p_key;
 if found then if c.kind<>p_kind or c.proposed<>p_change then raise exception 'idempotency conflict' using errcode='23505';end if;return to_jsonb(c);end if;
 if p_key is null or p_version is null or p_version<>s.version then raise exception 'stale policy version' using errcode='P0001';end if;
 if p_kind='settings' then
 if exists(select 1 from jsonb_object_keys(p_change) k where k not in ('balDay','balReview','balApprovers','balRequirement','whatsappSimpleAcceptance'))
 or p_change ? 'balDay' and p_change->'balDay'<>'null'::jsonb and (p_change->>'balDay')::integer not between 0 and 6
 or p_change ? 'balReview' and p_change->>'balReview' not in ('optional','required')
 or p_change ? 'balRequirement' and p_change->>'balRequirement' not in ('any','all')
 or p_change ? 'balApprovers' and (jsonb_typeof(p_change->'balApprovers')<>'array' or jsonb_array_length(p_change->'balApprovers') not between 1 and 2 or exists(select 1 from jsonb_array_elements_text(p_change->'balApprovers') z where z not in ('family','supervisor')))
 or p_change ? 'whatsappSimpleAcceptance' and jsonb_typeof(p_change->'whatsappSimpleAcceptance')<>'boolean' then raise exception 'invalid settings';end if;
 critical_change:=(p_change ? 'balReview' and p_change->>'balReview' is distinct from s.settings->>'balReview') or p_change ? 'balApprovers' or p_change ? 'balRequirement' or coalesce((p_change->>'whatsappSimpleAcceptance')::boolean,false);
 elsif p_kind='capability' then
 if not exists(select 1 from public.capability_definitions where code=p_change->>'capability') or jsonb_typeof(p_change->'enabled') is distinct from 'boolean'
 or (p_change->>'subjectUser' is null)=(p_change->>'subjectRole' is null) then raise exception 'invalid capability override';end if;
 if p_change->>'subjectUser' is not null and not exists(select 1 from public.care_recipient_memberships where care_recipient_id=p_patient and user_id=(p_change->>'subjectUser')::uuid and status='active') then raise exception 'invalid patient member';end if;
 critical_change:=(p_change->>'enabled')::boolean and exists(select 1 from public.capability_definitions where code=p_change->>'capability' and critical);
 elsif p_kind='membership' then critical_change:=true;
 else raise exception 'invalid access change';end if;
 insert into public.access_change_requests(care_recipient_id,kind,proposed,base_version,proposed_by,idempotency_key) values(p_patient,p_kind,p_change,s.version,auth.uid(),p_key) returning id into v_id;
 if not critical_change then perform private.apply_access_change(v_id);end if;
 insert into public.audit_events(actor_id,action,entity_type,entity_id,metadata) values(auth.uid(),case when critical_change then 'access.proposed' else 'access.changed' end,'access_change',v_id,jsonb_build_object('care_recipient_id',p_patient,'kind',p_kind));
 return (select to_jsonb(q) from public.access_change_requests q where id=v_id);
end;$function$

CREATE OR REPLACE FUNCTION public.verified_legacy_whatsapp_receipt(p_provider_id text, p_phone text, p_hash text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare c public.whatsapp_challenges;d public.operational_documents;claims text;sub text;result jsonb;begin
 if coalesce(auth.role(),'')<>'service_role' then raise exception 'signed webhook worker required' using errcode='42501';end if;
 if p_provider_id is null or length(p_provider_id)>500 or p_phone!~'^[+]?[1-9][0-9]{7,14}$' or p_hash!~'^[a-f0-9]{64}$' then raise exception 'invalid receipt challenge';end if;
 perform pg_advisory_xact_lock(hashtextextended('inbound:'||p_provider_id,0));
 if exists(select 1 from public.inbound_messages where provider_id=p_provider_id) then return jsonb_build_object('duplicate',true);end if;
 select * into c from public.whatsapp_challenges where token_hash=p_hash;
 if not found then return jsonb_build_object('accepted',false);end if;
 select * into d from public.operational_documents where id=c.document_id;
 perform pg_advisory_xact_lock(hashtextextended('stock:'||d.care_recipient_id,0));
 select * into c from public.whatsapp_challenges where id=c.id for update;
 select * into d from public.operational_documents where id=c.document_id for update;
 if c.used_at is not null or c.expires_at<=now() or c.phone<>'+'||ltrim(p_phone,'+') or d.recipient_id<>c.recipient_id or d.version<>c.document_version or d.status<>'pending_receipt'
 or not private.user_can(d.care_recipient_id,c.recipient_id,'ent.receive') or not exists(select 1 from public.verified_phones v join auth.users u on u.id=v.user_id where v.user_id=c.recipient_id and v.phone=c.phone and '+'||ltrim(u.phone,'+')=c.phone and u.phone_confirmed_at is not null)
 or not coalesce((select (settings->>'whatsappSimpleAcceptance')::boolean from public.patient_settings where care_recipient_id=d.care_recipient_id),false) then
 insert into public.inbound_messages values(p_provider_id,encode(extensions.digest(p_phone,'sha256'),'hex'),'receipt','rejected',now());return jsonb_build_object('accepted',false);end if;
 claims:=current_setting('request.jwt.claims',true);sub:=current_setting('request.jwt.claim.sub',true);
 perform set_config('request.jwt.claims',jsonb_build_object('sub',c.recipient_id,'role','authenticated')::text,true);
 perform set_config('request.jwt.claim.sub',c.recipient_id::text,true);
 result:=public.supply_document_command(d.id,'receive',jsonb_build_object('divergences','[]'::jsonb,'securityLevel','verified_phone_one_time_challenge','providerId',p_provider_id),c.id,d.version);
 perform set_config('request.jwt.claims',coalesce(claims,''),true);perform set_config('request.jwt.claim.sub',coalesce(sub,''),true);
 update public.whatsapp_challenges set used_at=now() where id=c.id;
 insert into public.inbound_messages values(p_provider_id,encode(extensions.digest(p_phone,'sha256'),'hex'),'receipt','processed',now());
 return jsonb_build_object('accepted',true,'documentId',d.id);
end;$function$
